      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = STYLE_URL;
      link.dataset.dolopawsMaplibre = VERSION;
      link.onload = resolve;
      link.onerror = () => reject(new Error('Map styles could not be loaded.'));
      document.head.appendChild(link);
