      ownerId,
      trailId:completion.trailId,
      response:input.response,
      waterAccuracy,
      hazards,
      ...observations(input),
      missingRestriction:typeof input.missingRestriction === 'boolean'
        ? input.missingRestriction
        : null,
      recordedHikePresent:true,
      offlinePackageUsed:!!input.offlinePackageUsed,
