// ---- hike-mode.js ----
/**
 * hike-mode.js, "Start hike" companion for the trail detail page.
 *
 * Turns the trail map into an on-trail companion: live position snapped to
 * the route, progress readout (km walked, next water / rifugio ahead),
 * off-route warning, and a screen wake lock so the phone doesn't sleep
 * mid-hike.
 *
 * Everything works from data already on the trail object (path, distance,
 * rifugi, waterSources), no network calls, so the safety features keep
 * working even when the signal drops in a valley. Only the map tiles need
 * connectivity, and GPS itself is satellite-based and works offline.
 *
 * Usage: initHikeMode(map, trail) inside trail.js's map 'load' handler,
 * after the route path has been added. Include this file in trail.html
 * BEFORE trail.js.
 */

/**
 * Where along the walk a position on the drawn line is.
 *
 * For most shapes the line is the walk, and position is the fraction along it
 * times the stated distance. A there-and-back is drawn once and walked twice:
 * the line is one leg, so the fraction scales by half the distance on the way
 * out and mirrors into the second half on the way back. Scaling by the full
 * distance put the walker at the finish the moment they reached the
 * turnaround -- 5.5 km at Rifugio Nuvolau, with the whole descent to come.
 *
 * Pure, so the arithmetic can be checked without a GPS or a map.
 */
function hikeRoutePositionKm(input){
  const totalMeters = Number(input && input.totalMeters) || 1;
  const statedKm = Number(input && input.statedKm) || 0;
  const routeProgressM = Number(input && input.routeProgressM) || 0;
  const outAndBack = !!(input && input.outAndBack);
  const furthestRouteM = Number(input && input.furthestRouteM) || 0;
  const returnMarginM = Number(input && input.returnMarginM) || 150;
  const legKm = outAndBack ? statedKm / 2 : statedKm;
  const alongLegKm = (routeProgressM / totalMeters) * legKm;
  const returning = outAndBack && (furthestRouteM - routeProgressM) > returnMarginM;
  return returning ? Math.max(0, statedKm - alongLegKm) : alongLegKm;
}

function initHikeMode(map, trail, options){
  if (!('geolocation' in navigator)) return; // no GPS, don't show the button
  if (!Array.isArray(trail.path) || trail.path.length < 2) return;

  const container = (options && options.container) || (map && map.getContainer());
  if(!container) return;
  container.style.position = container.style.position || 'relative';

  // ---- Precompute cumulative distance along the path (meters) -------------
  const M_PER_DEG = 111000;
  function metersBetween(aLat, aLng, bLat, bLng){
    const dLat = (bLat - aLat) * M_PER_DEG;
    const dLng = (bLng - aLng) * M_PER_DEG * Math.cos(((aLat + bLat) / 2) * Math.PI / 180);
    return Math.hypot(dLat, dLng);
  }
  const cum = [0];
  for (let i = 1; i < trail.path.length; i++){
    cum.push(cum[i - 1] + metersBetween(
      trail.path[i - 1][0], trail.path[i - 1][1],
      trail.path[i][0], trail.path[i][1]));
  }
  const totalMeters = cum[cum.length - 1] || 1;
  // Route-position consumers such as the elevation profile use the trail's
  // stated length. Distance walked is accumulated separately from GPS fixes.
  const statedKm = trail.distance || totalMeters / 1000;
  // A there-and-back is drawn once and walked twice, so the line is one leg of
  // the stated distance. Scaling position by the full distance put the walker
  // at the finish the moment they reached the turnaround -- 5.5 km at Rifugio
  // Nuvolau, with the whole descent still to come.
  const outAndBack = trail.routeShape === 'out-and-back';
  // Declared shape wins over guessing from the ends. A there-and-back whose
  // line is later completed closes on itself, and closure alone would then
  // read it as a loop and switch off the next-water and next-hut readouts.
  const isLoop = trail.routeShape
    ? trail.routeShape === 'loop'
    : metersBetween(
      trail.path[0][0], trail.path[0][1],
      trail.path[trail.path.length - 1][0], trail.path[trail.path.length - 1][1]
    ) <= 75;
  // How far out the walk has reached, so the return leg can be told from the
  // outbound one. Both are the same line in the same direction of travel.
  let furthestRouteM = 0;
  const RETURN_MARGIN_M = 150;

  // ---- UI elements ---------------------------------------------------------
  const startBtn = document.createElement('button');
  const hikeLabel = (key, fallback) => {
    const text = window.t ? window.t(key) : fallback;
    return String(text || fallback).replace(/^\s*🐾\s*/, '');
  };
  const hikeButtonHtml = label => `<svg viewBox="0 0 24 24" aria-hidden="true" style="width:16px;height:16px;vertical-align:-3px;margin-right:6px;fill:currentColor;"><path d="M12 18.2c-2.4 0-4.2-1.5-4.2-3.6 0-1.4 1.1-2.5 2.5-2.5.7 0 1.2.3 1.7.7.5-.4 1-.7 1.7-.7 1.4 0 2.5 1.1 2.5 2.5 0 2.1-1.8 3.6-4.2 3.6Z"></path><circle cx="6.7" cy="10.4" r="1.7"></circle><circle cx="10.2" cy="8" r="1.7"></circle><circle cx="13.8" cy="8" r="1.7"></circle><circle cx="17.3" cy="10.4" r="1.7"></circle></svg>${label}`;
  startBtn.type = 'button';
  startBtn.id = 'mapStartHikeBtn';
  startBtn.innerHTML = hikeButtonHtml(hikeLabel('hike.start', 'Start hike'));
  startBtn.style.cssText = 'position:absolute;top:10px;left:10px;z-index:6;padding:9px 18px;border-radius:14px;background:var(--ink);color:#fff;border:none;font-size:12.5px;font-weight:700;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.3);';
  container.appendChild(startBtn);

  const pauseBtn = document.createElement('button');
  pauseBtn.type = 'button';
  pauseBtn.id = 'mapPauseHikeBtn';
  pauseBtn.textContent = hikeLabel('hike.pause', 'Pause');
  pauseBtn.hidden = true;
  pauseBtn.style.cssText = 'position:absolute;top:10px;left:132px;z-index:6;padding:9px 14px;border-radius:14px;background:#fff;color:var(--ink);border:1px solid rgba(46,64,52,.2);font-size:12.5px;font-weight:700;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.2);';
  container.appendChild(pauseBtn);

  const panel = document.createElement('div');
  panel.id = 'mapHikeStatus';
  panel.setAttribute('role', 'group');
  panel.setAttribute('aria-label', 'Live hike details');
  panel.style.cssText = 'position:absolute;bottom:10px;left:50%;transform:translateX(-50%);z-index:6;max-width:92%;padding:10px 16px;border-radius:12px;background:rgba(46,64,52,.94);color:#fff;font-size:12.5px;font-weight:600;box-shadow:0 2px 10px rgba(0,0,0,.35);display:none;text-align:center;line-height:1.5;';
  container.appendChild(panel);

  const statusAnnouncer = document.createElement('div');
  statusAnnouncer.className = 'sr-only';
  statusAnnouncer.setAttribute('role', 'status');
  statusAnnouncer.setAttribute('aria-live', 'polite');
  statusAnnouncer.setAttribute('aria-atomic', 'true');
  container.appendChild(statusAnnouncer);

  function announceStatus(message){
    statusAnnouncer.textContent = String(message || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  const banner = document.createElement('div');
  banner.id = 'mapHikeOffRoute';
  banner.setAttribute('role', 'group');
  banner.setAttribute('aria-label', 'Off-route warning');
  banner.textContent = window.t ? window.t('hike.offRoute') : '⚠️ Off route';
  banner.style.cssText = 'position:absolute;top:10px;left:50%;transform:translateX(-50%);z-index:7;width:max-content;max-width:min(92%,520px);padding:9px 16px;border-radius:12px;background:#9C3A25;color:#fff;font-size:12.5px;font-weight:700;line-height:1.4;text-align:center;box-shadow:0 2px 10px rgba(0,0,0,.35);display:none;';
  container.appendChild(banner);

  const urgentAnnouncer = document.createElement('div');
  urgentAnnouncer.className = 'sr-only';
  urgentAnnouncer.setAttribute('role', 'alert');
  urgentAnnouncer.setAttribute('aria-live', 'assertive');
  urgentAnnouncer.setAttribute('aria-atomic', 'true');
  container.appendChild(urgentAnnouncer);

  const rejoinBtn = document.createElement('button');
  rejoinBtn.type = 'button';
  rejoinBtn.id = 'mapHikeRejoinBtn';
  rejoinBtn.textContent = hikeLabel('hike.rejoinAction', 'Find closest trail point');
  rejoinBtn.hidden = true;
  rejoinBtn.style.cssText = 'position:absolute;bottom:100px;left:50%;transform:translateX(-50%);z-index:8;padding:10px 16px;border-radius:14px;background:#1677ff;color:#fff;border:2px solid #fff;font-size:12.5px;font-weight:800;cursor:pointer;box-shadow:0 3px 12px rgba(0,0,0,.35);white-space:nowrap;';
  container.appendChild(rejoinBtn);

  // ---- State ---------------------------------------------------------------
  let active = false;
  let watchId = null;
  let lastTileError = 0;   // last failed tile/style fetch, signals the map may grey out
  let wakeLock = null;
  let lastIdx = 0;          // last snapped path index, used for continuity
  let offRouteStreak = 0;   // consecutive fixes far from the route
  let offRouteSince = null; // first fix in the current sustained off-route run
  let announcedOffRoute = false;
  let firstFix = true;
  let hikeStartRecorded = false;
  let hikeStartedAt = null;
  let lastKnownKm = 0;      // actual distance walked since Start, for stats
  let lastValidFixAt = null;
  let distanceTracker = window.DoloPawsHikeDistance
    ? window.DoloPawsHikeDistance.create(0)
    : null;
  let latestFix = null;
  let latestAssessment = null;
  let latestRouteDistanceM = null;
  let manualRejoinActive = false;
  let durableSession = null;
  let completionRetry = null;
  const rejoinRoute = trail.path.map(point => ({ lat: point[0], lng: point[1] }));
  let footpathGraph = null;
  const routedTrailIds = new Set(['lago-carezza', 'alpe-siusi']);
  const rejoinSupported = routedTrailIds.has(trail.id) && !!window.DoloPawsFootpathRouter;
  let footpathGraphState = rejoinSupported ? 'loading' : 'unsupported';

  function updateRejoinControl(){
    if(!active || !rejoinSupported){
      rejoinBtn.hidden = true;
      return;
    }
    rejoinBtn.hidden = false;
    rejoinBtn.disabled = true;
    rejoinBtn.style.opacity = '.78';
    if(!latestFix){
      rejoinBtn.textContent = hikeLabel('hike.rejoinWaitingGps', 'Route me to trail · waiting for GPS');
      return;
    }
    if(!latestAssessment || !latestAssessment.usableForProgress){
      rejoinBtn.textContent = hikeLabel('hike.rejoinWeakGps', 'Route me to trail · improve GPS signal');
      return;
    }
    if(latestRouteDistanceM > 1500){
      rejoinBtn.textContent = hikeLabel('hike.rejoinTooFar', 'Rejoin available within 1.5 km');
      return;
    }
    if(footpathGraphState === 'loading'){
      rejoinBtn.textContent = hikeLabel('hike.rejoinLoading', 'Loading rejoin route…');
      return;
    }
    if(!footpathGraph){
      rejoinBtn.textContent = hikeLabel('hike.rejoinNoMap', 'No mapped rejoin path available');
      return;
    }
    rejoinBtn.disabled = false;
    rejoinBtn.style.opacity = '1';
    rejoinBtn.textContent = hikeLabel('hike.rejoinAction', 'Route me to the trail');
  }

  if(rejoinSupported){
    fetch(`offline/packages/${encodeURIComponent(trail.id)}/footpath-network.json`)
      .then(response => response.ok ? response.json() : null)
      .then(graph => {
        if(graph && window.DoloPawsFootpathRouter.validateGraph(graph)){
          footpathGraph = graph;
          footpathGraphState = 'ready';
        }else{
          footpathGraphState = 'unavailable';
        }
        updateRejoinControl();
      })
      .catch(() => {
        footpathGraphState = 'unavailable';
        updateRejoinControl();
      });
  }

  function keepSessionResult(result){
    if(result && result.session) durableSession = result.session;
    return !!(result && result.ok);
  }

  function beginDurableSession(){
    if(!window.DoloPawsHikeSession) return;
    const user = window.DoloPawsAuth && window.DoloPawsAuth.currentUser;
    keepSessionResult(window.DoloPawsHikeSession.create({
      trailId: trail.id,
      packageId: trail.offlinePackageId || trail.packageId || `dolopaws-trail:${trail.id}`,
      ownerId: user && user.uid || null,
      startedAt: hikeStartedAt,
    }));
  }

  function persistProgress(km, pathIndex, accuracyM, recordedAt){
    if(!durableSession || !window.DoloPawsHikeSession) return;
    if(!Number.isFinite(accuracyM) || accuracyM < 0 || accuracyM > 100) return;
    keepSessionResult(window.DoloPawsHikeSession.updateProgress(durableSession, {
      km,
      pathIndex,
      accuracyM,
      recordedAt,
    }));
  }

  function persistSessionState(state){
    if(!durableSession || !window.DoloPawsHikeSession) return;
    return keepSessionResult(window.DoloPawsHikeSession.setState(
      durableSession,
      state,
      Date.now()
    ));
  }

  function clearDurableSession(){
    if(window.DoloPawsHikeSession) window.DoloPawsHikeSession.clear();
    durableSession = null;
  }

  function setStartLabel(key, fallback){
    startBtn.innerHTML = hikeButtonHtml(hikeLabel(key, fallback));
  }

  // Pulsing "you are here" dot + live pill, shown only while recording. The
  // dot rides the snapped on-path position so it tracks the route like the
  // redesign prototype rather than jittering with raw GPS noise.
  const livePill = document.getElementById('tdLivePill');
  let liveMarker = null;
  let rejoinMarker = null;
  function showLiveDot(){
    if (!map || typeof maplibregl === 'undefined') return;
    if (!liveMarker){
      const dot = document.createElement('div');
      dot.className = 'hike-live-dot';
      liveMarker = new maplibregl.Marker({ element: dot });
    }
    liveMarker.setLngLat([trail.path[0][1], trail.path[0][0]]).addTo(map);
    if (livePill) livePill.hidden = false;
  }
  function moveLiveDot(lat, lng){ if (liveMarker) liveMarker.setLngLat([lng, lat]); }
  function hideLiveDot(){
    if (liveMarker){ liveMarker.remove(); }
    if (livePill) livePill.hidden = true;
  }

  function hideRejoinGuidance(){
    if(rejoinMarker) rejoinMarker.remove();
    const source = map && map.getSource ? map.getSource('dolopaws-rejoin-direction') : null;
    if(source){
      source.setData({ type: 'FeatureCollection', features: [] });
    }
  }

  function mappedRejoinGuidance(fix){
    return fix && footpathGraph && window.DoloPawsFootpathRouter
      ? window.DoloPawsFootpathRouter.routeToTrail(
        { lat:fix.lat, lng:fix.lng },
        footpathGraph,
        {
          maxSnapDistanceM:Math.min(60, Math.max(25, Number(fix.accuracy) + 10)),
          maxRouteDistanceM:1500,
        }
      )
      : null;
  }

  function renderManualRejoin(){
    const guidance = mappedRejoinGuidance(latestFix);
    if(guidance){
      banner.textContent = window.t('hike.rejoinMapped', {
        distance:Math.round(guidance.distanceM),
      });
      showRejoinGuidance(guidance);
    }else{
      banner.textContent = window.t('hike.rejoinUnavailable');
      hideRejoinGuidance();
    }
    banner.style.display = 'block';
  }

  rejoinBtn.addEventListener('click', () => {
    manualRejoinActive = true;
    renderManualRejoin();
  });

  function showRejoinGuidance(guidance){
    if(!guidance || guidance.routingMode !== 'mapped-footpath' ||
       !Array.isArray(guidance.path) || !map || typeof maplibregl === 'undefined' ||
       !map.isStyleLoaded || !map.isStyleLoaded()) return;
    if(!rejoinMarker){
      const target = document.createElement('div');
      target.setAttribute('aria-label', hikeLabel('hike.rejoinTarget', 'Closest point on trail'));
      target.style.cssText = 'width:22px;height:22px;border:4px solid #fff;border-radius:50%;background:#f3a712;box-shadow:0 0 0 3px rgba(156,58,37,.28),0 2px 8px rgba(0,0,0,.35);';
      rejoinMarker = new maplibregl.Marker({ element: target });
    }
    rejoinMarker.setLngLat([guidance.target.lng, guidance.target.lat]).addTo(map);
    const data = {
      type: 'FeatureCollection',
      features: [{
        type: 'Feature',
        properties: {},
        geometry: {
          type: 'LineString',
          coordinates: guidance.path.map(point => [point.lng, point.lat]),
        },
      }],
    };
    const source = map.getSource('dolopaws-rejoin-direction');
    if(source){
      source.setData(data);
    }else{
      map.addSource('dolopaws-rejoin-direction', { type: 'geojson', data });
      map.addLayer({
        id: 'dolopaws-rejoin-direction-line',
        type: 'line',
        source: 'dolopaws-rejoin-direction',
        paint: {
          'line-color': '#1677ff',
          'line-width': 5,
          'line-opacity': 0.92,
        },
      });
    }
  }

  // Map tile fetches fail silently when the connection drops mid-hike, // navigator.onLine often stays true on a weak mountain signal, so track
  // actual failed fetches too.
  let mapErrorListenerBound = false;
  function attachMap(nextMap){
    if(!nextMap) return;
    map = nextMap;
    if(!mapErrorListenerBound && map.on){
      mapErrorListenerBound = true;
      map.on('error', (e) => {
        const msg = e && e.error && (e.error.message || String(e.error));
        if (msg && /fetch|network|failed|abort/i.test(msg)) lastTileError = Date.now();
      });
    }
    if(active) showLiveDot();
  }
  attachMap(map);

  function offlineNote(){
    const offline = !navigator.onLine || (Date.now() - lastTileError < 30000);
    return offline
      ? `<br><span style="font-weight:400;opacity:.85;">${window.t('hike.offline')}</span>`
      : '';
  }

  // ---- Wake lock: keep the screen on while hiking --------------------------
  async function acquireWakeLock(){
    try {
      if ('wakeLock' in navigator) wakeLock = await navigator.wakeLock.request('screen');
    } catch (e) { /* not supported or denied, hike mode still works */ }
  }
  document.addEventListener('visibilitychange', () => {
    // The lock is auto-released when the app backgrounds; re-acquire on return.
    if (active && document.visibilityState === 'visible') acquireWakeLock();
  });

  // ---- Snap a GPS fix to the nearest point on the route --------------------
  // Continuity bias: when several path points are similarly close (common on
  // out-and-back or tightly-folded loops), prefer the one nearest to where
  // we last were, stops the readout jumping between overlapping segments.
  function snapToPath(lat, lng){
    let minDist = Infinity;
    const dists = new Array(trail.path.length);
    for (let i = 0; i < trail.path.length; i++){
      const d = metersBetween(lat, lng, trail.path[i][0], trail.path[i][1]);
      dists[i] = d;
      if (d < minDist) minDist = d;
    }
    let bestIdx = 0, bestIdxGap = Infinity;
    for (let i = 0; i < dists.length; i++){
      if (dists[i] <= minDist + 25){       // all near-ties within 25 m
        const gap = Math.abs(i - lastIdx);
        if (gap < bestIdxGap){ bestIdxGap = gap; bestIdx = i; }
      }
    }
    return { idx: bestIdx, dist: dists[bestIdx], minDist };
  }

  // ---- Lead advisories (positioned segments from the canonical scorer) -----
  // The rules for which advisories are usable live in recommendation-v1.js and
  // are not repeated here: this reads the leashAdvisories it already returns,
  // ordered by start distance. They do not depend on the dog, so an empty
  // subject is enough.
  let leashZones = [];
  const announcedZones = Object.create(null);

  function resolveLeashZones(activeTrail){
    leashZones = [];
    const scoring = window.DoloPawsScoring;
    if(!scoring || typeof scoring.recommendTrail !== 'function') return;
    try{
      const result = scoring.recommendTrail(activeTrail, {},
        window.ORMAScoringConditions && window.ORMAScoringConditions.forTrail(activeTrail));
      if(result && Array.isArray(result.leashAdvisories)) leashZones = result.leashAdvisories;
    }catch(error){
      // A scorer failure must never stop a walk from being recorded.
      leashZones = [];
    }
  }

  // Returns the advisory to speak about right now: the one being walked
  // through, else the next one close enough ahead to act on.
  const LEAD_WARNING_KM = 0.3;

  function leashZoneFor(currentKm){
    if(!Number.isFinite(currentKm)) return null;
    for(const zone of leashZones){
      if(currentKm >= zone.fromKm && currentKm <= zone.toKm) return { zone, inside:true, ahead:0 };
    }
    for(const zone of leashZones){
      const ahead = zone.fromKm - currentKm;
      if(ahead > 0 && ahead <= LEAD_WARNING_KM) return { zone, inside:false, ahead };
    }
    return null;
  }

  // ---- Next POI ahead (from km-tagged rifugi / water sources) --------------
  function nextAhead(list, currentKm, labelKey){
    let best = null;
    for (const item of (list || [])){
      if (typeof item.km !== 'number') continue;
      const ahead = item.km - currentKm;
      if (ahead > 0.05 && (!best || ahead < best.ahead)){
        best = { ahead, label: item[labelKey] };
      }
    }
    return best;
  }

  // ---- Per-fix update -------------------------------------------------------
  function onFix(pos){
    const { latitude: lat, longitude: lng, accuracy } = pos.coords;
    const snap = snapToPath(lat, lng);
    const rejoin = window.DoloPawsRouteRejoin &&
      window.DoloPawsRouteRejoin.guidance({ lat, lng }, rejoinRoute);
    const routeDistanceM = rejoin ? rejoin.distanceM : snap.minDist;
    const fixTimestamp = Number.isFinite(pos.timestamp) ? pos.timestamp : Date.now();
    latestFix = { lat, lng, accuracy };
    const assessment = window.DoloPawsGpsPolicy
      ? window.DoloPawsGpsPolicy.assessFix({
        timestamp: fixTimestamp,
        now: Date.now(),
        accuracyM: accuracy,
        routeDistanceM,
        previousOffRouteStreak: offRouteStreak,
        previousOffRouteSince: offRouteSince,
      })
      : {
        usableForProgress: false,
        reliableForWarning: false,
        offRouteState: 'none',
        nextOffRouteStreak: 0,
        farFromRoute: false,
        freshness: 'unavailable',
      };
    latestAssessment = assessment;
    latestRouteDistanceM = routeDistanceM;
    updateRejoinControl();

    if(firstFix && assessment.usableForProgress){
      firstFix = false;
      recordConfirmedHikeStart(accuracy);
      if(map && map.easeTo && map.getZoom){
        map.easeTo({ center: [lng, lat], zoom: Math.max(map.getZoom(), 15), duration: 800 });
      }
    }

    if(assessment.usableForProgress) lastIdx = snap.idx;
    // Ride the snapped on-path point when near the route; otherwise show the
    // real fix so a lost hiker still sees where they actually are.
    if(assessment.reliableForWarning && routeDistanceM <= 60 && rejoin){
      moveLiveDot(rejoin.target.lat, rejoin.target.lng);
    }
    else moveLiveDot(lat, lng);
    const routeProgressM = rejoin
      ? cum[rejoin.segmentIndex] +
        (cum[rejoin.segmentIndex + 1] - cum[rejoin.segmentIndex]) * rejoin.segmentFraction
      : cum[snap.idx];
    if(routeProgressM > furthestRouteM) furthestRouteM = routeProgressM;
    const currentRouteKm = hikeRoutePositionKm({
      routeProgressM, totalMeters, statedKm, outAndBack, furthestRouteM,
      returnMarginM:RETURN_MARGIN_M,
    });
    if(assessment.usableForProgress){
      if(window.DoloPawsHikeDistance){
        distanceTracker = window.DoloPawsHikeDistance.update(
          distanceTracker || window.DoloPawsHikeDistance.create(lastKnownKm),
          {
            lat,
            lng,
            timestamp:fixTimestamp,
            accuracyM:accuracy,
            routePositionM:routeProgressM,
            nearRoute:routeDistanceM <= 60,
            usable:true,
          },
          { totalRouteM:totalMeters, loop:isLoop }
        );
        lastKnownKm = distanceTracker.distanceM / 1000;
      }
      lastValidFixAt = fixTimestamp;
      persistProgress(
        lastKnownKm,
        snap.idx,
        accuracy,
        fixTimestamp
      );
    }

    // Far from the trail entirely (driving there, wrong valley…)
    if(assessment.farFromRoute){
      panel.innerHTML = window.t('hike.far', {
        d: (routeDistanceM / 1000).toFixed(1),
      }) + `<br><span style="font-weight:400;opacity:.85;">${
        window.t('hike.gpsLine', {
          accuracy: Math.round(accuracy),
          distance: Math.round(routeDistanceM),
          time: new Date(lastValidFixAt || fixTimestamp).toLocaleTimeString(),
        })
      }</span>` + offlineNote();
      banner.style.display = 'none';
      announcedOffRoute = false;
      manualRejoinActive = false;
      hideRejoinGuidance();
      offRouteStreak = assessment.nextOffRouteStreak;
      offRouteSince = assessment.nextOffRouteSince;
      return;
    }

    offRouteStreak = assessment.nextOffRouteStreak;
    offRouteSince = assessment.nextOffRouteSince;
    const rejoinAvailable = !rejoinBtn.disabled;
    if(!rejoinAvailable) manualRejoinActive = false;
    if(manualRejoinActive){
      renderManualRejoin();
    }else if(assessment.offRouteState === 'confirmed'){
      banner.textContent = window.t('hike.offRouteDistance', {
        distance:Math.round(routeDistanceM),
      });
      banner.style.display = 'block';
      if(!announcedOffRoute){
        urgentAnnouncer.textContent = banner.textContent;
        announcedOffRoute = true;
      }
    }else{
      banner.style.display = 'none';
      announcedOffRoute = false;
      hideRejoinGuidance();
    }

    // Progress readout
    const displayKm = lastKnownKm;
    const parts = [window.t('hike.walked', {distance:displayKm.toFixed(1)})];
    const water = isLoop ? null : nextAhead(trail.waterSources, currentRouteKm, 'label');
    if (water) parts.push(window.t('hike.waterIn', {d: water.ahead.toFixed(1)}));
    const hut = isLoop ? null : nextAhead(trail.rifugi, currentRouteKm, 'name');
    if (hut) parts.push(window.t('hike.hutIn', {name: hut.label, d: hut.ahead.toFixed(1)}));
    const decision = isLoop ? null : nextAhead(trail.decisionPoints, currentRouteKm, 'instruction');
    if (decision && decision.ahead < 0.5) parts.push(window.t('hike.ahead', {what: decision.label}));

    // Lead advisories are a range rather than a next-point search, so unlike
    // the readouts above they stay meaningful on a loop.
    const lead = assessment.usableForProgress ? leashZoneFor(currentRouteKm) : null;
    if (lead) {
      const detail = lead.zone.note || lead.zone.label;
      const message = lead.inside
        ? window.t('hike.leadOnNow', {what: detail})
        : window.t('hike.leadOnAhead', {m: Math.round(lead.ahead * 1000), what: detail});
      parts.push(message);
      // Announce each zone once entering and once approaching, so the phone
      // speaks up when it matters without repeating on every fix.
      const key = `${lead.zone.fromKm}-${lead.zone.toKm}-${lead.inside ? 'in' : 'near'}`;
      if (!announcedZones[key]) {
        announcedZones[key] = true;
        urgentAnnouncer.textContent = message;
      }
    }
    const validFixLabel = lastValidFixAt
      ? new Date(lastValidFixAt).toLocaleTimeString()
      : ', ';
    const reliabilityNote = assessment.freshness === 'stale'
      ? window.t('hike.gpsStale')
      : !assessment.reliableForWarning
        ? window.t('hike.gpsWeak')
        : '';
    const onRouteThresholdM = window.DoloPawsGpsPolicy
      ? window.DoloPawsGpsPolicy.THRESHOLDS.onRouteM
      : 40;
    const gpsStatusKey = assessment.offRouteState === 'possible'
      ? 'hike.gpsCheckingRoute'
      : assessment.upperBoundM < onRouteThresholdM
        ? 'hike.gpsOnTrail'
        : 'hike.gpsNearTrail';
    panel.innerHTML = parts.join(' · ')
      + `<br><span style="font-weight:400;opacity:.85;">${window.t(gpsStatusKey, {
        accuracy: Number.isFinite(accuracy) ? Math.round(accuracy) : ', ',
        time: validFixLabel,
      })}${reliabilityNote ? `<br>${reliabilityNote}` : ''}</span>`
      + offlineNote();

    // Drive the elevation-profile cursor from live position, if the page has one.
    if (typeof window._dolopawsElevHighlight === 'function'){
      try { window._dolopawsElevHighlight(Math.min(currentRouteKm, statedKm)); } catch (e) {}
    }

    // Let page chrome (the live recording banner) mirror our progress.
    window.dispatchEvent(new CustomEvent('dolopaws-hike-progress', {
      detail: { km: displayKm, startedAt: hikeStartedAt },
    }));
  }

  function onError(err){
    if(firstFix) clearDurableSession();
    else persistSessionState('paused');
    if (err.code === 1){ // PERMISSION_DENIED
      panel.innerHTML = window.t('hike.permission');
      stopHike(true);
      panel.style.display = 'block';
    } else if (err.code === 2){ // POSITION_UNAVAILABLE
      panel.innerHTML = window.t('hike.unavailable');
      stopHike(true);
      panel.style.display = 'block';
    } else if (err.code === 3){ // TIMEOUT
      panel.innerHTML = window.t('hike.timeout');
      stopHike(true);
      panel.style.display = 'block';
    } else {
      panel.innerHTML = window.t('hike.waiting');
    }
    announceStatus(panel.textContent);
    if(durableSession) setStartLabel('hike.resume', 'Resume hike');
  }

  // ---- Start / stop ---------------------------------------------------------
  function recordConfirmedHikeStart(){
    if (hikeStartRecorded) return;
    hikeStartRecorded = true;
    // One anonymous count event per trail per device per day. A confirmed
    // GPS fix is required, so permission errors do not count as hikes.
    try {
      const guardKey = `dolopaws-hiked-${trail.id}-${new Date().toISOString().slice(0, 10)}`;
      if (!localStorage.getItem(guardKey) && window.DoloPawsCommunity) {
        window.DoloPawsCommunity.recordHikeStart(trail.id).then(ok => {
          if (ok) localStorage.setItem(guardKey, '1');
        });
      }
    } catch (e) { /* private browsing etc., skip silently */ }
  }

  function startHike(){
    durableSession = null;
    active = true;
    firstFix = true;
    hikeStartRecorded = false;
    hikeStartedAt = Date.now();
    lastKnownKm = 0;
    distanceTracker = window.DoloPawsHikeDistance
      ? window.DoloPawsHikeDistance.create(0)
      : null;
    latestFix = null;
    latestAssessment = null;
    latestRouteDistanceM = null;
    manualRejoinActive = false;
    lastValidFixAt = null;
    offRouteStreak = 0;
    offRouteSince = null;
    resolveLeashZones(trail);
    for(const key of Object.keys(announcedZones)) delete announcedZones[key];
    beginDurableSession();
    updateRejoinControl();
    // A hiker needs a navigation screen, not an article: go fullscreen.
    if (window.DoloPawsMapFS) window.DoloPawsMapFS.enter();
    setStartLabel('hike.end', 'End hike');
    startBtn.style.background = '#9C3A25';
    pauseBtn.hidden = false;
    window.dispatchEvent(new CustomEvent('dolopaws-hike-progress', {
      detail: { km: 0, startedAt: hikeStartedAt },
    }));
    panel.style.display = 'block';
    container.classList.add('hike-status-visible');
    panel.innerHTML = window.t('hike.getting');
    announceStatus(panel.textContent);
    showLiveDot();
    acquireWakeLock();
    watchId = navigator.geolocation.watchPosition(onFix, onError, {
      enableHighAccuracy: true,
      maximumAge: 2000,
      timeout: 20000,
    });
  }

  function requestNewHike(){
    if(window.DoloPawsReadiness && window.DoloPawsReadiness.open){
      window.DoloPawsReadiness.open(trail, startHike);
    }else{
      startHike();
    }
  }

  function stopHike(keepPanel){
    active = false;
    if (window.DoloPawsMapFS) window.DoloPawsMapFS.exit();
    if (watchId !== null){ navigator.geolocation.clearWatch(watchId); watchId = null; }
    if (wakeLock){ try { wakeLock.release(); } catch (e) {} wakeLock = null; }
    hideLiveDot();
    setStartLabel('hike.start', 'Start hike');
    startBtn.style.background = 'var(--ink)';
    pauseBtn.hidden = true;
    if (!keepPanel){
      panel.style.display = 'none';
      container.classList.remove('hike-status-visible');
    } else {
      container.classList.add('hike-status-visible');
    }
    banner.style.display = 'none';
    rejoinBtn.hidden = true;
    manualRejoinActive = false;
    hideRejoinGuidance();
  }

  function resumeHike(){
    if(!durableSession) return;
    active = true;
    const progress = durableSession.lastProgress;
    firstFix = !progress;
    hikeStartRecorded = !!progress;
    hikeStartedAt = durableSession.startedAt;
    lastKnownKm = progress ? progress.km : 0;
    distanceTracker = window.DoloPawsHikeDistance
      ? window.DoloPawsHikeDistance.create(lastKnownKm)
      : null;
    latestFix = null;
    latestAssessment = null;
    latestRouteDistanceM = null;
    manualRejoinActive = false;
    lastIdx = progress ? progress.pathIndex : 0;
    // A walk resumed on the way back has already been to the far end. Without
    // this the readout would call the return leg outbound until the walker got
    // 150 m past wherever the app happened to restart.
    furthestRouteM = progress && cum[lastIdx] !== undefined ? cum[lastIdx] : 0;
    lastValidFixAt = progress ? progress.recordedAt : null;
    offRouteStreak = 0;
    offRouteSince = null;
    // A restored session re-resolves its advisories; it may have been stored
    // before this build existed, or the trail record may have gained one since.
    resolveLeashZones(trail);
    for(const key of Object.keys(announcedZones)) delete announcedZones[key];
    persistSessionState('active');
    updateRejoinControl();
    if(window.DoloPawsMapFS) window.DoloPawsMapFS.enter();
    setStartLabel('hike.end', 'End hike');
    startBtn.style.background = '#9C3A25';
    startBtn.disabled = false;
    pauseBtn.hidden = false;
    panel.style.display = 'block';
    container.classList.add('hike-status-visible');
    panel.innerHTML = window.t('hike.getting');
    announceStatus(panel.textContent);
    showLiveDot();
    acquireWakeLock();
    window.dispatchEvent(new CustomEvent('dolopaws-hike-progress', {
      detail: { km: lastKnownKm, startedAt: hikeStartedAt },
    }));
    watchId = navigator.geolocation.watchPosition(onFix, onError, {
      enableHighAccuracy: true,
      maximumAge: 2000,
      timeout: 20000,
    });
  }

  function pauseHike(){
    if(!active || !durableSession) return;
    persistSessionState('paused');
    stopHike(true);
    setStartLabel('hike.resume', 'Resume hike');
    panel.textContent = window.t('hike.paused');
    announceStatus(panel.textContent);
  }

  function persistCompletionAndShow(completedAt){
    if(!durableSession || !window.DoloPawsHikeCompletions) return false;
    persistSessionState('completion-pending');
    const result = window.DoloPawsHikeCompletions.save(durableSession, {
      completedAt,
      distanceKm: lastKnownKm,
    });
    if(!result.ok){
      stopHike(true);
      completionRetry = () => persistCompletionAndShow(completedAt);
      startBtn.disabled = false;
      setStartLabel('hike.retryFinish', 'Save completed hike');
      panel.textContent = window.t('hike.completionSaveFailed');
      announceStatus(panel.textContent);
      return false;
    }
    // SOCIAL-01 stage 1: one anonymous tally per completed walk, tagged only
    // with the dog's coarse FCI group. Fire-and-forget; a finished hike must
    // never depend on it.
    if(window.DoloPawsCommunity && typeof window.DoloPawsCommunity.recordTrailWalk === 'function'){
      window.DoloPawsCommunity.recordTrailWalk(trail.id, activeDogGroup());
    }
    completionRetry = null;
    clearDurableSession();
    stopHike(false);
    showCompletionScreen(result.record);
    return true;
  }

  // The active dog's FCI group for the anonymous walk tally, or 'unknown'.
  // breedGroupId comes from breeds-data.js (same trail bundle); guarded so a
  // context without it degrades to 'unknown' rather than throwing.
  function activeDogGroup(){
    try {
      const raw = JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null');
      const active = raw && Array.isArray(raw.dogs)
        ? raw.dogs.find(dog => dog.id === raw.activeDogId) || raw.dogs[0]
        : null;
      const breed = (active && active.breed) || (raw && raw.breed) || '';
      return typeof breedGroupId === 'function' ? breedGroupId(breed) : 'unknown';
    } catch (e) {
      return 'unknown';
    }
  }

  function finishHike(){
    const hadGpsFix = !firstFix;
    if(!hadGpsFix){
      clearDurableSession();
      stopHike(false);
      return;
    }
    persistCompletionAndShow(Date.now());
  }

  // ---- Completion screen: save / discard, photos, share-to-trail flag ------
  // Replaces the old "Hike ended, log this walk →" link with the design's
  // full-screen summary. Saving writes straight into the walk journal store
  // (same schema journal.html reads), carrying { photos, shareToTrail }, // the flag the trail page checks before surfacing a walk's photos.
  function esc(s){
    return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  }
  function fmtClock(sec){
    const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
    const mm = String(m).padStart(2, '0'), ss = String(s).padStart(2, '0');
    return h > 0 ? `${h}:${mm}:${ss}` : `${mm}:${ss}`;
  }
  function dogSummary(){
    let name = '', photo = null;
    try {
      const raw = JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null');
      const active = raw && Array.isArray(raw.dogs)
        ? raw.dogs.find(dog => dog.id === raw.activeDogId) || raw.dogs[0]
        : null;
      if (active && active.name) name = String(active.name);
      else if (raw && raw.name) name = String(raw.name);
      if (active && typeof active.photo === 'string' && active.photo.startsWith('data:image/')) photo = active.photo;
    } catch (e) {}
    return { name, photo };
  }

  function showCompletionScreen(completion){
    const elapsedSeconds = completion.durationSeconds;
    const elapsedMinutes = Math.max(1, Math.round(elapsedSeconds / 60));
    const dog = dogSummary();
    const dogName = dog.name || 'Your dog';
    const km = completion.distanceKm;
    const pace = km > 0.1 ? (elapsedMinutes / km).toFixed(1) + ' min/km' : ', ';
    // The trail rating, in the words the rest of the product uses. This held
    // its own English table -- "Low-risk", "Moderate", "Caution" -- so the one
    // badge a walker sees at the end of a hike stayed English on the Italian
    // site, and said something shorter than the same badge everywhere else.
    const ratingLabel = typeof trailSafetyLabel === 'function'
      ? trailSafetyLabel(trail)
      : '';
    const ratingClass = typeof safetyClass === 'function'
      ? safetyClass(trail.safetyLevel)
      : 'safety-moderate';
    // The trail page already computed the personal match, reuse its figure.
    const scoreEl = document.querySelector('.personal-score b');
    const matchPct = scoreEl ? parseInt(scoreEl.textContent, 10) : NaN;

    const photos = [];       // { file, url }
    let cond = 'Comfortable';
    let shareOn = true;
    let outcomeResponse = '';

    const overlay = document.createElement('div');
    overlay.className = 'hk-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-labelledby', 'hkTitle');
    overlay.innerHTML = `
      <div class="hk-card">
        <div class="hk-avatar"${dog.photo ? ` style="background-image:url(${dog.photo});"` : ''}>${dog.photo ? '' : esc(dogName.charAt(0).toUpperCase() || '🐾')}</div>
        <h1 class="hk-title" id="hkTitle">${esc(window.t('hike.completedTitle', {name: dogName}))}</h1>
        <p class="hk-sub">${esc(trail.name)}</p>
        <div class="hk-stats">
          <div class="hk-stat"><b>${fmtClock(elapsedSeconds)}</b><span>${esc(window.t('hike.statTime'))}</span></div>
          <div class="hk-stat"><b>${km.toFixed(1)} km</b><span>${esc(window.t('hike.statDistance'))}</span></div>
          <div class="hk-stat"><b>${pace}</b><span>${esc(window.t('hike.statPace'))}</span></div>
        </div>
        <div class="hk-matchline">
          ${ratingLabel ? `<span class="safety-badge ${ratingClass}">${esc(ratingLabel)}</span>` : ''}
          ${Number.isFinite(matchPct) ? `<span class="pct">${esc(window.t('hike.matchFor', {pct: matchPct, name: dogName}))}</span>` : ''}
        </div>
        <div class="hk-block hk-outcome-block">
          <div class="hk-label">Private trail feedback</div>
          <p class="hk-outcome-intro">Did this trail suit ${esc(dogName)}? This helps assess the recommendation and never becomes a public review.</p>
          <div class="hk-outcome-options" id="hkOutcomeOptions" role="radiogroup" aria-label="Did this trail suit your dog?"></div>
          <div class="hk-outcome-followups" id="hkOutcomeFollowups" hidden>
            <label for="hkWaterAccuracy">Was the listed water information accurate? <span>Optional</span></label>
            <select id="hkWaterAccuracy">
              <option value="">Prefer not to answer</option>
              <option value="accurate">Yes, it was accurate</option>
              <option value="less_than_listed">Less water than listed</option>
              <option value="more_than_listed">More water than listed</option>
              <option value="not_checked">I did not check</option>
            </select>
            <label for="hkLivestock">Did you encounter livestock? <span>Optional</span></label>
            <select id="hkLivestock">
              <option value="">Prefer not to answer</option>
              <option value="none">No livestock at all</option>
              <option value="seen_at_distance">Seen, but at a distance</option>
              <option value="close_encounter">Passed close to them</option>
            </select>
            <label for="hkOffLead">Were dogs off-lead on this route? <span>Optional</span></label>
            <select id="hkOffLead">
              <option value="">Prefer not to answer</option>
              <option value="all_on_lead">Everyone kept dogs on the lead</option>
              <option value="some_off_lead">Some dogs were off-lead</option>
              <option value="mostly_off_lead">Most dogs were off-lead</option>
            </select>
            <label for="hkCrowding">How busy was it? <span>Optional</span></label>
            <select id="hkCrowding">
              <option value="">Prefer not to answer</option>
              <option value="quiet">Quiet, room to give space</option>
              <option value="moderate">Steady foot traffic</option>
              <option value="busy">Busy throughout</option>
            </select>
            <label for="hkEnjoyment">Did ${esc(dogName)} enjoy it? <span>Optional</span></label>
            <select id="hkEnjoyment">
              <option value="">Prefer not to answer</option>
              <option value="loved_it">Loved it</option>
              <option value="fine">Took it in their stride</option>
              <option value="struggled">Struggled with it</option>
            </select>
            <label for="hkReactiveFit">Would you recommend it for a reactive dog? <span>Optional</span></label>
            <select id="hkReactiveFit">
              <option value="">Prefer not to answer</option>
              <option value="yes">Yes, there is room to pass</option>
              <option value="with_care">Only with care</option>
              <option value="no">No, too little space</option>
            </select>
            <label class="hk-outcome-check">
              <input type="checkbox" id="hkMissingRestriction">
              A posted restriction was missing from ORMA
            </label>
            <fieldset>
              <legend>Any material hazard we should account for? <span>Optional</span></legend>
              <div class="hk-hazard-options">
                <label><input type="checkbox" value="surface"> Surface</label>
                <label><input type="checkbox" value="exposure"> Exposure</label>
                <label><input type="checkbox" value="livestock"> Livestock</label>
                <label><input type="checkbox" value="heat"> Heat</label>
                <label><input type="checkbox" value="access"> Access</label>
                <label><input type="checkbox" value="water"> Water</label>
              </div>
            </fieldset>
          </div>
          <button type="button" class="hk-outcome-save" id="hkOutcomeSave" disabled>Save private feedback</button>
          <p class="hk-outcome-status" id="hkOutcomeStatus" role="status" aria-live="polite"></p>
        </div>
        <div class="hk-block">
          <div class="hk-label">${esc(window.t('hike.feel'))}</div>
          <div class="hk-seg" id="hkCondSeg" role="radiogroup" aria-label="${esc(window.t('hike.feel'))}"></div>
        </div>
        <div class="hk-block">
          <div class="hk-label">${esc(window.t('hike.photos'))}</div>
          <div class="hk-photos" id="hkPhotos"></div>
          <div class="hk-share" id="hkShareRow" hidden>
            <span><b>${esc(window.t('hike.shareTitle'))}</b><small>${esc(window.t('hike.shareSub'))}</small></span>
            <button type="button" class="li-switch on" id="hkShareToggle" role="switch" aria-checked="true" aria-label="${esc(window.t('hike.shareTitle'))}"><span class="knob"></span></button>
          </div>
        </div>
        <div id="hkDiscardNote" class="hk-discard-note" hidden>
          <p>${esc(window.t('hike.discardConfirm'))}</p>
          <div class="row">
            <button type="button" class="hk-ghost" id="hkKeepBtn" style="flex:1;">${esc(window.t('hike.keep'))}</button>
            <button type="button" class="hk-danger" id="hkDiscardConfirmBtn">${esc(window.t('hike.discard'))}</button>
          </div>
        </div>
        <div class="hk-actions" id="hkActions">
          <button type="button" class="hk-ghost" id="hkDiscardBtn">${esc(window.t('hike.discard'))}</button>
          <button type="button" class="hk-save" id="hkSaveBtn">${esc(window.t('hike.saveJournal'))}</button>
        </div>
        <input type="file" accept="image/*" multiple id="hkPhotoInput" hidden>
      </div>`;
    document.body.appendChild(overlay);
    document.body.style.overflow = 'hidden';

    const q = sel => overlay.querySelector(sel);
    let releaseCompletionFocus = null;

    function renderOutcome(){
      const labels = [
        ['appropriate', 'Yes, appropriate'],
        ['appropriate_with_unexpected_cautions', 'Yes, with unexpected cautions'],
        ['not_appropriate', 'No, not appropriate'],
        ['did_not_complete', 'We turned back'],
        ['prefer_not_to_answer', 'Prefer not to answer'],
      ];
      const choices = q('#hkOutcomeOptions');
      choices.innerHTML = '';
      labels.forEach(([value, label]) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = label;
        button.className = value === outcomeResponse ? 'on' : '';
        button.dataset.radioValue = value;
        button.setAttribute('role', 'radio');
        button.setAttribute('aria-checked', String(value === outcomeResponse));
        button.addEventListener('click', () => {
          outcomeResponse = value;
          renderOutcome();
          const selected = choices.querySelector('[data-radio-value="' + value + '"]');
          if(selected) selected.focus();
        });
        choices.appendChild(button);
      });
      if(window.DoloPawsA11y){
        window.DoloPawsA11y.wireRadioGroup(choices, target => {
          outcomeResponse = target.dataset.radioValue;
          renderOutcome();
          return choices.querySelector('[data-radio-value="' + outcomeResponse + '"]');
        });
      }
      q('#hkOutcomeFollowups').hidden =
        !outcomeResponse || outcomeResponse === 'prefer_not_to_answer';
      q('#hkOutcomeSave').disabled = !outcomeResponse;
    }

    q('#hkOutcomeSave').addEventListener('click', async () => {
      const saveButton = q('#hkOutcomeSave');
      const status = q('#hkOutcomeStatus');
      const user = window.DoloPawsAuth && window.DoloPawsAuth.currentUser;
      if(!user){
        status.textContent = 'Log in before saving this private response.';
        if(window.DoloPawsAuthUI) window.DoloPawsAuthUI.openLogin();
        return;
      }
      if(!window.DoloPawsPostHikeOutcomes){
        status.textContent = 'Private feedback is unavailable. Your completed hike is still saved.';
        return;
      }
      saveButton.disabled = true;
      status.textContent = 'Saving privately on this device…';
      let offlinePackageUsed = false;
      if(window.DoloPawsOffline && window.DoloPawsOffline.inspectPackage){
        try{
          const inspection = await window.DoloPawsOffline.inspectPackage(trail.id);
          offlinePackageUsed = !!inspection.usable;
        }catch(error){}
      }
      const hazards = Array.from(
        overlay.querySelectorAll('.hk-hazard-options input:checked')
      ).map(input => input.value);
      const result = window.DoloPawsPostHikeOutcomes.save(completion, {
        response:outcomeResponse,
        waterAccuracy:q('#hkWaterAccuracy').value || null,
        // Empty stays null: an unanswered question is a gap in the evidence,
        // not a quiet claim that the pleasant answer applies.
        livestockEncountered:q('#hkLivestock').value || null,
        offLeadObserved:q('#hkOffLead').value || null,
        crowding:q('#hkCrowding').value || null,
        dogEnjoyment:q('#hkEnjoyment').value || null,
        reactiveDogFit:q('#hkReactiveFit').value || null,
        missingRestriction:q('#hkMissingRestriction').checked ? true : null,
        hazards,
        offlinePackageUsed,
      }, user.uid);
      if(!result.ok){
        status.textContent = 'The response could not be saved. Try again before closing this screen.';
        saveButton.disabled = false;
        return;
      }
      overlay.querySelectorAll(
        '#hkOutcomeOptions button,#hkOutcomeFollowups input,#hkOutcomeFollowups select'
      ).forEach(control => { control.disabled = true; });
      status.textContent = navigator.onLine
        ? 'Saved privately · syncing…'
        : 'Saved privately · pending sync until you reconnect.';
      const sync = await window.DoloPawsPostHikeOutcomes.syncBrowser();
      status.textContent = sync.ok && sync.pending === 0
        ? 'Saved privately · synced to your account.'
        : 'Saved privately · pending sync until you reconnect.';
      saveButton.textContent = 'Feedback saved';
    });

    function renderCond(){
      const seg = q('#hkCondSeg');
      seg.innerHTML = '';
      ['Comfortable', 'Warm', 'Hot'].forEach(c => {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = c;
        b.className = c === cond ? 'on' : '';
        b.dataset.radioValue = c;
        b.setAttribute('role', 'radio');
        b.setAttribute('aria-checked', String(c === cond));
        b.addEventListener('click', () => {
          cond = c;
          renderCond();
          const selected = seg.querySelector('[data-radio-value="' + c + '"]');
          if(selected) selected.focus();
        });
        seg.appendChild(b);
      });
      if(window.DoloPawsA11y){
        window.DoloPawsA11y.wireRadioGroup(seg, target => {
          cond = target.dataset.radioValue;
          renderCond();
          return seg.querySelector('[data-radio-value="' + cond + '"]');
        });
      }
    }

    function renderPhotos(){
      const grid = q('#hkPhotos');
      grid.innerHTML = '';
      photos.forEach((p, i) => {
        const cell = document.createElement('div');
        cell.className = 'hk-photo';
        cell.style.backgroundImage = `url(${p.url})`;
        const rm = document.createElement('button');
        rm.type = 'button';
        rm.textContent = '×';
        rm.setAttribute('aria-label', window.t('hike.removePhoto'));
        rm.addEventListener('click', () => {
          URL.revokeObjectURL(p.url);
          photos.splice(i, 1);
          renderPhotos();
        });
        cell.appendChild(rm);
        grid.appendChild(cell);
      });
      if (photos.length < 4){
        const add = document.createElement('button');
        add.type = 'button';
        add.className = 'hk-add';
        add.textContent = '+';
        add.setAttribute('aria-label', window.t('hike.addPhoto'));
        add.addEventListener('click', () => q('#hkPhotoInput').click());
        grid.appendChild(add);
      }
      q('#hkShareRow').hidden = photos.length === 0;
    }

    q('#hkPhotoInput').addEventListener('change', (e) => {
      Array.from(e.target.files || []).slice(0, 4 - photos.length).forEach(file => {
        if (!/^image\//.test(file.type)) return;
        photos.push({ file, url: URL.createObjectURL(file) });
      });
      e.target.value = '';
      renderPhotos();
    });

    const shareToggle = q('#hkShareToggle');
    shareToggle.addEventListener('click', () => {
      shareOn = !shareOn;
      shareToggle.classList.toggle('on', shareOn);
      shareToggle.setAttribute('aria-checked', String(shareOn));
    });

    function closeOverlay(){
      photos.forEach(p => URL.revokeObjectURL(p.url));
      overlay.remove();
      document.body.style.overflow = '';
      if(releaseCompletionFocus){ releaseCompletionFocus(); releaseCompletionFocus = null; }
    }

    q('#hkDiscardBtn').addEventListener('click', () => {
      q('#hkDiscardNote').hidden = false;
      q('#hkActions').hidden = true;
      q('#hkKeepBtn').focus();
    });
    q('#hkKeepBtn').addEventListener('click', () => {
      q('#hkDiscardNote').hidden = true;
      q('#hkActions').hidden = false;
      q('#hkDiscardBtn').focus();
    });
    q('#hkDiscardConfirmBtn').addEventListener('click', () => {
      if(window.DoloPawsHikeCompletions){
        window.DoloPawsHikeCompletions.markFollowUp(
          completion.completionId,
          'discarded'
        );
      }
      closeOverlay();
    });

    q('#hkSaveBtn').addEventListener('click', () => {
      const user = window.DoloPawsAuth && window.DoloPawsAuth.currentUser;
      if (!user){
        // Guests fall back to the journal's pending-walk flow, which asks
        // them to log in first (photos can't follow it).
        const returnToTrail = `trail.html?id=${encodeURIComponent((window.DoloPawsRegionalData && window.DoloPawsRegionalData.slugFor ? window.DoloPawsRegionalData.slugFor(trail.id) : (trail.id)))}`;
        window.location.href = `journal.html?trail=${encodeURIComponent(trail.id)}&duration=${elapsedMinutes}&completion=${encodeURIComponent(completion.completionId)}&from=${encodeURIComponent(returnToTrail)}`;
        return;
      }
      const journalStore = window.DoloPawsJournalStore;
      const savedAt = Date.now();
      const entry = {
        // A unique id per walk: journal entries now sync to the account, where
        // two devices sharing an id would mean one walk overwriting the other.
        id: journalStore ? journalStore.newId(savedAt) : ('w' + savedAt),
        updatedAt: savedAt,
        date: new Date().toISOString(),
        trailId: trail.id,
        trail: trail.name,
        region: trail.valley || trail.area || '',
        dist: km > 0.1 ? km.toFixed(1) : '',
        dur: String(elapsedMinutes),
        cond,
        rating: null,
        note: '',
        photos: photos.length,
        shareToTrail: photos.length > 0 && shareOn,
      };
      let saved = false;
      try {
        const key = `dolopaws-journal-${user.uid}`;
        const entries = JSON.parse(localStorage.getItem(key) || '[]');
        entries.unshift(entry);
        entries.sort((a, b) => new Date(b.date) - new Date(a.date));
        localStorage.setItem(key, JSON.stringify(entries));
        saved = true;
      } catch (e) { /* storage full/blocked, still leave the page gracefully */ }
      if(saved && window.DoloPawsHikeCompletions){
        window.DoloPawsHikeCompletions.markFollowUp(
          completion.completionId,
          'journal-saved'
        );
      }
      closeOverlay();
      window.location.href = 'journal.html';
    });

    renderCond();
    renderPhotos();
    renderOutcome();
    if(window.DoloPawsA11y){
      releaseCompletionFocus = window.DoloPawsA11y.openDialog(overlay, {
        initialFocus:'#hkOutcomeOptions [role="radio"]',
        closeOnEscape:false,
      });
    }else{
      const firstBtn = q('#hkOutcomeOptions [role="radio"]') || q('#hkSaveBtn');
      if(firstBtn) firstBtn.focus();
    }
  }

  function recoveryActions(includeResume, otherTrailId, showDownloads){
    const actions = document.createElement('span');
    actions.style.cssText = 'display:flex;justify-content:center;gap:8px;margin-top:8px;flex-wrap:wrap;';
    if(includeResume){
      const resume = document.createElement('button');
      resume.type = 'button';
      resume.textContent = window.t('hike.resume');
      resume.addEventListener('click', resumeHike);
      actions.appendChild(resume);
    }
    if(otherTrailId){
      const open = document.createElement('a');
      open.href = `trail.html?id=${encodeURIComponent((window.DoloPawsRegionalData && window.DoloPawsRegionalData.slugFor ? window.DoloPawsRegionalData.slugFor(otherTrailId) : (otherTrailId)))}`;
      open.textContent = window.t('hike.openTrail');
      open.style.cssText = 'color:#fff;padding:6px 8px;font-weight:800;';
      actions.appendChild(open);
    }
    if(showDownloads){
      const downloads = document.createElement('a');
      downloads.href = 'downloads.html';
      downloads.textContent = window.t('hike.openDownloads');
      downloads.style.cssText = 'color:#fff;padding:6px 8px;font-weight:800;';
      actions.appendChild(downloads);
    }
    const discard = document.createElement('button');
    discard.type = 'button';
    discard.textContent = window.t('hike.discard');
    discard.style.background = '#9C3A25';
    discard.addEventListener('click', () => {
      clearDurableSession();
      panel.style.display = 'none';
      container.classList.remove('hike-status-visible');
      startBtn.disabled = false;
      setStartLabel('hike.start', 'Start hike');
    });
    actions.appendChild(discard);
    panel.appendChild(actions);
  }

  async function checkForRecovery(){
    if(!window.DoloPawsHikeSession || active) return;
    const user = window.DoloPawsAuth && window.DoloPawsAuth.currentUser;
    let packageAvailable = true;
    if(!navigator.onLine){
      packageAvailable = false;
      if(window.DoloPawsOffline && window.DoloPawsOffline.inspectPackage){
        try {
          const inspection = await window.DoloPawsOffline.inspectPackage(trail.id);
          packageAvailable = !!inspection.usable;
        } catch (error) {}
      }
    }
    const recovery = window.DoloPawsHikeSession.recoveryState({
      trailId: trail.id,
      ownerId: user && user.uid || null,
      packageAvailable,
    });
    if(recovery.status === 'empty' || recovery.status === 'unavailable' ||
       recovery.status === 'owner-mismatch'){
      if(recovery.status === 'owner-mismatch'){
        durableSession = null;
        panel.style.display = 'none';
        container.classList.remove('hike-status-visible');
        startBtn.disabled = false;
        setStartLabel('hike.start', 'Start hike');
      }
      return;
    }

    panel.style.display = 'block';
    container.classList.add('hike-status-visible');
    if(recovery.status === 'ready'){
      durableSession = recovery.session;
      if(durableSession.state === 'completion-pending'){
        completionRetry = () => persistCompletionAndShow(durableSession.updatedAt);
        startBtn.disabled = false;
        setStartLabel('hike.retryFinish', 'Save completed hike');
        panel.textContent = window.t('hike.completionPending');
        announceStatus(panel.textContent);
        recoveryActions(false);
        return;
      }
      const progress = durableSession.lastProgress;
      panel.innerHTML = `<strong>${window.t('hike.restoreTitle')}</strong><br>${
        window.t('hike.restoreBody', {
          time: new Date(durableSession.startedAt).toLocaleTimeString([], {
            hour: '2-digit',
            minute: '2-digit',
          }),
          km: progress ? progress.km.toFixed(1) : '0.0',
        })
      }`;
      announceStatus(panel.textContent);
      setStartLabel('hike.resume', 'Resume hike');
      recoveryActions(true);
      return;
    }
    startBtn.disabled = true;
    if(recovery.status === 'other-trail'){
      panel.textContent = window.t('hike.otherTrail');
      announceStatus(panel.textContent);
      recoveryActions(false, recovery.session && recovery.session.trailId);
    }else if(recovery.status === 'missing-package'){
      panel.textContent = window.t('hike.missingPackage');
      announceStatus(panel.textContent);
      recoveryActions(false, null, true);
    }else{
      panel.textContent = recovery.status === 'expired'
        ? window.t('hike.expired')
        : window.t('hike.corrupt');
      announceStatus(panel.textContent);
      recoveryActions(false);
    }
  }

  startBtn.addEventListener('click', () => {
    if(active) finishHike();
    else if(completionRetry) completionRetry();
    else if(durableSession) resumeHike();
    else if(window.ORMADeviceHandoff&&window.ORMADeviceHandoff.shouldHandoff()){
      const phoneUrl=new URL(window.location.href);
      phoneUrl.searchParams.delete('from');
      phoneUrl.searchParams.set('hike','1');
      phoneUrl.hash='start-hike';
      window.ORMADeviceHandoff.open({
        title:'Start this hike on your phone',
        description:'Live hike guidance needs the phone you will carry on the trail.',
        url:phoneUrl.href,
      });
    }
    else requestNewHike();
  });
  pauseBtn.addEventListener('click', pauseHike);

  if(window.DoloPawsAuth) checkForRecovery();
  else window.addEventListener('dolopaws-auth-ready', checkForRecovery, { once: true });
  window.addEventListener('dolopaws-auth-changed', checkForRecovery);

  // Lets the QR/deep-link boot path replace its loading message as soon as
  // the hike controls exist, before the readiness sheet opens.
  window.dispatchEvent(new CustomEvent('dolopaws-hike-mode-ready', {
    detail: { trailId: trail.id },
  }));

  // Deep link from the journal's "Track it live instead →": start recording
  // straight away (the browser still gates this behind its location prompt).
  if (new URLSearchParams(window.location.search).get('hike') === '1'){
    setTimeout(async () => {
      if(window.ORMADeviceHandoff&&window.ORMADeviceHandoff.shouldHandoff()){
        window.ORMADeviceHandoff.open({
          title:'Start this hike on your phone',
          description:'Live hike guidance needs the phone you will carry on the trail.',
          url:window.location.href,
        });
        return;
      }
      await checkForRecovery();
      const loaded = window.DoloPawsHikeSession && window.DoloPawsHikeSession.load();
      if(!active && !durableSession && (!loaded || loaded.status === 'empty')) requestNewHike();
    }, 400);
  }

  return { attachMap };
}
;

// ---- detail-pois.js ----
/**
 * detail-pois.js, real nearby POIs on the trail detail map.
 *
 * The homepage map loads the full OSM POI datasets (huts, bars & cafés,
 * drinking water); the trail detail map used to show only the few
 * hand-curated markers stored on the trail itself, so places visible on
 * the homepage "disappeared" when opening a trail. This file loads the
 * same two GeoJSON files, filters them to the trail's surroundings
 * (~2 km beyond the route's bounding box), and shows them by default, * on a single-trail page, "what's nearby" shouldn't hide behind a toggle.
 *
 * Also registers the filtered features with basemap-poi-click.js, so
 * clicking the base map's own icons gets the enriched popup here too.
 *
 * Usage: initDetailPois(map, trail) inside trail.js's map 'load' handler.
 * Include in trail.html BEFORE trail.js.
 */

function initDetailPois(map, trail){
  // What a dog walker needs unprompted is water and shelter. Food and
  // sightseeing are planning extras and now start behind the Layers control
  // rather than covering the route on first paint.
  // Group names here match the icon-system's ('water'), not trail.js's
  // chip key for the same layer ('fountains').
  const DEFAULT_VISIBLE_GROUPS = new Set(['water', 'huts']);
  if (!trail || typeof trail.lat !== 'number' || typeof trail.lng !== 'number') return;
  const icons = window.DoloPawsIcons;
  const iconMinZoom = icons ? icons.ICON_MIN_ZOOM : 12;
  const trailRegion = trail.region || (window.DoloPawsRegionalData
    && window.DoloPawsRegionalData.regionForTrail(trail.id)) || 'dolomites';
  const regionalPoiUrl = kind => window.DoloPawsRegionalData
    ? window.DoloPawsRegionalData.poiUrl(trailRegion, kind)
    : (kind === 'water' ? './water-sources-all-regions.geojson' : './huts-bars-all-regions.geojson');

  // Bounding box of the route (or trailhead) plus ~2 km padding.
  let minLat = trail.lat, maxLat = trail.lat, minLng = trail.lng, maxLng = trail.lng;
  (trail.path || []).forEach(p => {
    if (p[0] < minLat) minLat = p[0];
    if (p[0] > maxLat) maxLat = p[0];
    if (p[1] < minLng) minLng = p[1];
    if (p[1] > maxLng) maxLng = p[1];
  });
  const PAD = 0.02;
  minLat -= PAD; maxLat += PAD; minLng -= PAD; maxLng += PAD;

  const inBox = f => {
    const g = f.geometry;
    if (!g || g.type !== 'Point') return false;
    const [lng, lat] = g.coordinates;
    return lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng;
  };

  const esc = (typeof trEsc === 'function') ? trEsc
    : s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  // Every popup states IN WORDS what the place is, an icon plus an
  // elevation is a riddle, not information.
  function tt(key, fallback){
    if(!window.t) return fallback;
    const v = window.t(key);
    return v === key ? fallback : v;
  }
  function poiPopupHtml(props){
    // Place type: icon-system SVG (same visual language as the page chrome)
    // plus a plain-text label, no emoji.
    let typeLabel = tt('poi.place', 'Point of interest'), iconKey = null;
    if (props.tourism === 'alpine_hut') { typeLabel = tt('legend.hut', 'Mountain hut'); iconKey = 'hut'; }
    else if (props.tourism === 'wilderness_hut') { typeLabel = tt('poi.wildhut', 'Wilderness hut'); iconKey = 'hut'; }
    else if (props.amenity === 'shelter') { typeLabel = tt('poi.shelter', 'Shelter'); iconKey = 'hut'; }
    else if (props.amenity === 'bar') { typeLabel = 'Bar'; iconKey = 'food'; }
    else if (props.amenity === 'pub') { typeLabel = 'Pub'; iconKey = 'food'; }
    else if (props.amenity === 'cafe') { typeLabel = 'Café'; iconKey = 'food'; }
    else if (props.amenity === 'restaurant') { typeLabel = tt('poi.restaurant', 'Restaurant'); iconKey = 'food'; }
    else if (props.amenity === 'fast_food') { typeLabel = tt('poi.fastfood', 'Snack bar'); iconKey = 'food'; }
    else if (props.amenity === 'drinking_water' || props.amenity === 'water_point') { typeLabel = tt('legend.water', 'Drinking water'); iconKey = 'water'; }
    else if (props.natural === 'spring') { typeLabel = tt('poi.spring', 'Spring'); iconKey = 'water'; }
    else if (props.amenity === 'fountain') { typeLabel = tt('poi.fountain', 'Fountain'); iconKey = 'water'; }
    else if (props.amenity === 'toilets') { typeLabel = tt('poi.toilets', 'Public toilets'); iconKey = 'toilets'; }
    else if (props.man_made === 'water_tap') { typeLabel = tt('poi.tap', 'Water tap'); iconKey = 'water'; }
    else if (props.tourism === 'viewpoint') { typeLabel = tt('poi.viewpoint', 'Viewpoint'); iconKey = 'camera'; }
    else if (props.tourism === 'picnic_site' || props.leisure === 'picnic_table' || props.amenity === 'bbq') { typeLabel = tt('poi.picnic', 'Picnic spot'); iconKey = 'picnic'; }
    else if (props.tourism === 'museum') { typeLabel = tt('poi.museum', 'Museum'); iconKey = 'sight'; }
    else if (props.tourism === 'artwork') { typeLabel = tt('poi.artwork', 'Artwork'); iconKey = 'sight'; }
    else if (props.tourism === 'attraction') { typeLabel = tt('poi.attraction', 'Attraction'); iconKey = 'sight'; }
    else if (props.tourism === 'information') { typeLabel = tt('poi.info', 'Visitor information'); iconKey = 'information'; }
    else if (props.historic) { typeLabel = tt('poi.historic', 'Historic site'); iconKey = 'sight'; }
    const typeIcon = (iconKey && icons && icons.renderIconSvg)
      ? `<span style="display:inline-block;vertical-align:-2px;margin-right:3px;">${icons.renderIconSvg(iconKey, { mode: 'inline', color: 'currentColor', size: 13 })}</span>`
      : '';
    let html = `<div class="dp-poi-popup"><span class="dp-poi-type">${typeIcon}${esc(typeLabel)}</span>`;
    if (props.name) html += `<strong class="dp-poi-name">${esc(props.name)}</strong>`;
    if (props.ele) html += `<span>${esc(props.ele)} m elevation</span>`;
    if (props.opening_hours) html += `<span>Hours: ${esc(props.opening_hours)}</span>`;
    const phone = props.phone || props['contact:phone'];
    if (phone) html += `<span>Phone: ${esc(phone)}</span>`;
    const site = props.website || props['contact:website'];
    if (site && /^https?:\/\//.test(site)) html += `<a href="${esc(site)}" target="_blank" rel="noopener">Website</a>`;
    if (props.dog === 'yes') html += `<span class="dp-poi-dog">Dogs welcome</span>`;
    else if (props.dog === 'leashed') html += `<span class="dp-poi-dog">Dogs on leash</span>`;
    else if (props.dog === 'no') html += `<span class="dp-poi-dog">No dogs</span>`;
    if (props.outdoor_seating && props.outdoor_seating !== 'no') html += `<span>Outdoor seating</span>`;
    return html + '</div>';
  }

  function addPoiLayerSet(sourceId, features, group){
    if (!features.length || map.getSource(sourceId)) return;
    const circleColor = icons ? icons.getPoiCircleColorExpression(group) : '#5A5548';
    map.addSource(sourceId, {
      type: 'geojson',
      data: { type: 'FeatureCollection', features },
    });
    map.addLayer({
      id: sourceId + '-layer-lowzoom',
      type: 'circle',
      source: sourceId,
      filter: ['!', ['has', 'point_count']],
      maxzoom: iconMinZoom,
      layout: { visibility: DEFAULT_VISIBLE_GROUPS.has(group) ? 'visible' : 'none' },
      paint: {
        'circle-radius': 4,
        'circle-color': circleColor,
        'circle-opacity': 0.7,
        'circle-stroke-width': 1.25,
        'circle-stroke-color': '#fff',
      },
    });
    map.addLayer({
      id: sourceId + '-layer',
      type: 'symbol',
      source: sourceId,
      filter: ['!', ['has', 'point_count']],
      minzoom: iconMinZoom,
      layout: {
        visibility: DEFAULT_VISIBLE_GROUPS.has(group) ? 'visible' : 'none',
        'icon-image': icons ? icons.getPoiMapIconExpression(group) : '',
        'icon-size': 0.82,
        // Collision on, generous padding: the previous settings let ~40
        // identical pins stack over a 7.5 km route until the route itself
        // was the least visible thing on the map.
        'icon-padding': 12,
        'icon-allow-overlap': false,
        'icon-optional': false,
        'text-field': ['coalesce', ['get', 'name'], ''],
        'text-font': ['Noto Sans Regular'],
        'text-size': 11,
        'text-anchor': 'top',
        'text-offset': [0, 1.15],
        'text-max-width': 12,
        'text-padding': 4,
        'text-optional': true,
      },
      paint: {
        'icon-opacity': 0.92,
        'text-color': '#243128',
        'text-halo-color': 'rgba(255,255,255,.96)',
        'text-halo-width': 2,
      },
    });
    [sourceId + '-layer', sourceId + '-layer-lowzoom'].forEach((layerId) => {
      map.on('mouseenter', layerId, () => { map.getCanvas().style.cursor = 'pointer'; });
      map.on('mouseleave', layerId, () => { map.getCanvas().style.cursor = ''; });
    });
    [sourceId + '-layer', sourceId + '-layer-lowzoom'].forEach((layerId) => map.on('click', layerId, (e) => {
      const f = e.features[0];
      new maplibregl.Popup({ offset: 10, maxWidth: '220px' })
        .setLngLat(f.geometry.coordinates)
        .setHTML(poiPopupHtml(f.properties))
        .addTo(map);
    }));
  }

  // Features already drawn by the huts/bars/water layers, so the corridor
  // amenities file (which overlaps them) only contributes NEW places.
  const drawnIds = new Set();
  const noteDrawn = features => features.forEach(f => {
    const id = f.properties && f.properties['@id'];
    if (id) drawnIds.add(id);
  });

  // Huts + food & drink (same file the homepage uses; browser-cached)
  const hutsBarsLoad = fetch(regionalPoiUrl('huts-bars'))
    .then(r => r.ok ? r.json() : null)
    .then(data => {
      if (!data) return;
      const near = (data.features || []).filter(inBox);
      if (!near.length) return;
      noteDrawn(near);
      const isHut = p => p && (p.tourism === 'alpine_hut' || p.tourism === 'wilderness_hut' || p.amenity === 'shelter');
      const huts = near.filter(f => isHut(f.properties));
      const bars = near.filter(f => !isHut(f.properties));
      addPoiLayerSet('detail-huts', huts, 'huts');
      addPoiLayerSet('detail-bars', bars, 'food');
      // Feed the base-map click enrichment on this page too.
      if (typeof registerPoiFeatures === 'function') registerPoiFeatures(near);
      if (typeof window.onDetailPoisReady === 'function'){
        try { window.onDetailPoisReady(near); } catch (e) {}
      }
    })
    .catch(() => { /* nearby POIs are a bonus, never break the page */ });

  // Drinking water
  const waterLoad = fetch(regionalPoiUrl('water'))
    .then(r => r.ok ? r.json() : null)
    .then(data => {
      if (!data) return;
      const near = (data.features || []).filter(inBox);
      noteDrawn(near);
      if (typeof window.onDetailWaterReady === 'function'){
        try { window.onDetailWaterReady(near); } catch (e) {}
      }
      addPoiLayerSet('detail-water', near, 'water');
    })
    .catch(() => {});

  // Viewpoints, picnic spots, selected sights and toilets from the trail-corridor
  // amenity sweep (data/trail-amenities/). Waits for the two layers above so
  // anything they already drew is skipped rather than doubled.
  const PLACE_KINDS = ['viewpoint', 'picnic', 'sight', 'toilets', 'information'];
  Promise.allSettled([hutsBarsLoad, waterLoad])
    .then(() => fetch('data/trail-amenities/' + trailRegion + '-amenities.geojson'))
    .then(r => r.ok ? r.json() : null)
    .then(data => {
      if (!data) return;
      const near = (data.features || []).filter(f =>
        inBox(f) &&
        PLACE_KINDS.includes(f.properties && f.properties.kind) &&
        !(f.properties && f.properties.kind === 'sight' && f.properties.historic) &&
        !drawnIds.has(f.properties['@id']));
      if (!near.length) return;
      addPoiLayerSet('detail-places', near, 'places');
      if (typeof registerPoiFeatures === 'function') registerPoiFeatures(near);
      if (typeof window.onDetailPlacesReady === 'function'){
        try { window.onDetailPlacesReady(near); } catch (e) {}
      }
    })
    .catch(() => {});
}
;

// ---- trail-photo-provenance.js ----
(function(root,factory){
  const api=factory();
  if(typeof module==='object'&&module.exports)module.exports=api;
  if(root)root.DoloPawsPhotoProvenance=api;
})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';

  function clean(value,maximum=1000){return String(value||'').trim().slice(0,maximum);}

  function normalizeCredit(value,fallbackUrl){
    const record=typeof value==='string'?{text:value}:(value&&typeof value==='object'?value:null);
    const text=clean(record?.text,500);if(!text)return null;
    const url=clean(record?.url||fallbackUrl);
    return {text,url:/^https:\/\//i.test(url)?url:'',bare:record?.bare===true,label:record?.bare===true?text:`Photo: ${text}`};
  }

  function heroCredit(trail){return normalizeCredit(trail?.imageCredit,trail?.imageSourcePage);}

  function editorialPhotos(trail){
    return (Array.isArray(trail?.editorialPhotos)?trail.editorialPhotos:[])
      .filter(photo=>photo&&photo.source==='orma-editorial'&&/^images\/[A-Za-z0-9_./-]+\.(?:avif|jpe?g|png|webp)$/i.test(clean(photo.image)))
      .map((photo,index)=>({...photo,image:clean(photo.image),isEditorial:true,editorialOrder:index,status:'approved'}));
  }

  function photoCaption(photo){
    const dog=photo?.dogContext?.name;
    const caption=photo?.isEditorial
      ? 'Shared by the ORMA community'
      : (clean(photo?.caption,500)||(dog?`Shared by ${dog}’s human`:'Shared by the ORMA community'));
    const credit=normalizeCredit(photo?.credit,photo?.creditUrl);
    const status=photo?.status==='reported'?'Reported, under review':'';
    return [caption,photo?.isEditorial?'':credit?.label,status].filter(Boolean).join(' · ');
  }

  function photoAlt(photo){return clean(photo?.alt,500)||clean(photo?.caption,500)||'Trail photograph';}

  return {clean,normalizeCredit,heroCredit,editorialPhotos,photoCaption,photoAlt};
});
;

// ---- trail-weather-window.js ----
(function(root,factory){
  const api=factory();
  if(typeof module==='object'&&module.exports)module.exports=api;
  if(root)root.DoloPawsWeatherWindow=api;
})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';

  const DAYLIGHT_BUFFER_MINUTES=60;
  const PLANNING_BUFFER_MINUTES=30;
  const PREFERRED_START_MINUTES=9*60;
  const SUNSET_NOTE_WINDOW_MINUTES=2*60;
  // Heat thresholds already shipped on the trail page's conditions card,
  // reused here so one number does not mean two different things in two places.
  const WARM_C=22;
  const HOT_C=28;

  function dayKey(value){return String(value||'').slice(0,10);}

  function minuteOfDay(value){
    const match=String(value||'').match(/T(\d{2}):(\d{2})/);
    return match?Number(match[1])*60+Number(match[2]):null;
  }

  function formatTime(minutes){
    const value=Math.max(0,Math.round(Number(minutes)||0));
    return `${String(Math.floor(value/60)%24).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`;
  }

  function average(values){
    const finite=values.filter(Number.isFinite);
    return finite.length?finite.reduce((sum,value)=>sum+value,0)/finite.length:Infinity;
  }

  // Trail durations are authored as strings, usually a range ("2–2.5", "3–4")
  // and sometimes annotated ("2.5–3 (estimated)"). Number() cannot parse those,
  // so a bare Number() silently collapsed every range to the 1 h fallback and
  // planned a four-hour hike as if it finished in one. Take the upper bound of
  // whatever numbers the string carries, so the finish-before-dark maths never
  // underestimates how long the walk takes.
  function parseDurationHours(value){
    if(typeof value==='number')return value;
    const matches=String(value==null?'':value).match(/\d+(?:\.\d+)?/g);
    return matches&&matches.length?Math.max(...matches.map(Number)):NaN;
  }

  function recommendation(input){
    const durationHours=Math.min(12,Math.max(.5,parseDurationHours(input?.durationHours)||1));
    const durationMinutes=Math.ceil(durationHours*60);
    const dailyDates=Array.isArray(input?.dailyDates)?input.dailyDates:[];
    const sunrises=Array.isArray(input?.sunrises)?input.sunrises:[];
    const sunsets=Array.isArray(input?.sunsets)?input.sunsets:[];
    const hourlyTimes=Array.isArray(input?.hourlyTimes)?input.hourlyTimes:[];
    const hourlyTemps=Array.isArray(input?.hourlyTemps)?input.hourlyTemps:[];
    const currentDay=dayKey(input?.currentTime)||dayKey(dailyDates[0]);
    const currentMinute=minuteOfDay(input?.currentTime);
    if(!dailyDates.length||!currentDay||currentMinute===null)return null;

    const hours=hourlyTimes.map((time,index)=>({
      day:dayKey(time),
      minute:minuteOfDay(time),
      temp:Number(hourlyTemps[index]),
    })).filter(hour=>hour.day&&hour.minute!==null);

    // A reader who picked a day on the homepage is asking about that day, not
    // about whichever of the next three happens to be coolest. Without one,
    // the scan is unchanged: the first day that offers a usable window wins.
    const preferredDate=/^\d{4}-\d{2}-\d{2}$/.test(input?.preferredDate||'')?input.preferredDate:'';
    const lastDay=preferredDate?dailyDates.length:Math.min(3,dailyDates.length);
    for(let dayOffset=0;dayOffset<lastDay;dayOffset+=1){
      const date=dayKey(dailyDates[dayOffset]);
      if(preferredDate&&date!==preferredDate)continue;
      const sunrise=minuteOfDay(sunrises[dayOffset]);
      const sunset=minuteOfDay(sunsets[dayOffset]);
      if(!date||sunrise===null||sunset===null)continue;
      const earliestDaylightStart=Math.ceil(sunrise/60)*60;
      const latestStart=sunset-DAYLIGHT_BUFFER_MINUTES-durationMinutes;
      const earliestStart=dayOffset===0
        ? Math.max(earliestDaylightStart,Math.ceil((currentMinute+PLANNING_BUFFER_MINUTES)/60)*60)
        : earliestDaylightStart;
      const candidates=hours.filter(hour=>hour.day===date&&hour.minute>=earliestStart&&hour.minute<=latestStart);
      if(!candidates.length)continue;

      const practicalStart=Math.max(earliestStart,PREFERRED_START_MINUTES);
      const scored=candidates.map(candidate=>{
        const routeTemps=hours
          .filter(hour=>hour.day===date&&hour.minute>=candidate.minute&&hour.minute<candidate.minute+durationMinutes)
          .map(hour=>hour.temp)
          .filter(Number.isFinite);
        return {
          ...candidate,
          averageTemp:average(routeTemps),
          maxTemp:routeTemps.length?Math.max(...routeTemps):Infinity,
          hasTemperature:routeTemps.length>0,
          practicalDistance:Math.abs(candidate.minute-practicalStart),
        };
      });
      const weatherCandidates=scored.filter(candidate=>candidate.hasTemperature);
      const comfortable=weatherCandidates.filter(candidate=>candidate.maxTemp<WARM_C);
      let chosen;
      let reason;
      if(comfortable.length){
        // If every viable hour is cool, do not mistake dawn for a useful
        // recommendation merely because it is one degree colder. Prefer a
        // practical 09:00 start (or the next viable hour today). A genuinely
        // warm afternoon still narrows this pool to the cooler earlier hours.
        chosen=comfortable.sort((a,b)=>(a.practicalDistance-b.practicalDistance)||(a.minute-b.minute))[0];
        reason=weatherCandidates.some(candidate=>candidate.maxTemp>=WARM_C)?'avoid-heat':'comfortable';
      }else if(weatherCandidates.length){
        // No fully cool window exists: minimise the hottest hour across the
        // walk, then its average temperature, before breaking ties by time.
        chosen=weatherCandidates.sort((a,b)=>(a.maxTemp-b.maxTemp)||(a.averageTemp-b.averageTemp)||(a.minute-b.minute))[0];
        reason='least-warm';
      }else{
        chosen=scored.sort((a,b)=>(a.practicalDistance-b.practicalDistance)||(a.minute-b.minute))[0];
        reason='daylight-only';
      }
      return {
        dayOffset,
        date,
        startMinutes:chosen.minute,
        finishMinutes:chosen.minute+durationMinutes,
        sunsetMinutes:sunset,
        daylightBufferMinutes:DAYLIGHT_BUFFER_MINUTES,
        durationHours,
        maxTemperatureC:Number.isFinite(chosen.maxTemp)?Math.round(chosen.maxTemp):null,
        reason,
      };
    }
    return null;
  }

  function dayLabel(date){
    const parsed=/^\d{4}-\d{2}-\d{2}$/.test(date||'')?new Date(`${date}T12:00:00`):null;
    if(!parsed||Number.isNaN(parsed.getTime()))return date;
    try{
      return parsed.toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'short'});
    }catch(error){ return date; }
  }

  function markup(result){
    if(!result)return 'No route-length daylight recommendation is available. Check the official forecast and plan to finish well before dusk.';
    const start=formatTime(result.startMinutes);
    const finish=formatTime(result.finishMinutes);
    // A day a reader picked is now the common case, not the exception, so it
    // is named the way they picked it rather than printed as an ISO string.
    const when=result.dayOffset===0
      ? `<strong>${start}</strong>`
      : result.dayOffset===1
        ? `tomorrow at <strong>${start}</strong>`
        : `on ${dayLabel(result.date)} at <strong>${start}</strong>`;
    const maximum=Number.isFinite(result.maxTemperatureC)?` (up to ${result.maxTemperatureC}°C)`:'';
    let lead;
    let close='';
    if(result.reason==='comfortable')lead=`The forecast stays cool during the walk${maximum}. Suggested start: ${when}`;
    else if(result.reason==='avoid-heat'){
      lead=`Cooler forecast window${maximum}: start ${when}`;
      close=' before the warmer part of the day';
    }else if(result.reason==='least-warm'){
      lead=`Least-warm forecast window${maximum}: start ${when}`;
      close=' before the hottest available hours';
    }else lead=`Suggested daylight start: ${when}`;
    const daylightMargin=result.sunsetMinutes-result.finishMinutes;
    const daylight=daylightMargin<=SUNSET_NOTE_WINDOW_MINUTES
      ? ` This leaves ${Math.max(1,Math.floor(daylightMargin/60))} hour${daylightMargin>=120?'s':''} before sunset.`
      : '';
    return `${lead} · for this ${result.durationHours} h route, finish around <strong>${finish}</strong>${close}.${daylight}`;
  }

  // The hour heat actually becomes a problem today, read off the forecast
  // rather than asserted. Returns null when the forecast never crosses the
  // threshold, so the caller can stay silent instead of inventing an hour.
  function heatOnset(input){
    const times=Array.isArray(input&&input.hourlyTimes)?input.hourlyTimes:[];
    const temps=Array.isArray(input&&input.hourlyTemps)?input.hourlyTemps:[];
    if(!times.length||times.length!==temps.length)return null;
    const today=dayKey(input.currentTime);
    const nowMinute=minuteOfDay(input.currentTime);
    if(!today||nowMinute===null)return null;
    const threshold=Number.isFinite(input.thresholdC)?input.thresholdC:HOT_C;

    for(let index=0;index<times.length;index+=1){
      if(dayKey(times[index])!==today)continue;
      const minute=minuteOfDay(times[index]);
      const temp=Number(temps[index]);
      if(minute===null||!Number.isFinite(temp))continue;
      if(minute<nowMinute)continue;
      if(temp>=threshold)return {minutes:minute,label:formatTime(minute),temperatureC:Math.round(temp)};
    }
    return null;
  }

  // Today's heat, in the vocabulary the recommendation engine reads.
  function currentConditions(input){
    const temp=Number(input&&input.temperatureC);
    if(!Number.isFinite(temp))return {status:'not-provided'};
    const heatRisk=temp>=HOT_C?'high':temp>=WARM_C?'moderate':'low';
    const onset=heatOnset(input);
    return {
      status:'known',
      heatRisk,
      // Only present when the forecast actually crosses the threshold later
      // today. Absent means the engine says nothing about an hour.
      hotFromLabel:onset&&heatRisk!=='high'?onset.label:null,
      // SCORE-01 requires a conditions snapshot to carry its observation time
      // and to stop being described as live once stale. Stamping it here means
      // a caller cannot forget it; isFresh() below is the shared expiry rule.
      capturedAt:Number.isFinite(Number(input&&input.capturedAt))?Number(input.capturedAt):Date.now(),
    };
  }

  // Weather goes out of date faster than a page stays open. pre-hike-readiness
  // already treats a forecast older than thirty minutes as unusable; the score
  // uses the same rule so the two cannot disagree about what "now" means.
  const CONDITIONS_MAX_AGE_MS=30*60*1000;

  function isFresh(conditions,now){
    if(!conditions||conditions.status!=='known')return false;
    const captured=Number(conditions.capturedAt);
    if(!Number.isFinite(captured))return false;
    const at=Number.isFinite(Number(now))?Number(now):Date.now();
    return at-captured<=CONDITIONS_MAX_AGE_MS&&at>=captured;
  }

  // What the engine should be handed: the snapshot while it is current, and an
  // explicit omission once it is not. Never a stale snapshot presented as live.
  function scoringConditions(conditions,now){
    return isFresh(conditions,now)?conditions:{status:'not-provided'};
  }

  return {DAYLIGHT_BUFFER_MINUTES,PLANNING_BUFFER_MINUTES,PREFERRED_START_MINUTES,WARM_C,HOT_C,CONDITIONS_MAX_AGE_MS,minuteOfDay,formatTime,dayLabel,parseDurationHours,recommendation,markup,heatOnset,currentConditions,isFresh,scoringConditions};
});
;

// ---- scoring-conditions.js ----
// One answer to "what is the weather doing for this trail, for scoring".
//
// A match percentage is a promise that the same dog on the same trail gets the
// same number wherever it is read. It did not. Five surfaces passed today's
// conditions to the engine and eight did not, so the engine reported conditions
// as not included and returned the ignore-the-day score instead. Across
// representative dogs, trails and weather the two answers differ in about a
// third of cases, by a median of 10 points and as much as 25 -- and in some of
// those the verdict word changes too, so one screen says "Strong option" while
// another says "Possible with cautions" about the same walk on the same day.
//
// Worst of it was on one page: trail.js and trail-blueprint.js ship in the same
// bundle and paint three personal-match numbers on a trail page, of which only
// the ring included the day.
//
// The two sources were never in conflict about meaning -- both end in
// weatherWindow.scoringConditions, which applies the shared expiry -- only about
// which snapshot they hold. So this picks between them rather than replacing
// them, and every caller asks the same question the same way.
(function(root, factory){
  const api = factory(root);
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.ORMAScoringConditions = api;
})(typeof window !== 'undefined' ? window : globalThis, function(root){
  'use strict';

  // A page that fetched one forecast knows which trail it was for. Without
  // that, a trail page would hand its own valley's weather to the nearby picks
  // beside it, which are different trails at different altitudes -- a wrong
  // number rather than an absent one.
  let declaredTrailId = null;
  let declaredConditions = null;

  function declareForTrail(trailId, conditions){
    declaredTrailId = trailId == null ? null : String(trailId);
    declaredConditions = conditions || null;
  }

  function reset(){
    declaredTrailId = null;
    declaredConditions = null;
  }

  /**
   * Conditions for scoring `trail`, or undefined when the day is not known for
   * it. Undefined is a real answer: the engine reports conditions as not
   * included and says so on the card, which is honest. Handing over another
   * trail's forecast to avoid an undefined would not be.
   *
   * An area forecast wins over a single declared one because it is computed per
   * trail, altitude included, and answers for any trail rather than one.
   */
  function forTrail(trail){
    const scope = root || {};
    const area = scope.DoloPawsHomeConditions;
    if(area && typeof area.forTrail === 'function'){
      const found = area.forTrail(trail);
      if(found) return found;
    }
    const id = trail && trail.id != null ? String(trail.id) : null;
    if(declaredConditions && id && id === declaredTrailId) return declaredConditions;
    return undefined;
  }

  return { forTrail, declareForTrail, reset };
});
;

// ---- trail-reports.js ----
/**
 * trail-reports.js, community dog-safety flags on the trail detail page.
 *
 * Renders active flags as banners in a "Trail reports" section, places
 * km-tagged flags as ⚠️ markers on the route map, and provides the
 * "Report something" modal (structured flag types, optional position
 * slider, short note).
 *
 * Product rule this file enforces: community flags display ALONGSIDE the
 * ORMA verified safety score, they never alter it. Type-specific expiry
 * removes stale flags from the active safety view without deleting history.
 *
 * Usage: initTrailReports(map, trail) inside trail.js's map 'load'
 * handler. Include this file in trail.html BEFORE trail.js.
 * Data functions live in firebase-init.js (window.DoloPawsCommunity).
 */

const FLAG_TYPES = {
  'guard-dogs-livestock': { icon: '🐑', label: 'Livestock guard dogs on route', severe: true },
  'dangerous-terrain':    { icon: '⚠️', label: 'Terrain dangerous for dogs',    severe: true },
  'not-dog-friendly':     { icon: '🚫', label: 'Not dog-friendly',              severe: true },
  'water-dry':            { icon: '💧', label: 'Water source dry',              severe: false },
  'lift-refused-dog':     { icon: '🚡', label: 'Lift refused a dog',            severe: false },
  'other':                { icon: '📝', label: 'Other',                          severe: false },
};

function trEsc(s){
  return String(s).replace(/[&<>"']/g,
    c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

// One star glyph for every rating UI on the page (rows, average, picker), // filled or outlined, sized per context. Replaces the mixed ★/☆ text chars.
function starSvgIcon(filled, size){
  const s = size || 13;
  return filled
    ? `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style="flex:none;display:block;"><path d="M12 2.5l2.9 6.1 6.6.8-4.9 4.5 1.3 6.6L12 18l-5.9 3.1 1.3-6.6L2.5 9.4l6.6-.8z"/></svg>`
    : `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true" style="flex:none;display:block;"><path d="M12 3.6l2.6 5.4 5.9.7-4.4 4 1.2 5.9L12 16.8l-5.3 2.8 1.2-5.9-4.4-4 5.9-.7z"/></svg>`;
}

function initTrailReports(map, trail){
  const listEl = document.getElementById('trailLegacyHazards') || document.getElementById('trailFlagsList');
  const addBtn = document.getElementById('addReportBtn');
  const reviewListEl = document.getElementById('trailReviewsList');
  const addReviewBtn = document.getElementById('addReviewBtn');
  const ratingEl = document.getElementById('communityRating');
  const heroRatingEl = document.getElementById('heroRating');
  const photosListEl = document.getElementById('trailPhotosList');
  const photoStripPrev = document.getElementById('trailPhotosPrev');
  const photoStripNext = document.getElementById('trailPhotosNext');
  const editorialPhotos = window.DoloPawsPhotoProvenance
    ? window.DoloPawsPhotoProvenance.editorialPhotos(trail)
    : [];
  let actionStatusTimer = null;
  let closeActivePhotoViewer = null;

  function showActionStatus(message){
    let status = document.getElementById('trailActionStatus');
    if (!status){
      status = document.createElement('div');
      status.id = 'trailActionStatus';
      status.className = 'dw-toast';
      status.setAttribute('role', 'status');
      status.setAttribute('aria-live', 'polite');
      document.body.appendChild(status);
    }
    if (actionStatusTimer) clearTimeout(actionStatusTimer);
    status.textContent = message;
    status.hidden = false;
    status.className = 'dw-toast dw-toast--in';
    actionStatusTimer = setTimeout(() => {
      status.hidden = true;
      status.className = 'dw-toast';
    }, 4200);
  }
  const addPhotoBtn = document.getElementById('addPhotoBtn');
  if (!listEl) return;

  let flagMarkers = [];

  function flagDate(f){
    // Firestore Timestamp -> Date (guard both shapes and nulls)
    if (f.createdAt && typeof f.createdAt.toDate === 'function') return f.createdAt.toDate();
    return null;
  }

  function reviewDate(review){
    if (review.createdAt && typeof review.createdAt.toDate === 'function') return review.createdAt.toDate();
    return null;
  }

  function renderReviews(reviews){
    const visible = reviews.filter(review =>
      window.DoloPawsCommunityStates &&
      window.DoloPawsCommunityStates.countsTowardRating(review.status) &&
      Number(review.rating) >= 1 && Number(review.rating) <= 5
    )
      .sort((a, b) => {
        const aDate = reviewDate(a), bDate = reviewDate(b);
        return (bDate ? bDate.getTime() : 0) - (aDate ? aDate.getTime() : 0);
      });

    if (ratingEl){
      if (!visible.length){
        ratingEl.hidden = true;
      } else {
        const average = visible.reduce((total, review) => total + Number(review.rating), 0) / visible.length;
        ratingEl.hidden = false;
        ratingEl.innerHTML = `<span class="community-rating__stars" aria-label="${average.toFixed(1)} out of 5 stars">${starSvgIcon(true, 13)}</span><strong>${average.toFixed(1)}</strong><span>${visible.length} ${visible.length === 1 ? 'review' : 'reviews'}</span>`;
      }
    }
    if (heroRatingEl){
      const starSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style="flex:none;"><path d="M12 2.5l2.9 6.1 6.6.8-4.9 4.5 1.3 6.6L12 18l-5.9 3.1 1.3-6.6L2.5 9.4l6.6-.8z"/></svg>';
      heroRatingEl.hidden = false;
      if (!visible.length){
        // Honest zero state in the design's rating slot: invite the first
        // review instead of pretending a score exists.
        heroRatingEl.classList.add('is-empty');
        heroRatingEl.innerHTML = `${starSvg} <span class="cnt">No reviews yet</span>`;
      } else {
        const average = visible.reduce((total, review) => total + Number(review.rating), 0) / visible.length;
        heroRatingEl.classList.remove('is-empty');
        heroRatingEl.innerHTML = `${starSvg} ${average.toFixed(1)} <span class="cnt">· ${visible.length} ${visible.length === 1 ? 'review' : 'reviews'}</span>`;
      }
      // The rating is a shortcut to the reviews section either way.
      heroRatingEl.style.cursor = 'pointer';
      heroRatingEl.onclick = () => {
        const list = document.getElementById('trailReviewsList');
        if (list) list.scrollIntoView({ behavior: 'smooth', block: 'center' });
      };
    }

    if (!reviewListEl) return;
    if (!visible.length){
      reviewListEl.innerHTML = `<div class="empty-state empty-state--compact">
        <p class="empty-state__title">No reviews yet</p>
        <p class="empty-state__copy">Share how the route felt for your dog and what another owner should know.</p>
        <div class="empty-state__actions"><button type="button" class="empty-state__action" data-empty-review>Leave the first review</button></div>
      </div>`;
      const emptyReview = reviewListEl.querySelector('[data-empty-review]');
      if (emptyReview) emptyReview.addEventListener('click', openReviewModal);
      return;
    }

    reviewListEl.innerHTML = visible.slice(0, 3).map(review => {
      const date = reviewDate(review);
      const dateLabel = date ? date.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : 'Recently';
      const dogName = review.dogContext && review.dogContext.name;
      const reviewer = dogName ? `${trEsc(dogName)}’s human` : 'A ORMA member';
      const stars = [1, 2, 3, 4, 5].map(n => starSvgIcon(n <= Number(review.rating), 13)).join('');
      return `<article class="community-review">
        <div class="community-review__rating" aria-label="${review.rating} out of 5 stars">${stars}</div>
        ${review.status === 'reported' ? '<p class="community-review__notice">Reported · under moderation review</p>' : ''}
        ${review.text ? `<p>${trEsc(review.text)}</p>` : ''}
        <footer>${reviewer} <span>·</span> ${dateLabel}</footer>
      </article>`;
    }).join('');
  }

  function photoCaption(photo){
    if(window.DoloPawsPhotoProvenance)return window.DoloPawsPhotoProvenance.photoCaption(photo);
    const dog = photo.dogContext && photo.dogContext.name;
    const caption = photo.caption
      ? String(photo.caption)
      : (dog ? `Shared by ${dog}’s human` : 'Shared by the ORMA community');
    return caption + (photo.status === 'reported' ? ' · Reported, under review' : '');
  }

  function photoAlt(photo){
    return window.DoloPawsPhotoProvenance
      ? window.DoloPawsPhotoProvenance.photoAlt(photo)
      : photoCaption(photo);
  }

  function openPhotoCarousel(photos, startIndex, returnFocus){
    if (!photos.length) return;
    if (closeActivePhotoViewer) closeActivePhotoViewer(false);

    let currentIndex = Math.max(0, Math.min(Number(startIndex) || 0, photos.length - 1));
    const overlay = document.createElement('div');
    overlay.className = 'trail-photo-viewer';
    overlay.innerHTML = `<div class="trail-photo-viewer__dialog">
      <h2 class="trail-photo-viewer__title">Trail photos</h2>
      <button type="button" class="trail-photo-viewer__close" data-gallery-close aria-label="Close photo gallery">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
      <div class="trail-photo-viewer__stage" data-gallery-stage>
        <button type="button" class="trail-photo-viewer__nav trail-photo-viewer__nav--prev" data-gallery-prev aria-label="Previous photo">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg>
        </button>
        <img data-gallery-image alt="">
        <button type="button" class="trail-photo-viewer__nav trail-photo-viewer__nav--next" data-gallery-next aria-label="Next photo">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg>
        </button>
      </div>
      <div class="trail-photo-viewer__meta">
        <p data-gallery-caption></p>
        <span data-gallery-count aria-live="polite"></span>
      </div>
    </div>`;
    document.body.appendChild(overlay);
    document.body.classList.add('trail-photo-viewer-open');

    const image = overlay.querySelector('[data-gallery-image]');
    const caption = overlay.querySelector('[data-gallery-caption]');
    const count = overlay.querySelector('[data-gallery-count]');
    const previous = overlay.querySelector('[data-gallery-prev]');
    const next = overlay.querySelector('[data-gallery-next]');
    let cleanupKeyboard = () => {};

    function show(index){
      currentIndex = (index + photos.length) % photos.length;
      const photo = photos[currentIndex];
      const label = photoCaption(photo);
      image.src = photo.image;
      image.alt = photoAlt(photo);
      caption.textContent = label;
      count.textContent = `${currentIndex + 1} of ${photos.length}`;
      previous.hidden = photos.length < 2;
      next.hidden = photos.length < 2;
    }

    function close(restoreFocus = true){
      cleanupKeyboard();
      document.body.classList.remove('trail-photo-viewer-open');
      overlay.remove();
      closeActivePhotoViewer = null;
      if (restoreFocus && returnFocus && document.contains(returnFocus)) returnFocus.focus();
    }
    closeActivePhotoViewer = close;

    previous.addEventListener('click', () => show(currentIndex - 1));
    next.addEventListener('click', () => show(currentIndex + 1));
    overlay.querySelector('[data-gallery-close]').addEventListener('click', () => close());
    overlay.addEventListener('click', event => { if (event.target === overlay) close(); });
    overlay.addEventListener('keydown', event => {
      if (event.key === 'ArrowLeft') { event.preventDefault(); show(currentIndex - 1); }
      if (event.key === 'ArrowRight') { event.preventDefault(); show(currentIndex + 1); }
    });

    let touchStartX = null;
    const stage = overlay.querySelector('[data-gallery-stage]');
    stage.addEventListener('touchstart', event => {
      touchStartX = event.changedTouches[0] ? event.changedTouches[0].clientX : null;
    }, { passive:true });
    stage.addEventListener('touchend', event => {
      if (touchStartX === null || !event.changedTouches[0]) return;
      const distance = event.changedTouches[0].clientX - touchStartX;
      touchStartX = null;
      if (Math.abs(distance) < 45 || photos.length < 2) return;
      show(currentIndex + (distance < 0 ? 1 : -1));
    }, { passive:true });

    cleanupKeyboard = enableModalKeyboard(overlay, () => close(), '[data-gallery-close]', returnFocus);
    show(currentIndex);
  }

  function updatePhotoStripControls(total){
    [photoStripPrev, photoStripNext].forEach(button => {
      if (button) button.hidden = total < 2;
    });
  }

  function scrollPhotoStrip(direction){
    if (!photosListEl) return;
    const distance = Math.max(180, Math.round(photosListEl.clientWidth * 0.8));
    if (typeof photosListEl.scrollBy === 'function'){
      photosListEl.scrollBy({ left: direction * distance, behavior:'smooth' });
    } else {
      photosListEl.scrollLeft += direction * distance;
    }
  }

  if (photoStripPrev) photoStripPrev.addEventListener('click', () => scrollPhotoStrip(-1));
  if (photoStripNext) photoStripNext.addEventListener('click', () => scrollPhotoStrip(1));

  function renderPhotos(photos){
    if (!photosListEl) return;
    const visible = editorialPhotos.concat(photos.filter(photo =>
      window.DoloPawsCommunityStates&&window.DoloPawsCommunityStates.isPublic(photo.status)&&
      typeof photo.image==='string'&&photo.image.startsWith('data:image/')
    ))
      .sort((a, b) => {
        if(a.isEditorial!==b.isEditorial)return a.isEditorial?-1:1;
        if(a.isEditorial&&b.isEditorial)return a.editorialOrder-b.editorialOrder;
        const aDate = reviewDate(a), bDate = reviewDate(b);
        return (bDate ? bDate.getTime() : 0) - (aDate ? aDate.getTime() : 0);
      });
    updatePhotoStripControls(visible.length);
    if (!visible.length){
      photosListEl.innerHTML = `<div class="empty-state empty-state--compact">
        <p class="empty-state__title">No trail photos yet</p>
        <p class="empty-state__copy">Add a recent, useful view so others can recognise the route and conditions.</p>
        <div class="empty-state__actions"><button type="button" class="empty-state__action" data-empty-photo>Add the first photo</button></div>
      </div>`;
      const emptyPhoto = photosListEl.querySelector('[data-empty-photo]');
      if (emptyPhoto) emptyPhoto.addEventListener('click', openPhotoModal);
      return;
    }
    photosListEl.innerHTML = visible.map((photo, index) => {
      const caption = trEsc(photoCaption(photo));
      return `<figure class="community-photo">
        <button type="button" class="community-photo__open" data-photo-index="${index}" aria-label="Open photo ${index + 1} of ${visible.length}: ${caption}">
          <img src="${trEsc(photo.image)}" alt="${trEsc(photoAlt(photo))}" loading="lazy" decoding="async">
        </button>
      </figure>`;
    }).join('');
    photosListEl.querySelectorAll('[data-photo-index]').forEach(button => {
      button.addEventListener('click', () => openPhotoCarousel(visible, Number(button.dataset.photoIndex), button));
    });
  }

  function isExpired(f){
    return !window.DoloPawsCommunityStates ||
      !window.DoloPawsCommunityStates.hazardIsExpired ||
      window.DoloPawsCommunityStates.hazardIsExpired(f);
  }

  function trustLabel(f){
    const state = window.DoloPawsCommunityStates.hazardTrustState(f);
    const key = {
      'official-confirmed':'reports.officialConfirmed',
      'dolopaws-reviewed':'reports.dolopawsReviewed',
      'community-confirmed':'reports.communityConfirmed',
      'community-disputed':'reports.communityDisputed',
      unconfirmed:'reports.unconfirmed',
    }[state];
    return window.t(key);
  }

  function dogContextLine(f){
    const dc = f.dogContext;
    if (!dc || (!dc.name && !dc.breed)) return '';
    const who = [dc.name ? `${dc.name}'s human` : null, dc.breed || null]
      .filter(Boolean).join(' · ');
    return window.t('reports.reportedBy', {who: trEsc(who)});
  }

  function render(flags){
    flags = flags.filter(flag =>
      window.DoloPawsCommunityStates &&
      window.DoloPawsCommunityStates.isPublic(flag.status) &&
      !isExpired(flag)
    );
    flags.sort((a, b) => {
      const da = flagDate(a), db = flagDate(b);
      return (db ? db.getTime() : 0) - (da ? da.getTime() : 0);
    });

    const uid = window.DoloPawsAuth && window.DoloPawsAuth.currentUser
      ? window.DoloPawsAuth.currentUser.uid : null;

    if (flags.length === 0){
      listEl.innerHTML = '';
    } else {
      listEl.innerHTML = flags.map(f => {
        const t = FLAG_TYPES[f.type] || FLAG_TYPES.other;
        const d = flagDate(f);
        const dateStr = d ? d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '';
        const kmChip = (typeof f.km === 'number')
          ? `<span style="font-size:11px;font-weight:700;background:rgba(0,0,0,.07);padding:2px 8px;border-radius:10px;margin-left:8px;">km ${f.km}</span>` : '';
        const removeLink = (uid && f.uid === uid)
          ? ` · <a href="#" data-remove="${trEsc(f.id)}" style="color:#9C3A25;">${window.t('reports.remove')}</a>` : '';
        const reportLink = (uid && f.uid !== uid)
          ? ` · <a href="#" data-report="${trEsc(f.id)}" style="color:var(--ink-soft);">${window.t('reports.report')}</a>` : '';
        const responseLinks = (uid && f.uid !== uid)
          ? `<div style="display:flex;gap:12px;margin-top:7px;">
              <a href="#" data-hazard-response="confirm" data-flag-id="${trEsc(f.id)}">${window.t('reports.confirm')}</a>
              <a href="#" data-hazard-response="dispute" data-flag-id="${trEsc(f.id)}">${window.t('reports.dispute')}</a>
            </div>` : '';
        const responseCount = `${Number(f.confirmations) || 0} confirmed · ${Number(f.disputes) || 0} disputed`;
        // Design tile: neutral inset card + a coloured flag square whose tone
        // carries severity, replacing the mixed emoji-per-type language.
        const tile = t.severe ? { bg: '#F3D9D2', fg: '#9C3A25' }
          : { bg: '#F5E4C6', fg: '#8A5A16' };
        const flagSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M5 3v18h2v-7h5l1 2h6V6h-5l-1-2H5z"/></svg>';
        return `
        <div data-hazard-item style="display:flex;gap:12px;align-items:flex-start;background:#FAF8F1;border:1px solid #EDE9DD;border-radius:12px;padding:12px 14px;margin-bottom:10px;">
          <span style="flex:none;width:28px;height:28px;border-radius:8px;display:grid;place-items:center;background:${tile.bg};color:${tile.fg};">${flagSvg}</span>
          <div style="flex:1;min-width:0;">
            <div style="font-weight:800;color:var(--ink);font-size:13px;">${window.t('flag.' + f.type)}${kmChip}</div>
            ${f.text ? `<div style="font-size:12.5px;color:var(--ink-soft);line-height:1.5;margin-top:2px;">${trEsc(f.text)}</div>` : ''}
            <div style="font-size:11.5px;color:#8A9689;margin-top:4px;">${dateStr}${dogContextLine(f)}${removeLink}${reportLink}</div>
            <div style="font-size:11.5px;color:var(--ink-soft);margin-top:4px;">${trEsc(trustLabel(f))} · ${responseCount}</div>
            ${responseLinks}
          </div>
        </div>`;
      }).join('');
    }
    window.dispatchEvent(new CustomEvent('orma-hazards-changed'));

    // Remove / report links
    listEl.querySelectorAll('[data-remove]').forEach(a => {
      a.addEventListener('click', async (e) => {
        e.preventDefault();
        if (!confirm(window.t('reports.confirmRemove'))) return;
        await window.DoloPawsCommunity.deleteFlag(a.dataset.remove);
        load();
      });
    });
    listEl.querySelectorAll('[data-report]').forEach(a => {
      a.addEventListener('click', async (e) => {
        e.preventDefault();
        await window.DoloPawsCommunity.reportContent('flag', a.dataset.report, 'inappropriate or inaccurate');
        a.replaceWith(Object.assign(document.createElement('span'), { textContent: window.t('reports.reported') }));
      });
    });
    listEl.querySelectorAll('[data-hazard-response]').forEach(a => {
      a.addEventListener('click', async (e) => {
        e.preventDefault();
        const result = await window.DoloPawsCommunity.respondToHazard(
          a.dataset.flagId,
          a.dataset.hazardResponse
        );
        if(!result.ok){
          showActionStatus(result.message || 'Your response could not be saved.');
          return;
        }
        showActionStatus(window.t('reports.responseSaved'));
        load();
      });
    });

    // Map markers for active, km-tagged flags.
    flagMarkers.forEach(m => m.remove());
    flagMarkers = [];
    if (map && Array.isArray(trail.path) && trail.path.length > 1 && typeof pointAtFraction === 'function'){
      flags.filter(f => typeof f.km === 'number').forEach(f => {
        const t = FLAG_TYPES[f.type] || FLAG_TYPES.other;
        const fraction = trail.distance > 0 ? f.km / trail.distance : 0;
        const [lat, lng] = pointAtFraction(trail.path, fraction);
        const el = document.createElement('div');
        el.className = 'dp-marker';
        el.style.background = '#9C3A25';
        el.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="#fff" aria-hidden="true" style="display:block;margin:auto;"><path d="M5 3v18h2v-7h5l1 2h6V6h-5l-1-2H5z"/></svg>';
        const marker = new maplibregl.Marker({ element: el, offset: [0, 0] })
          .setLngLat([lng, lat])
          .setPopup(new maplibregl.Popup({ offset: 16 }).setHTML(
            `<b>${window.t('flag.' + f.type)}</b><br>Km ${f.km}${f.text ? `<br>${trEsc(f.text)}` : ''}<br><small>${window.t('reports.community')}</small>`))
          .addTo(map);
        flagMarkers.push(marker);
      });
    }
  }

  async function load(){
    if (!window.DoloPawsCommunity || !window.DoloPawsCommunity.getActiveFlags) return;
    const [flags, reviews, photos] = await Promise.all([
      window.DoloPawsCommunity.getActiveFlags(trail.id),
      window.DoloPawsCommunity.getReviews ? window.DoloPawsCommunity.getReviews(trail.id) : Promise.resolve([]),
      window.DoloPawsCommunity.getTrailPhotos ? window.DoloPawsCommunity.getTrailPhotos(trail.id) : Promise.resolve([]),
    ]);
    if (Array.isArray(flags)) render(flags);
    renderReviews(Array.isArray(reviews) ? reviews : []);
    renderPhotos(Array.isArray(photos) ? photos : []);
  }

  function downscaleTrailPhoto(file){
    return new Promise((resolve, reject) => {
      const image = new Image();
      const url = URL.createObjectURL(file);
      image.onload = () => {
        try {
          const scale = Math.min(1, 900 / Math.max(image.width, image.height));
          const canvas = document.createElement('canvas');
          canvas.width = Math.max(1, Math.round(image.width * scale));
          canvas.height = Math.max(1, Math.round(image.height * scale));
          canvas.getContext('2d').drawImage(image, 0, 0, canvas.width, canvas.height);
          URL.revokeObjectURL(url);
          resolve(canvas.toDataURL('image/jpeg', 0.78));
        } catch (error) { URL.revokeObjectURL(url); reject(error); }
      };
      image.onerror = () => { URL.revokeObjectURL(url); reject(new Error('decode failed')); };
      image.src = url;
    });
  }

  function confirmDiscard(dirty){
    return !dirty || window.confirm(window.t('form.discard'));
  }

  function enableModalKeyboard(overlay, onEscape, initialFocus, returnFocus){
    const title = overlay.querySelector('h2');
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    if (title){
      title.id = 'trailModalTitle-' + Math.random().toString(36).slice(2, 8);
      overlay.setAttribute('aria-labelledby', title.id);
    }
    const focusableSelector = 'button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
    const onKeydown = event => {
      if (event.key === 'Escape'){
        event.preventDefault();
        onEscape();
        return;
      }
      if (event.key !== 'Tab') return;
      const focusable = Array.from(overlay.querySelectorAll(focusableSelector)).filter(el => !el.hidden);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first){
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last){
        event.preventDefault();
        first.focus();
      }
    };
    overlay.addEventListener('keydown', onKeydown);
    setTimeout(() => {
      const target = overlay.querySelector(initialFocus) || overlay.querySelector(focusableSelector);
      if (target) target.focus();
    }, 0);
    return () => {
      overlay.removeEventListener('keydown', onKeydown);
      if (returnFocus && document.contains(returnFocus)) returnFocus.focus();
    };
  }

  function openPhotoModal(){
    if (!(window.DoloPawsAuth && window.DoloPawsAuth.currentUser)){
      if (window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('photo');
      return;
    }
    window.location.href = `photo-upload.html?trail=${encodeURIComponent(trail.id)}&name=${encodeURIComponent(trail.name)}`;
    return;
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal" style="max-width:420px;">
      <button type="button" class="modal-close" data-close aria-label="Close"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
      <h2 style="font-size:19px;">Add a trail photo</h2>
      <p class="hint">Share a recent, useful view of this trail. Photos appear with the community reviews.</p>
      <input data-photo type="file" accept="image/*" style="font-size:13px;margin:8px 0 12px;">
      <textarea data-caption maxlength="240" rows="3" placeholder="Add a short caption (optional)" style="width:100%;box-sizing:border-box;padding:10px;border:1.5px solid var(--paper-line);border-radius:10px;font-family:'Inter',sans-serif;font-size:13px;resize:vertical;"></textarea>
      <div data-err role="alert" style="color:#9C3A25;font-size:12.5px;margin-top:8px;" hidden></div>
      <button type="button" data-submit class="auth-submit" style="margin-top:12px;">Add photo</button>
    </div>`;
    document.body.appendChild(overlay);
    let dirty = false;
    const warnBeforeUnload = event => {
      if (!dirty) return;
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', warnBeforeUnload);
    overlay.querySelector('[data-photo]').addEventListener('change', () => { dirty = true; });
    overlay.querySelector('[data-caption]').addEventListener('input', () => { dirty = true; });
    let cleanupKeyboard = () => {};
    const close = force => {
      if (force !== true && !confirmDiscard(dirty)) return;
      window.removeEventListener('beforeunload', warnBeforeUnload);
      cleanupKeyboard();
      overlay.remove();
    };
    cleanupKeyboard = enableModalKeyboard(overlay, () => close(false), '[data-photo]', addPhotoBtn);
    overlay.querySelector('[data-close]').addEventListener('click', () => close(false));
    overlay.addEventListener('click', event => { if (event.target === overlay) close(false); });
    overlay.querySelector('[data-submit]').addEventListener('click', async () => {
      const error = overlay.querySelector('[data-err]');
      const file = overlay.querySelector('[data-photo]').files[0];
      if (!file || !file.type.startsWith('image/') || file.size > 10 * 1024 * 1024){
        error.textContent = 'Choose an image smaller than 10 MB.';
        error.hidden = false;
        return;
      }
      const submit = overlay.querySelector('[data-submit]');
      submit.disabled = true;
      submit.textContent = 'Adding…';
      try {
        const image = await downscaleTrailPhoto(file);
        const result = await window.DoloPawsCommunity.addTrailPhoto(trail.id, image, overlay.querySelector('[data-caption]').value.trim());
        if (result.ok){
          close(true);
          await load();
          showActionStatus('Photo submitted for review. It will appear after approval.');
          return;
        }
        error.textContent = result.message || 'Could not add this photo, please try again.';
      } catch (e) { error.textContent = 'Could not prepare this photo, please try another image.'; }
      error.hidden = false;
      submit.disabled = false;
      submit.textContent = 'Add photo';
    });
  }

  // ---- "Leave a review" modal --------------------------------------------
  function openReviewModal(){
    if (!(window.DoloPawsAuth && window.DoloPawsAuth.currentUser)){
      if (window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('review');
      return;
    }
    window.location.href = `reviews.html?trail=${encodeURIComponent(trail.id)}&name=${encodeURIComponent(trail.name)}`;
    return;

    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `
      <div class="modal" style="max-width:420px;">
        <button type="button" class="modal-close" data-close aria-label="Close"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
        <h2 style="font-size:19px;">Rate this trail</h2>
        <p class="hint">Your review helps other dogs and their humans choose the right walk.</p>
        <div data-stars class="review-star-picker" aria-label="Choose a rating">
          ${[1, 2, 3, 4, 5].map(value => `<button type="button" role="radio" aria-checked="false" data-rating="${value}" aria-label="${value} star${value === 1 ? '' : 's'}">${starSvgIcon(false, 24)}</button>`).join('')}
        </div>
        <textarea data-text maxlength="1000" rows="4" placeholder="What should other dog owners know? (optional)" style="width:100%;box-sizing:border-box;padding:10px;border:1.5px solid var(--paper-line);border-radius:10px;font-family:'Inter',sans-serif;font-size:13px;resize:vertical;"></textarea>
        <div data-err role="alert" style="color:#9C3A25;font-size:12.5px;margin-top:8px;" hidden></div>
        <button type="button" data-submit class="auth-submit" style="margin-top:12px;">Post review</button>
      </div>`;
    document.body.appendChild(overlay);

    let selectedRating = 0;
    let dirty = false;
    const warnBeforeUnload = event => {
      if (!dirty) return;
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', warnBeforeUnload);
    const starButtons = Array.from(overlay.querySelectorAll('[data-rating]'));
    starButtons.forEach(button => {
      button.addEventListener('click', () => {
        dirty = true;
        selectedRating = Number(button.dataset.rating);
        starButtons.forEach(star => {
          const active = Number(star.dataset.rating) <= selectedRating;
          star.innerHTML = starSvgIcon(active, 24);
          star.classList.toggle('is-selected', active);
          star.setAttribute('aria-checked', Number(star.dataset.rating) === selectedRating ? 'true' : 'false');
        });
      });
    });
    overlay.querySelector('[data-text]').addEventListener('input', () => { dirty = true; });

    let cleanupKeyboard = () => {};
    function close(force){
      if (force !== true && !confirmDiscard(dirty)) return;
      window.removeEventListener('beforeunload', warnBeforeUnload);
      cleanupKeyboard();
      overlay.remove();
    }
    cleanupKeyboard = enableModalKeyboard(overlay, () => close(false), '[data-rating]', addReviewBtn);
    overlay.querySelector('[data-close]').addEventListener('click', () => close(false));
    overlay.addEventListener('click', event => { if (event.target === overlay) close(false); });
    overlay.querySelector('[data-submit]').addEventListener('click', async () => {
      const error = overlay.querySelector('[data-err]');
      if (!selectedRating){
        error.textContent = 'Please choose a star rating.';
        error.hidden = false;
        return;
      }
      const submit = overlay.querySelector('[data-submit]');
      submit.disabled = true;
      submit.textContent = 'Posting…';
      try {
        const result = await window.DoloPawsCommunity.setReview(
          trail.id,
          selectedRating,
          overlay.querySelector('[data-text]').value.trim(),
          null,
        );
        if (result.ok){
          close(true);
          await load();
          showActionStatus('Review submitted for moderation. It will appear after approval.');
          return;
        }
        error.textContent = result.message || 'Could not post your review, please try again.';
      } catch (e) {
        error.textContent = 'Could not post your review, please try again.';
      }
      error.hidden = false;
      submit.disabled = false;
      submit.textContent = 'Post review';
    });
  }

  // ---- "Report something" modal --------------------------------------------
  function openReportModal(){
    if(window.OrmaHazardReporter && typeof window.OrmaHazardReporter.open === 'function'){
      window.OrmaHazardReporter.open();
      return;
    }
    if (!(window.DoloPawsAuth && window.DoloPawsAuth.currentUser)){
      if (window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('report');
      return;
    }
    window.location.href = `trail-report.html?trail=${encodeURIComponent(trail.id)}&name=${encodeURIComponent(trail.name)}`;
    return;

    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    const maxKm = trail.distance || 10;
    overlay.innerHTML = `
      <div class="modal" style="max-width:420px;">
        <button type="button" class="modal-close" data-close aria-label="Close"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
        <h2 style="font-size:19px;">${window.t('reports.modalTitle')}</h2>
        <p class="hint">${window.t('reports.modalHint')}</p>
        <div data-types style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:14px 0;">
          ${Object.entries(FLAG_TYPES).map(([key, t]) => `
            <button type="button" aria-pressed="false" data-type="${key}" style="padding:10px 8px;border-radius:10px;border:1.5px solid var(--paper-line);background:none;font-size:12px;font-weight:600;color:var(--ink);cursor:pointer;text-align:left;font-family:'Inter',sans-serif;">${window.t('flag.' + key)}</button>`).join('')}
        </div>
        <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--ink);margin-bottom:6px;">
          <input type="checkbox" data-haskm> ${window.t('reports.knowWhere')}
        </label>
        <div data-kmrow hidden style="margin-bottom:12px;">
          <input type="range" data-km min="0" max="${maxKm}" step="0.1" value="0" style="width:100%;">
          <div style="font-size:12px;color:var(--ink-soft);text-align:center;">${window.t('reports.atKm', {max: maxKm})}</div>
        </div>
        <textarea data-text maxlength="300" rows="3" placeholder="${window.t('reports.placeholder')}" style="width:100%;box-sizing:border-box;padding:10px;border:1.5px solid var(--paper-line);border-radius:10px;font-family:'Inter',sans-serif;font-size:13px;resize:vertical;"></textarea>
        <div data-err role="alert" style="color:#9C3A25;font-size:12.5px;margin-top:8px;" hidden></div>
        <button type="button" data-submit class="auth-submit" style="margin-top:12px;">${window.t('reports.post')}</button>
      </div>`;
    document.body.appendChild(overlay);

    let selectedType = null;
    let dirty = false;
    const warnBeforeUnload = event => {
      if (!dirty) return;
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', warnBeforeUnload);
    overlay.querySelectorAll('[data-type]').forEach(btn => {
      btn.addEventListener('click', () => {
        dirty = true;
        selectedType = btn.dataset.type;
        overlay.querySelectorAll('[data-type]').forEach(b => {
          b.style.background = 'none'; b.style.borderColor = 'var(--paper-line)'; b.style.color = 'var(--ink)';
          b.setAttribute('aria-pressed', b === btn ? 'true' : 'false');
        });
        btn.style.background = 'var(--ink)'; btn.style.borderColor = 'var(--ink)'; btn.style.color = '#fff';
      });
    });

    const hasKm = overlay.querySelector('[data-haskm]');
    const kmRow = overlay.querySelector('[data-kmrow]');
    const kmInput = overlay.querySelector('[data-km]');
    const kmVal = overlay.querySelector('[data-kmval]');
    hasKm.addEventListener('change', () => { dirty = true; kmRow.hidden = !hasKm.checked; });
    kmInput.addEventListener('input', () => { dirty = true; if (kmVal) kmVal.textContent = kmInput.value; });
    overlay.querySelector('[data-text]').addEventListener('input', () => { dirty = true; });

    let cleanupKeyboard = () => {};
    function close(force){
      if (force !== true && !confirmDiscard(dirty)) return;
      window.removeEventListener('beforeunload', warnBeforeUnload);
      cleanupKeyboard();
      overlay.remove();
    }
    cleanupKeyboard = enableModalKeyboard(overlay, () => close(false), '[data-type]', addBtn);
    overlay.querySelector('[data-close]').addEventListener('click', () => close(false));
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(false); });

    overlay.querySelector('[data-submit]').addEventListener('click', async () => {
      const err = overlay.querySelector('[data-err]');
      if (!selectedType){
        err.textContent = window.t('reports.pickType'); err.hidden = false; return;
      }
      const km = hasKm.checked ? Math.round(parseFloat(kmInput.value) * 10) / 10 : null;
      const text = overlay.querySelector('[data-text]').value.trim();
      const submitBtn = overlay.querySelector('[data-submit]');
      submitBtn.disabled = true; submitBtn.textContent = window.t('reports.posting');
      try {
        const res = await window.DoloPawsCommunity.addFlag(trail.id, selectedType, km, text);
        if (res.ok){
          close(true);
          await load();
          showActionStatus('Hazard report submitted for moderation.');
          return;
        }
        err.textContent = res.message || window.t('reports.error');
      } catch (e) {
        err.textContent = window.t('reports.error');
      }
      err.hidden = false;
      submitBtn.disabled = false; submitBtn.textContent = window.t('reports.post');
    });
  }

  // The report action lives on the map and is owned by trail-hazards.js. Keep
  // this function only for resuming the exact action after an auth detour.
  if (addReviewBtn) addReviewBtn.addEventListener('click', openReviewModal);
  if (addPhotoBtn) addPhotoBtn.addEventListener('click', openPhotoModal);

  let resumedAction = false;
  function resumePendingAction(user){
    if(resumedAction || !user || !window.DoloPawsTrailAction) return;
    const action = window.DoloPawsTrailAction.pending;
    const open = action === 'review' ? openReviewModal
      : action === 'photo' ? openPhotoModal
      : action === 'report' ? openReportModal
      : null;
    if(!open || !window.DoloPawsTrailAction.consume(action)) return;
    resumedAction = true;
    const targetTab = action === 'report' ? 'tabSafety' : 'tabReviews';
    const tabButton = document.querySelector(`[data-tab="${targetTab}"]`);
    if(tabButton) tabButton.click();
    open();
  }

  // Re-render on login/logout so Remove links appear/disappear, and resume
  // the exact community action that initiated an authentication detour.
  window.addEventListener('dolopaws-auth-changed', event => {
    load();
    resumePendingAction(event.detail.user);
  });

  if (window.DoloPawsCommunity) load();
  else window.addEventListener('dolopaws-auth-ready', load, { once: true });
  if(window.DoloPawsAuth) resumePendingAction(window.DoloPawsAuth.currentUser);
}
;

// ---- trail-route-refs.js ----
(function (global) {
  'use strict';

  const REF_PATTERN = /\b(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?\b/gi;
  const ROUTE_WORD_PATTERN = /\b(?:trails?|paths?|routes?|sentieri)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?(?:\s*(?:,\s*(?:and\s+)?|\/\s*|&\s*|→\s*|(?:and|then|to|onto)\s+)(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)*)/gi;
  const NAMED_SENTIERO_PATTERN = /\bsentiero\s+(?:[A-ZÀ-ÖØ-öø-ÿ'’-]+\s+){0,3}((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\b/gi;

  function normaliseRef(value) {
    const ref = String(value == null ? '' : value)
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '');
    return /^(?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?$/.test(ref) ? ref : null;
  }

  function refsFromText(text) {
    const refs = [];
    const source = String(text == null ? '' : text);
    for (const match of source.matchAll(ROUTE_WORD_PATTERN)) {
      const candidates = match[1].match(REF_PATTERN) || [];
      candidates.forEach(candidate => {
        const ref = normaliseRef(candidate);
        if (ref && !refs.includes(ref)) refs.push(ref);
      });
    }
    for (const match of source.matchAll(NAMED_SENTIERO_PATTERN)) {
      const ref = normaliseRef(match[1]);
      if (ref && !refs.includes(ref)) refs.push(ref);
    }
    return refs;
  }

  function explicitRefs(trail) {
    const values = [];
    ['routeRefs', 'routeNumbers', 'trailRefs', 'trailNumbers'].forEach(key => {
      const field = trail && trail[key];
      if (Array.isArray(field)) values.push(...field);
      else if (field != null) values.push(field);
    });
    if (trail && trail.ref != null) values.push(trail.ref);
    (Array.isArray(trail && trail.routeRefSegments) ? trail.routeRefSegments : [])
      .forEach(segment => values.push(segment && segment.ref));
    return values.map(value => normaliseRef(
      value && typeof value === 'object'
        ? value.ref || value.number || value.label
        : value
    )).filter(Boolean);
  }

  function switchRefs(instruction) {
    const match = String(instruction == null ? '' : instruction).match(
      /\bswitch\s+from\s+(?:trail|path|route|sentiero)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\s+onto\s+(?:trail|path|route|sentiero)\s+((?:[A-Z]{1,4}-?)?\d{1,4}[A-Z]?)\b/i
    );
    if (!match) return null;
    const from = normaliseRef(match[1]);
    const to = normaliseRef(match[2]);
    return from && to ? { from, to } : null;
  }

  function nearestPathIndex(path, point, startIndex) {
    if (!point || !Number.isFinite(Number(point.lat)) || !Number.isFinite(Number(point.lng))) return -1;
    let bestIndex = -1;
    let bestDistance = Infinity;
    for (let index = Math.max(0, startIndex || 0); index < path.length; index += 1) {
      const candidate = path[index];
      if (!Array.isArray(candidate) || candidate.length < 2) continue;
      const dLat = Number(candidate[0]) - Number(point.lat);
      const dLng = Number(candidate[1]) - Number(point.lng);
      const distance = dLat * dLat + dLng * dLng;
      if (distance < bestDistance) {
        bestDistance = distance;
        bestIndex = index;
      }
    }
    return bestIndex;
  }

  function switchesForTrail(trail) {
    return (Array.isArray(trail && trail.decisionPoints) ? trail.decisionPoints : [])
      .map(point => ({ point, refs: switchRefs(point && point.instruction) }))
      .filter(item => item.refs && Number.isFinite(Number(item.point && item.point.lat))
        && Number.isFinite(Number(item.point && item.point.lng)))
      .map(item => ({
        from:item.refs.from,
        to:item.refs.to,
        km:Number.isFinite(Number(item.point.km)) ? Number(item.point.km) : null,
        lat:Number(item.point.lat),
        lng:Number(item.point.lng),
        instruction:String(item.point.instruction || ''),
      }));
  }

  function segmentsForTrail(trail) {
    if (!trail || !Array.isArray(trail.path) || trail.path.length < 2) return [];
    const verified = (Array.isArray(trail.routeRefSegments) ? trail.routeRefSegments : [])
      .map(segment => ({
        ref: normaliseRef(segment && segment.ref),
        path: segment && segment.path,
        source: segment && segment.source,
      }))
      .filter(segment => segment.ref && Array.isArray(segment.path) && segment.path.length > 1);
    if (verified.length) return verified;

    const switches = switchesForTrail(trail);
    if (!switches.length) return [];

    const segments = [];
    let currentRef = switches[0].from;
    let startIndex = 0;
    switches.forEach(item => {
      const endIndex = nearestPathIndex(trail.path, item, startIndex);
      if (endIndex > startIndex) {
        segments.push({ ref: currentRef, path: trail.path.slice(startIndex, endIndex + 1) });
        startIndex = endIndex;
      }
      currentRef = item.to;
    });
    if (startIndex < trail.path.length - 1) {
      segments.push({ ref: currentRef, path: trail.path.slice(startIndex) });
    }
    return segments.filter(segment => segment.path.length > 1);
  }

  function forTrail(trail) {
    if (!trail || typeof trail !== 'object') return [];
    const refs = [];
    const add = value => {
      const ref = normaliseRef(value);
      if (ref && !refs.includes(ref)) refs.push(ref);
    };

    explicitRefs(trail).forEach(add);
    refsFromText(trail.routeSource && trail.routeSource.name).forEach(add);
    (Array.isArray(trail.decisionPoints) ? trail.decisionPoints : [])
      .forEach(point => refsFromText(point && point.instruction).forEach(add));
    return refs.slice(0, 8);
  }

  const SHIELD_IMAGE_ID = 'orma-route-number-shield';

  function featuresForTrail(trail) {
    const sections = segmentsForTrail(trail);
    const refs = forTrail(trail);
    // Verified section geometry remains the first choice. When a route has a
    // known sequence of references but no surveyed switch coordinates, keep
    // the sequence together on the full ORMA line. This makes the numbers
    // visible without pretending that an unverified point is the junction.
    const labelledPaths = sections.length
      ? sections
      : (refs.length && Array.isArray(trail && trail.path)
        ? [{ ref:refs.join(' / '), path:trail.path }]
        : []);
    return labelledPaths
      .filter(section => section.ref && Array.isArray(section.path) && section.path.length > 1)
      .map(section => ({
        type:'Feature',
        properties:{ id:trail.id, routeRef:section.ref },
        geometry:{ type:'LineString', coordinates:section.path.map(([lat, lng]) => [lng, lat]) },
      }));
  }

  function registerShieldImage(map) {
    if(map.hasImage(SHIELD_IMAGE_ID)) return;
    const canvas = document.createElement('canvas');
    canvas.width = 104;
    canvas.height = 68;
    const context = canvas.getContext('2d');
    context.fillStyle = '#FFFFFF';
    context.fillRect(2, 2, 100, 64);
    // Thinner keyline than the old 5px slab: at the reduced icon-size the
    // heavy border was most of what the eye saw.
    context.strokeStyle = '#3A4A3E';
    context.lineWidth = 3;
    context.strokeRect(3.5, 3.5, 97, 61);
    map.addImage(
      SHIELD_IMAGE_ID,
      context.getImageData(0, 0, 104, 68),
      { pixelRatio:2, stretchX:[[20, 84]], stretchY:[[16, 52]], content:[14, 9, 90, 59] }
    );
  }

  function addShieldLayer(map, options) {
    const config = options || {};
    if(!config.id || !config.source || map.getLayer(config.id)) return;
    registerShieldImage(map);
    map.addLayer({
      id:config.id,
      type:'symbol',
      source:config.source,
      minzoom:8,
      // minzoom 12: a route number is wayfinding detail. Below that it is
      // just a box sitting on a line nobody is following yet.
      minzoom:12,
      layout:{
        'symbol-placement':'line',
        'symbol-spacing':['interpolate', ['linear'], ['zoom'], 12, 220, 16, 260, 19, 300],
        'icon-image':SHIELD_IMAGE_ID,
        'icon-text-fit':'both',
        'icon-text-fit-padding':[4, 7, 4, 7],
        'icon-size':['interpolate', ['linear'], ['zoom'], 12, 0.72, 16, 0.82, 19, 0.9],
        'icon-rotation-alignment':'viewport',
        // Collision on. Shields that fight each other for the same bend are
        // the clutter; one readable shield per stretch of path is the point.
        'icon-allow-overlap':false,
        'icon-ignore-placement':false,
        'icon-padding':6,
        'text-field':['get', 'routeRef'],
        // The tile server (openfreemap) serves Noto only. Asking for
        // "Open Sans Bold" 404s every glyph range and MapLibre silently
        // rasterises a fallback locally, which is what made these shields
        // render as oversized, blurry clip-art boxes.
        'text-font':['Noto Sans Bold'],
        'text-size':['interpolate', ['linear'], ['zoom'], 12, 11.5, 16, 13, 19, 14],
        'text-rotation-alignment':'viewport',
        'text-keep-upright':true,
        'text-allow-overlap':false,
        'text-ignore-placement':false,
      },
      paint:{
        'text-color':'#17221B',
        'text-halo-color':'#FFFFFF',
        'text-halo-width':1.2,
      },
    }, config.beforeId);
  }

  const api = {
    forTrail,
    refsFromText,
    normaliseRef,
    segmentsForTrail,
    switchesForTrail,
    featuresForTrail,
    registerShieldImage,
    addShieldLayer,
    SHIELD_IMAGE_ID,
  };
  global.DoloPawsTrailRouteRefs = api;
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
})(typeof window !== 'undefined' ? window : globalThis);
;

// ---- route-operational-facts.js ----
(function(root, factory){
  const api = factory();
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.DoloPawsOperationalFacts = api;
})(typeof window !== 'undefined' ? window : globalThis, function(){
  'use strict';

  const CONTRACT_VERSION = '1.0.0';

  const ENTITY_TYPES = Object.freeze(['rifugio', 'lift', 'protected-area']);
  // `unknown` is a recorded answer: someone asked and could not get one. It is
  // not the same as an unverified fact, which has no answer at all.
  const DOG_POLICIES = Object.freeze([
    'accepted',
    'accepted_leashed',
    'accepted_muzzled',
    'not_accepted',
    'unknown',
  ]);
  const VERIFIED_SOURCES = Object.freeze(['phone', 'website', 'email', 'in-person']);

  const POLICY_LABEL = Object.freeze({
    accepted: 'dogs accepted',
    accepted_leashed: 'dogs accepted, leashed',
    accepted_muzzled: 'muzzle required',
    not_accepted: 'dogs not accepted',
    unknown: 'policy not published',
  });
  const ENTITY_LABEL = Object.freeze({
    rifugio: 'Rifugio',
    lift: 'Lift',
    'protected-area': 'Protected area',
  });

  const UNVERIFIED_NOTE = 'Not yet verified, check before you go';
  // A year is the point past which an opening-hours or dog rule is likely to
  // have moved without anyone telling us.
  const STALE_AFTER_MONTHS = 12;

  const ID_PATTERN = /^[a-z0-9][a-z0-9-]{1,79}$/;
  const TRAIL_PATTERN = /^[A-Za-z0-9._-]{1,80}$/;
  const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

  function isDate(value){
    return typeof value === 'string' && DATE_PATTERN.test(value)
      && !Number.isNaN(Date.parse(`${value}T00:00:00Z`));
  }

  function text(value, maximum){
    return typeof value === 'string' && value.trim().length > 0 && value.length <= maximum;
  }

  // A fact is only usable when it can be attributed. An entry that claims a
  // policy without a verification date, source and reviewer is rejected
  // outright rather than shown with a caveat: an unattributable policy on a
  // dog-safety page is worse than no policy at all.
  function validateFact(fact, index){
    const at = `/facts/${index}`;
    const errors = [];
    if(!fact || typeof fact !== 'object'){ return [`${at}: expected an object`]; }
    if(typeof fact.id !== 'string' || !ID_PATTERN.test(fact.id)) errors.push(`${at}/id: expected a slug`);
    if(typeof fact.trail_id !== 'string' || !TRAIL_PATTERN.test(fact.trail_id)) errors.push(`${at}/trail_id: expected a trail id`);
    if(!ENTITY_TYPES.includes(fact.entity_type)) errors.push(`${at}/entity_type: expected one of ${ENTITY_TYPES.join(', ')}`);
    if(!text(fact.entity_name, 160)) errors.push(`${at}/entity_name: expected a non-empty name`);
    if(!DOG_POLICIES.includes(fact.dog_policy)) errors.push(`${at}/dog_policy: expected one of ${DOG_POLICIES.join(', ')}`);
    if(fact.policy_notes !== null && !text(fact.policy_notes, 400)) errors.push(`${at}/policy_notes: expected text or null`);

    const verified = fact.verified_at !== null && fact.verified_at !== undefined;
    if(verified && !isDate(fact.verified_at)) errors.push(`${at}/verified_at: expected an ISO date or null`);
    if(verified){
      if(!VERIFIED_SOURCES.includes(fact.verified_source)) errors.push(`${at}/verified_source: expected one of ${VERIFIED_SOURCES.join(', ')}`);
      if(!text(fact.verified_by, 120)) errors.push(`${at}/verified_by: expected a reviewer`);
    }else{
      // Without a date there is nothing standing behind the policy, so the
      // only value it may carry is `unknown`.
      if(fact.dog_policy !== 'unknown'){
        errors.push(`${at}/dog_policy: an unverified fact may only record 'unknown'`);
      }
    }
    return errors;
  }

  function validateTable(table){
    const errors = [];
    if(!table || typeof table !== 'object') return ['/: expected an object'];
    if(table.contractVersion !== CONTRACT_VERSION) errors.push(`/contractVersion: expected ${CONTRACT_VERSION}`);
    if(table.updatedAt !== null && !isDate(table.updatedAt)) errors.push('/updatedAt: expected an ISO date or null');
    if(!Array.isArray(table.facts)) return errors.concat('/facts: expected an array');
    const seen = new Set();
    table.facts.forEach((fact, index) => {
      errors.push(...validateFact(fact, index));
      if(fact && typeof fact.id === 'string'){
        if(seen.has(fact.id)) errors.push(`/facts/${index}/id: duplicate id`);
        seen.add(fact.id);
      }
    });
    return errors;
  }

  function monthsBetween(fromISO, toISO){
    const from = new Date(`${fromISO}T00:00:00Z`);
    const to = new Date(`${toISO}T00:00:00Z`);
    return (to.getUTCFullYear() - from.getUTCFullYear()) * 12
      + (to.getUTCMonth() - from.getUTCMonth());
  }

  function monthLabel(iso){
    const date = new Date(`${iso}T00:00:00Z`);
    return date.toLocaleDateString('en-GB', { month:'short', year:'numeric', timeZone:'UTC' });
  }

  function verification(fact, asOfDate){
    if(!fact || !isDate(fact.verified_at)) return { state:'unverified', label:UNVERIFIED_NOTE };
    const label = monthLabel(fact.verified_at);
    const asOf = isDate(asOfDate) ? asOfDate : new Date().toISOString().slice(0, 10);
    if(monthsBetween(fact.verified_at, asOf) >= STALE_AFTER_MONTHS){
      return { state:'stale', label:`Last verified ${label}, may have changed`, verifiedLabel:label };
    }
    return { state:'verified', label:`Verified ${label}`, verifiedLabel:label };
  }

  function factsFor(trailId, table){
    const facts = table && Array.isArray(table.facts) ? table.facts : [];
    return facts.filter(fact => fact && fact.trail_id === trailId);
  }

  // Render-ready rows for one trail: only facts somebody has checked. The
  // places ORMA merely knows about (the km-tagged rifugi, most of them bars
  // and restaurants from OpenStreetMap) used to be listed too, each stamped
  // "not yet verified". 473 such rows across 110 trails, none of them
  // checked, said nothing a reader could act on, so they are no longer rows.
  // An undated fact is also left out: it has nothing standing behind it.
  function rowsFor(trail, table, asOfDate){
    if(!trail || typeof trail.id !== 'string') return [];
    const rows = factsFor(trail.id, table)
      .map(fact => ({
        entityType: fact.entity_type,
        entityName: fact.entity_name,
        policy: fact.dog_policy,
        policyLabel: POLICY_LABEL[fact.dog_policy],
        notes: fact.policy_notes || null,
        km: null,
        ...verification(fact, asOfDate),
      }))
      .filter(row => row.state !== 'unverified');

    return rows.sort((a, b) => {
      if(a.km !== null && b.km !== null) return a.km - b.km;
      if(a.km !== null) return -1;
      if(b.km !== null) return 1;
      return a.entityName.localeCompare(b.entityName);
    });
  }

  return Object.freeze({
    CONTRACT_VERSION,
    ENTITY_TYPES,
    DOG_POLICIES,
    VERIFIED_SOURCES,
    POLICY_LABEL,
    ENTITY_LABEL,
    UNVERIFIED_NOTE,
    STALE_AFTER_MONTHS,
    validateFact,
    validateTable,
    verification,
    factsFor,
    rowsFor,
  });
});
;

// ---- trail.js ----
function safetyLabel(level){
  if(level === 'low-risk') return t('safety.low');
  if(level === 'moderate') return t('safety.moderate');
  return t('safety.caution');
}
function trailSafetyLabel(trail){
  const base = safetyLabel(trail.safetyLevel);
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.riskLabel(trail, base) : base;
}
// Green/amber/red on the map means how well the walk suits the dog, never
// how hard the trail is. One palette, defined once in map-style.js, so opening
// a trail never changes the map's meaning. (This replaces safetyColor(), which
// coloured the same line by the trail's intrinsic risk in a near-identical
// palette, so a guest and a signed-in owner read the same line differently.)
function detailRouteColorForScore(score){
  return window.ORMAMapStyle
    ? window.ORMAMapStyle.matchColour(score)
    : (score >= 85 ? '#4A7856' : score >= 65 ? '#C98A2E' : '#9C3A25');
}

// A visitor with no dog yet is scored against the medium-dog profile the site
// already tells them about, so the map still answers "does this suit a dog?"
// instead of quietly switching to a different question.
function guestMatchScore(trail){
  const scoring = window.DoloPawsScoring;
  if(!scoring || typeof scoring.scoreTrail !== 'function') return null;
  try{ return scoring.scoreTrail(trail, scoring.GUEST_SUBJECT); }
  catch(error){ return null; }
}
function applyDetailRouteColor(color){
  window._dolopawsTrailRouteColor = color;
  const map = window._dolopawsTrailMap;
  if(!map || !map.isStyleLoaded || !map.isStyleLoaded()) return;
  if(map.getLayer('single-trail-path-line')) map.setPaintProperty('single-trail-path-line', 'line-color', color);
  if(map.getLayer('single-trail-direction-arrows')) map.setPaintProperty('single-trail-direction-arrows', 'text-halo-color', color);
}

function safetyClass(level){
  if(level === 'low-risk') return 'safety-low';
  if(level === 'moderate') return 'safety-moderate';
  return 'safety-caution';
}
function trailProductBadge(type, label){
  if(window.DoloPawsIcons) return window.DoloPawsIcons.badgeHtml(type, label);
  return `<span class="dp-badge dp-badge--${type}"><span>${label}</span></span>`;
}
function trailProductIcon(type, size = 16){
  return window.DoloPawsIcons ? window.DoloPawsIcons.renderIconSvg(type, { mode:'inline', color:'currentColor', size }) : '';
}
function withoutLeadingSymbol(label){
  return String(label || '').replace(/^[^\p{L}\p{N}]+/u, '');
}
function trustedWaterLabel(trail, label){
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.waterPointLabel(trail, label) : label;
}
function trustedStartLabel(trail, label){
  return window.DoloPawsTrailTrust ? window.DoloPawsTrailTrust.startPointLabel(trail, label) : label;
}

// ---- On this route --------------------------------------------------------
// Only what has been checked: operational facts (rifugi dog policy, lift
// muzzle rules) from the route_operational_fact table, and water points on a
// trail whose water has been reviewed. The table is filled by the editorial
// process; until it holds a fact for this trail there is nothing to list, and
// the card stays hidden rather than naming places nobody has checked.
function renderOnThisRoute(t, table){
  const api = window.DoloPawsOperationalFacts;
  if(!api) return '';
  const rows = api.rowsFor(t, table);
  if(!rows.length) return '';

  const items = rows.map(row => {
    const where = row.km !== null ? `Km ${row.km}, ` : '';
    const kind = api.ENTITY_LABEL[row.entityType] || '';
    // No verified fact means no policy line at all. Never a guess, never blank.
    const policy = row.policyLabel
      ? `<span class="td2-onroute-policy">${escapeLiftPopupText(row.policyLabel)}</span>`
      : '';
    const notes = row.notes ? `<span class="td2-onroute-note">${escapeLiftPopupText(row.notes)}</span>` : '';
    const stamp = `<span class="td2-onroute-stamp is-${escapeLiftPopupText(row.state)}">${escapeLiftPopupText(row.label)}</span>`;
    return `<li><span class="td2-onroute-name">${escapeLiftPopupText(where)}${escapeLiftPopupText(row.entityName)}</span>` +
      `<span class="td2-onroute-kind">${escapeLiftPopupText(kind)}</span>${policy}${notes}${stamp}</li>`;
  }).join('');

  // No heading of its own: #td2OnRouteCard supplies "On this route" above it,
  // and a card that states its own title twice is the repetition this page
  // was just cleared of.
  return `
    <div style="margin-bottom:14px;" id="td2OnRoute">
      <ul class="td2-onroute">${items}</ul>
    </div>`;
}

// The table is small and rarely changes, so it is fetched once per page and
// the card is painted again if a checked fact applies to this trail. A failed
// fetch leaves the card as it was.
function hydrateOnThisRoute(t){
  const api = window.DoloPawsOperationalFacts;
  if(!api) return;
  const prefix = location.pathname.includes('/trails/') ? '../' : '';
  fetch(`${prefix}data/route-operational-facts.json`, { cache:'no-store' })
    .then(response => response.ok ? response.json() : null)
    .then(table => {
      if(!table || !api.rowsFor(t, table).length) return;
      paintOnRouteCard(t, table);
    })
    .catch(() => {});
}

// The body of the "On this route" card: the checked places on the walk, then
// the water on it.
//
// Water is listed only where it has been reviewed. An unreviewed point carries
// ", availability can change", which is the same "nobody has checked" the
// places used to say, and the dog-safety column already tells the reader to
// bring their own water in that case.
function renderTrailDetailContent(t, table){
  const reviewed = window.DoloPawsTrailTrust
    && window.DoloPawsTrailTrust.categoryVerified(t, 'water');
  const water = reviewed && Array.isArray(t.waterSources) ? t.waterSources : [];
  const places = renderOnThisRoute(t, table || null);

  // Water reads in the same list as the places above it.
  const waterHtml = water.length > 0
    ? `<div style="margin-bottom:4px;">
      <div class="dp-inline-status" style="font-weight:700;color:var(--ink);margin-bottom:4px;">${trailProductIcon('water')}<span>${withoutLeadingSymbol(window.t('trail.waterHead'))}</span></div>
      <ul class="td2-onroute">${water.map(w =>
        `<li><span class="td2-onroute-name">Km ${w.km}, ${trustedWaterLabel(t, w.label)}</span></li>`).join('')}</ul>`
      + '</div>'
    : '';

  return `${places}${waterHtml}`;
}

// Writes the card and reveals it only when the route has something checked to
// name. Falls back to the retired hidden node for a visitor whose browser
// still has the previous trail.html, which has no card to write into.
function paintOnRouteCard(t, table){
  const body = document.getElementById('td2OnRouteBody');
  const card = document.getElementById('td2OnRouteCard');
  const markup = renderTrailDetailContent(t, table);
  if(!table) setTimeout(() => hydrateOnThisRoute(t), 0);
  if(!body || !card){
    const legacy = document.getElementById('trailDetailContent');
    if(legacy) legacy.innerHTML = markup;
    return;
  }
  body.innerHTML = markup;
  card.hidden = !markup;
}

function distMeters(a, b){
  return Math.hypot(a[0]-b[0], a[1]-b[1]) * 111000;
}

function mapDistanceKm(a, b){
  const rad = Math.PI / 180;
  const dLat = (b[0] - a[0]) * rad;
  const dLng = (b[1] - a[1]) * rad;
  const lat1 = a[0] * rad;
  const lat2 = b[0] * rad;
  const h = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(h));
}

function formatApproachDistance(distanceKm){
  if(!Number.isFinite(distanceKm)) return '';
  if(distanceKm < 1) return `${Math.max(10, Math.round(distanceKm * 1000 / 10) * 10)} m`;
  return `${distanceKm.toFixed(distanceKm < 10 ? 1 : 0)} km`;
}

function initLoopComposer(map, t){
  const openButton = document.getElementById('mapLoopComposerBtn');
  const panel = document.getElementById('mapLoopComposerPanel');
  const dismissButton = document.getElementById('mapLoopDismissBtn');
  const addCentreButton = document.getElementById('mapLoopAddCentreBtn');
  const undoButton = document.getElementById('mapLoopUndoBtn');
  const closeButton = document.getElementById('mapLoopCloseBtn');
  const saveButton = document.getElementById('mapLoopSaveBtn');
  const status = document.getElementById('mapLoopStatus');
  const distance = document.getElementById('mapLoopDistance');
  const pointCount = document.getElementById('mapLoopPointCount');
  const pointList = document.getElementById('mapLoopPointList');
  const mapBox = document.getElementById('trailMapBox');
  const coverage = window.DoloPawsTrailRoutingCoverage;
  const coverageEntry = coverage && coverage.trails ? coverage.trails[t.id] : null;
  const router = window.DoloPawsFootpathRouter;
  if(!openButton || !panel || !dismissButton || !addCentreButton || !undoButton ||
     !closeButton || !saveButton || !status || !distance || !pointCount || !pointList ||
     !coverageEntry || !coverageEntry.graphUrl || !router ||
     typeof router.routeThroughPoints !== 'function' || typeof router.routeLoop !== 'function') return;

  const MAX_POINTS = 3;
  const MAX_LEG_DISTANCE_M = 5000;
  const MAX_TOTAL_DISTANCE_M = Number.isFinite(coverage.maxWalkingRouteM)
    ? coverage.maxWalkingRouteM * 2
    : 10000;
  const STORAGE_KEY = 'orma-custom-loops-v1';
  let active = false;
  let busy = false;
  let closed = false;
  let points = [];
  let preview = null;
  let graphPromise = null;
  let calculationVersion = 0;
  let markers = [];
  openButton.hidden = false;

  function loadGraph(){
    if(!graphPromise){
      graphPromise = fetch(coverageEntry.graphUrl, { credentials:'same-origin' })
        .then(response => {
          if(!response.ok) throw new Error(`routing-graph-${response.status}`);
          return response.json();
        })
        .then(graph => router.validateGraph(graph) ? graph : null)
        .catch(() => null);
    }
    return graphPromise;
  }

  function markerElement(index){
    const element = document.createElement('span');
    element.className = `map-access-marker ${index === 0 ? 'map-access-marker--you' : 'map-access-marker--target'}`;
    element.textContent = index === 0 ? '' : String(index);
    element.setAttribute('aria-hidden', 'true');
    return element;
  }

  function drawMarkers(){
    markers.forEach(marker => marker.remove());
    markers = points.map((point, index) => new maplibregl.Marker({ element:markerElement(index) })
      .setLngLat([point.lng, point.lat])
      .addTo(map));
  }

  function emptyRoute(){
    return { type:'FeatureCollection', features:[] };
  }

  function drawRoute(path){
    const data = Array.isArray(path) && path.length > 1 ? {
      type:'Feature',
      properties:{ mode:closed ? 'mapped-loop' : 'mapped-waypoints' },
      geometry:{ type:'LineString', coordinates:path.map(point => [point.lng, point.lat]) },
    } : emptyRoute();
    if(!map.isStyleLoaded()){
      map.once('load', () => drawRoute(path));
      return;
    }
    const source = map.getSource('trail-loop-route');
    if(source){
      source.setData(data);
      return;
    }
    map.addSource('trail-loop-route', { type:'geojson', data });
    map.addLayer({
      id:'trail-loop-route-casing',
      type:'line',
      source:'trail-loop-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#ffffff', 'line-width':10, 'line-opacity':0.92 },
    });
    map.addLayer({
      id:'trail-loop-route-line',
      type:'line',
      source:'trail-loop-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#2E684F', 'line-width':6, 'line-opacity':0.98 },
    });
  }

  function pointLabel(index){
    return index === 0 ? 'Start' : `Point ${index + 1}`;
  }

  function renderPointList(){
    pointList.replaceChildren();
    points.forEach((point, index) => {
      const item = document.createElement('li');
      item.className = 'map-loop-point';
      item.append(document.createTextNode(pointLabel(index)));
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.textContent = '×';
      remove.disabled = busy;
      remove.setAttribute('aria-label', `Remove ${pointLabel(index).toLowerCase()}`);
      remove.addEventListener('click', () => removePoint(index));
      item.append(remove);
      pointList.append(item);
    });
  }

  function render(){
    panel.hidden = !active;
    openButton.setAttribute('aria-pressed', String(active));
    if(mapBox) mapBox.classList.toggle('loop-composer-active', active);
    panel.dataset.state = closed ? 'closed' : 'open';
    distance.textContent = preview ? formatApproachDistance(preview.distanceM / 1000) : ', ';
    pointCount.textContent = `${points.length} / ${MAX_POINTS}`;
    addCentreButton.disabled = busy || closed || points.length >= MAX_POINTS;
    undoButton.disabled = busy || !points.length;
    closeButton.hidden = closed;
    closeButton.disabled = busy || points.length < MAX_POINTS || !preview;
    saveButton.hidden = !closed;
    saveButton.disabled = busy || !closed || !preview;
    renderPointList();
  }

  function fitPreview(){
    if(!preview || !Array.isArray(preview.path) || !preview.path.length || !window.maplibregl) return;
    const bounds = new maplibregl.LngLatBounds();
    preview.path.forEach(point => bounds.extend([point.lng, point.lat]));
    map.fitBounds(bounds, { padding:{ top:70, right:50, bottom:190, left:50 }, maxZoom:16, duration:500 });
  }

  async function recalculate(closeRequested){
    const version = ++calculationVersion;
    if(points.length < 2){
      preview = null;
      closed = false;
      drawRoute([]);
      status.textContent = points.length ? 'Tap the map to add a must-pass point.' : 'Tap the map to choose your start.';
      render();
      return;
    }
    busy = true;
    status.textContent = closeRequested ? 'Closing the loop on mapped walking paths…' : 'Connecting the selected points…';
    render();
    const graph = await loadGraph();
    if(version !== calculationVersion) return;
    const options = {
      maxPoints:MAX_POINTS,
      maxLegDistanceM:MAX_LEG_DISTANCE_M,
      maxTotalDistanceM:MAX_TOTAL_DISTANCE_M,
      maxSnapDistanceM:90,
      maxTargetSnapDistanceM:90,
    };
    const result = graph
      ? (closeRequested ? router.routeLoop(points, graph, options) : router.routeThroughPoints(points, graph, options))
      : null;
    busy = false;
    if(!result){
      preview = null;
      closed = false;
      drawRoute([]);
      status.textContent = graph
        ? 'These points cannot form a bounded mapped route. Remove a point and choose a closer path.'
        : 'ORMA’s walking graph is unavailable here right now. Your points have been kept.';
      render();
      return;
    }
    preview = result;
    closed = closeRequested;
    drawRoute(preview.path);
    status.textContent = closed
      ? 'Loop ready. Review mapped access, signs, and current conditions before saving.'
      : points.length < MAX_POINTS
        ? 'Mapped preview ready. Add another must-pass point.'
        : 'Mapped preview ready. Close the loop when the shape looks right.';
    render();
    if(closed) fitPreview();
  }

  function addPoint(point){
    if(!active || busy || closed || points.length >= MAX_POINTS ||
       !point || !Number.isFinite(point.lat) || !Number.isFinite(point.lng)) return;
    points.push({ lat:point.lat, lng:point.lng });
    drawMarkers();
    recalculate(false);
  }

  function removePoint(index){
    if(busy || index < 0 || index >= points.length) return;
    calculationVersion += 1;
    points.splice(index, 1);
    closed = false;
    preview = null;
    saveButton.textContent = 'Save loop';
    drawMarkers();
    recalculate(false);
  }

  function reset(){
    calculationVersion += 1;
    busy = false;
    closed = false;
    points = [];
    preview = null;
    markers.forEach(marker => marker.remove());
    markers = [];
    drawRoute([]);
    status.textContent = 'Tap the map to choose your start.';
    saveButton.textContent = 'Save loop';
    render();
  }

  function open(){
    active = true;
    reset();
    render();
  }

  function dismiss(){
    active = false;
    reset();
    render();
    openButton.focus();
  }

  function save(){
    if(!closed || !preview) return;
    const record = {
      id:`loop-${Date.now()}`,
      sourceTrailId:t.id,
      createdAt:new Date().toISOString(),
      graphUrl:coverageEntry.graphUrl,
      source:preview.source,
      distanceM:Math.round(preview.distanceM),
      points:points.map(point => ({ lat:point.lat, lng:point.lng })),
      path:preview.path.map(point => [point.lat, point.lng]),
    };
    try{
      const existing = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      const records = Array.isArray(existing) ? existing : [];
      localStorage.setItem(STORAGE_KEY, JSON.stringify([record, ...records].slice(0, 20)));
      saveButton.textContent = 'Saved';
      saveButton.disabled = true;
      status.textContent = 'Loop saved on this device. Review local signs and conditions before walking.';
    }catch(error){
      status.textContent = 'This browser could not save the loop. The mapped preview is still available.';
    }
  }

  openButton.addEventListener('click', () => active ? dismiss() : open());
  dismissButton.addEventListener('click', dismiss);
  addCentreButton.addEventListener('click', () => {
    const centre = map.getCenter();
    addPoint({ lat:centre.lat, lng:centre.lng });
  });
  undoButton.addEventListener('click', () => {
    if(closed){
      closed = false;
      preview = null;
      saveButton.textContent = 'Save loop';
      recalculate(false);
      return;
    }
    removePoint(points.length - 1);
  });
  closeButton.addEventListener('click', () => recalculate(true));
  saveButton.addEventListener('click', save);
  map.on('click', event => {
    if(active) addPoint({ lat:event.lngLat.lat, lng:event.lngLat.lng });
  });
  document.addEventListener('keydown', event => {
    if(event.key === 'Escape' && active) dismiss();
  });
  render();
}

function initNearestTrailDirections(map, t){
  const button = document.getElementById('mapNearestDirectionsBtn');
  const panel = document.getElementById('mapNearestDirectionsPanel');
  const status = document.getElementById('mapNearestDirectionsStatus');
  const stepsWrap = document.getElementById('mapNearestDirectionsStepsWrap');
  const stepsList = document.getElementById('mapNearestDirectionsSteps');
  if(!button || !panel || !status || !Array.isArray(t.path) || !t.path.length ||
     !window.DoloPawsTrailAccess || !window.DoloPawsFootpathRouter) return;

  const defaultLabel = 'Get directions to trail';
  const coverage = window.DoloPawsTrailRoutingCoverage;
  const coverageEntry = coverage && coverage.trails ? coverage.trails[t.id] : null;
  const coverageEntries = coverage && coverage.trails
    ? Object.values(coverage.trails).filter(entry => entry && entry.graphUrl && entry.bounds)
    : [];
  let activePlan = null;
  const graphPromises = new Map();
  let originMarker = null;
  let targetMarker = null;
  button.hidden = false;

  function setButtonLabel(label){
    const labelNode = button.querySelector('span');
    if(labelNode) labelNode.textContent = label;
  }

  function markerElement(type){
    const element = document.createElement('span');
    element.className = `map-access-marker map-access-marker--${type}`;
    element.setAttribute('aria-hidden', 'true');
    return element;
  }

  function setPanelMessage(message){
    panel.hidden = !message;
    status.textContent = message || '';
  }

  function clearSteps(){
    if(stepsWrap) stepsWrap.hidden = true;
    if(stepsList) stepsList.replaceChildren();
  }

  function renderSteps(instructions){
    clearSteps();
    if(!stepsWrap || !stepsList || !Array.isArray(instructions) || !instructions.length) return;
    instructions.slice(0, 12).forEach(step => {
      const item = document.createElement('li');
      const distance = step.distanceM > 0
        ? ` for ${formatApproachDistance(step.distanceM / 1000)}`
        : '';
      item.textContent = `${step.action}${distance}`;
      stepsList.appendChild(item);
    });
    stepsWrap.hidden = false;
  }

  function loadRoutingGraph(entry){
    const selectedEntry = entry || coverageEntry;
    if(!selectedEntry || !selectedEntry.graphUrl) return Promise.resolve(null);
    if(!graphPromises.has(selectedEntry.graphUrl)){
      graphPromises.set(selectedEntry.graphUrl, fetch(selectedEntry.graphUrl, { credentials:'same-origin' })
        .then(response => {
          if(!response.ok) throw new Error(`routing-graph-${response.status}`);
          return response.json();
        })
        .then(graph => window.DoloPawsFootpathRouter.validateGraph(graph) ? graph : null)
        .catch(() => null));
    }
    return graphPromises.get(selectedEntry.graphUrl);
  }

  function boundsContainPoint(bounds, point){
    return bounds && point &&
      point.lat >= bounds.south && point.lat <= bounds.north &&
      point.lng >= bounds.west && point.lng <= bounds.east;
  }

  function routingEntriesForPoint(point, origin){
    const candidates = coverageEntries
      .filter(entry => boundsContainPoint(entry.bounds, point) && boundsContainPoint(entry.bounds, origin))
      .sort((first, second) => {
        if(first === coverageEntry) return -1;
        if(second === coverageEntry) return 1;
        const firstArea = (first.bounds.north - first.bounds.south) * (first.bounds.east - first.bounds.west);
        const secondArea = (second.bounds.north - second.bounds.south) * (second.bounds.east - second.bounds.west);
        return firstArea - secondArea;
      });
    return candidates.filter((entry, index) =>
      candidates.findIndex(candidate => candidate.graphUrl === entry.graphUrl) === index);
  }

  function removeMappedRoute(){
    if(!map.isStyleLoaded() || !map.getSource('trail-access-route')) return;
    map.getSource('trail-access-route').setData({ type:'FeatureCollection', features:[] });
  }

  function drawMappedRoute(path){
    if(!map.isStyleLoaded() || !Array.isArray(path) || path.length < 2) return;
    const data = {
      type:'Feature',
      properties:{ mode:'mapped-footpath' },
      geometry:{ type:'LineString', coordinates:path.map(point => [point.lng, point.lat]) },
    };
    const source = map.getSource('trail-access-route');
    if(source){
      source.setData(data);
      return;
    }
    map.addSource('trail-access-route', { type:'geojson', data });
    map.addLayer({
      id:'trail-access-route-casing',
      type:'line',
      source:'trail-access-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#ffffff', 'line-width':8, 'line-opacity':0.92 },
    });
    map.addLayer({
      id:'trail-access-route-line',
      type:'line',
      source:'trail-access-route',
      layout:{ 'line-join':'round', 'line-cap':'round' },
      paint:{ 'line-color':'#3E7A91', 'line-width':5, 'line-opacity':0.96 },
    });
  }

  function showPlan(plan, mapped){
    if(originMarker) originMarker.remove();
    originMarker = new maplibregl.Marker({ element:markerElement('you') })
      .setLngLat([plan.origin.lng, plan.origin.lat])
      .addTo(map);
    const bounds = new maplibregl.LngLatBounds();
    bounds.extend([plan.origin.lng, plan.origin.lat]);
    if(mapped && Array.isArray(plan.path)){
      drawMappedRoute(plan.path);
      plan.path.forEach(point => bounds.extend([point.lng, point.lat]));
    } else {
      removeMappedRoute();
      bounds.extend([plan.target.lng, plan.target.lat]);
    }
    if(targetMarker) targetMarker.remove();
    if(plan.mode === 'mapped-point' || plan.mode === 'external-point'){
      targetMarker = new maplibregl.Marker({ element:markerElement('target') })
        .setLngLat([plan.target.lng, plan.target.lat])
        .addTo(map);
    }
    map.fitBounds(bounds, { padding:70, maxZoom:16, duration:700 });
  }

  async function routeToSelectedPoint(target){
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    clearSteps();
    setPanelMessage('Connecting your location to the selected mapped route…');
    try{
      const origin = await window.DoloPawsTrailAccess.currentPosition(navigator);
      if(Number.isFinite(origin.accuracyM) && origin.accuracyM > window.DoloPawsTrailAccess.MAX_GPS_ACCURACY_M){
        setPanelMessage(`Your location is only accurate to about ${Math.round(origin.accuracyM)} m. Move into a clearer area and try again.`);
        setButtonLabel('Try again');
        return;
      }
      const entries = routingEntriesForPoint(target, origin);
      let plan = null;
      for(const entry of entries){
        const graph = await loadRoutingGraph(entry);
        plan = await window.DoloPawsTrailAccess.planMappedPoint(
          navigator,
          target,
          graph,
          window.DoloPawsFootpathRouter,
          navigator.userAgent,
          { origin, maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
        );
        if(plan.mode === 'mapped-point') break;
      }
      if(!plan){
        plan = await window.DoloPawsTrailAccess.planMappedPoint(
          navigator,
          target,
          null,
          window.DoloPawsFootpathRouter,
          navigator.userAgent,
          { origin, maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
        );
      }
      activePlan = plan;
      if(plan.mode === 'mapped-point'){
        showPlan(plan, true);
        renderSteps(plan.instructions);
        const targetSnap = plan.targetSnapDistanceM > 20
          ? ` The selected point was snapped ${formatApproachDistance(plan.targetSnapDistanceM / 1000)} to a connected path.`
          : '';
        setPanelMessage(`Mapped walking route · ${formatApproachDistance(plan.distanceKm)} to the selected route point.${targetSnap} Check local signs and temporary closures.`);
        setButtonLabel(defaultLabel);
        return;
      }
      if(plan.mode === 'external-point' && plan.allowed){
        showPlan(plan, false);
        setPanelMessage('This selected point is not connected to ORMA’s current walking graph. Your maps app can calculate the approach instead.');
        setButtonLabel('Open directions to selected point');
        return;
      }
      setPanelMessage('That point is outside ORMA’s current walking coverage. Choose a closer mapped route point.');
      setButtonLabel(defaultLabel);
    }catch(error){
      setPanelMessage('We could not calculate a route to that point. Check your location signal and try again.');
      setButtonLabel(defaultLabel);
    }finally{
      button.disabled = false;
      button.removeAttribute('aria-busy');
    }
  }

  button.addEventListener('click', async () => {
    if(activePlan && activePlan.url){
      window.open(activePlan.url, '_blank', 'noopener');
      return;
    }

    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    setButtonLabel('Calculating directions…');
    clearSteps();
    setPanelMessage('Checking your location against mapped walking paths…');
    try{
      const graph = await loadRoutingGraph();
      const plan = await window.DoloPawsTrailAccess.planTrailEntry(
        navigator,
        t,
        graph,
        window.DoloPawsFootpathRouter,
        navigator.userAgent,
        { maxRouteDistanceM:5000, maxFallbackDistanceKm:5 }
      );
      if(plan.mode === 'unreliable-location'){
        setPanelMessage(`Your location is only accurate to about ${Math.round(plan.accuracyM)} m. Move into a clearer area and try again.`);
        setButtonLabel('Try again');
        return;
      }
      if(plan.mode === 'mapped-footpath'){
        activePlan = plan;
        showPlan(plan, true);
        renderSteps(plan.instructions);
        const snapNote = plan.snapDistanceM > 20
          ? ` Your GPS is about ${formatApproachDistance(plan.snapDistanceM / 1000)} from the mapped path.`
          : '';
        setPanelMessage(`Mapped footpath route · ${formatApproachDistance(plan.distanceKm)} to the trail.${snapNote} Check local signs and temporary closures.`);
        setButtonLabel('Refresh walking route');
        return;
      }
      if(plan.mode === 'nearest-route'){
        activePlan = plan;
        showPlan(plan, false);
        const distanceM = plan.distanceKm * 1000;
        const overlapsFix = Number.isFinite(plan.accuracyM) && distanceM <= plan.accuracyM;
        setPanelMessage(overlapsFix
          ? 'Your location overlaps this trail. Open your maps app for the nearest mapped point, and check local signs before joining.'
          : `The nearest point on this trail is about ${formatApproachDistance(plan.distanceKm)} away. Your maps app will calculate the walk; check local signs and access before joining.`);
        setButtonLabel('Open directions to nearest trail point');
        return;
      }
      if(plan.mode === 'recommended-start' && plan.allowed){
        activePlan = plan;
        showPlan(plan, false);
        const startType = plan.targetKind === 'mapped-start' ? 'listed route start' : 'recommended start';
        setPanelMessage(`ORMA does not yet have a connected footpath network here. The ${startType} is about ${formatApproachDistance(plan.distanceKm)} away as the crow flies; your maps app will calculate the actual walk.`);
        setButtonLabel('Open directions to start');
        return;
      }
      if(plan.mode === 'recommended-start'){
        const startType = plan.targetKind === 'mapped-start' ? 'listed route start' : 'recommended start';
        setPanelMessage(`The ${startType} is about ${formatApproachDistance(plan.distanceKm)} away. Walking directions are available when you are within 5 km.`);
        setButtonLabel('Try again');
        return;
      }
      setPanelMessage('ORMA cannot identify a reliable access point for this trail yet. Use the recommended starting-point information below the map.');
      setButtonLabel(defaultLabel);
    }catch(error){
      const denied = error && (error.code === 1 || error.message === 'geolocation-unavailable');
      setPanelMessage(denied
        ? 'Allow location access to find the nearest point on this trail.'
        : 'We could not get a reliable location. Check your signal and try again.');
      setButtonLabel(defaultLabel);
    }finally{
      button.disabled = false;
      button.removeAttribute('aria-busy');
    }
  });
}

function sampledTrailPath(trail, maxPoints = 30){
  const path = Array.isArray(trail && trail.path) && trail.path.length
    ? trail.path
    : (trail && typeof trail.lat === 'number' && typeof trail.lng === 'number' ? [[trail.lat, trail.lng]] : []);
  if(path.length <= maxPoints) return path;
  const step = Math.ceil(path.length / maxPoints);
  const sampled = path.filter((_, index) => index % step === 0);
  if(sampled[sampled.length - 1] !== path[path.length - 1]) sampled.push(path[path.length - 1]);
  return sampled;
}

function nearbyTrailCandidates(currentTrail, allTrails, radiusKm = 25, limit = 5){
  const currentPath = sampledTrailPath(currentTrail);
  if(!currentPath.length) return [];
  return (allTrails || [])
    .filter(trail => trail && trail.id !== currentTrail.id && Array.isArray(trail.path) && trail.path.length > 1)
    .map(trail => {
      const candidatePath = sampledTrailPath(trail);
      let distanceKm = Infinity;
      let mapPoint = candidatePath[0];
      currentPath.forEach(currentPoint => candidatePath.forEach(candidatePoint => {
        const distance = mapDistanceKm(currentPoint, candidatePoint);
        if(distance < distanceKm){
          distanceKm = distance;
          mapPoint = candidatePoint;
        }
      }));
      return { trail, distanceKm, mapPoint };
    })
    .filter(item => item.distanceKm <= radiusKm)
    .sort((a, b) => a.distanceKm - b.distanceKm)
    .slice(0, limit);
}

// Finds the real point along an actual GPS path at a given fraction of its
// total length (0 = start, 1 = end). Used to place rifugi/water icons at
// their true position on the map, rather than guessing coordinates.
function pointAtFraction(path, fraction){
  const total = path.reduce((sum, p, i) => i === 0 ? 0 : sum + distMeters(path[i-1], p), 0);
  const target = total * Math.max(0, Math.min(1, fraction));
  let acc = 0;
  for(let i = 0; i < path.length - 1; i++){
    const seg = distMeters(path[i], path[i+1]);
    if(acc + seg >= target){
      const t = seg > 0 ? (target - acc) / seg : 0;
      return [
        path[i][0] + (path[i+1][0] - path[i][0]) * t,
        path[i][1] + (path[i+1][1] - path[i][1]) * t,
      ];
    }
    acc += seg;
  }
  return path[path.length - 1];
}

// Elevation profile chart with two-way hover sync: hovering the chart moves
// a cursor dot on the map; hovering near the route on the map highlights
// the matching point on the chart. Honest note on data granularity: this
// draws whatever is in t.elevationProfile, currently a sparse 5-6 point
// sample for hand-built trails, but it'll render just as correctly (and
// more smoothly) once a trail has real per-vertex elevation from the
// build-trail.mjs/build-route.mjs pipeline. The chart code doesn't care
// which source the numbers came from.
function setupElevationProfile(map, t){
  const panel = document.getElementById('tdElevationPanel');
  if(!Array.isArray(t.elevationProfile) || t.elevationProfile.length < 2 || !Array.isArray(t.path)){
    if(panel) panel.hidden = true;
    return;
  }

  const wrap = document.getElementById('elevationProfileWrap');
  const svg = document.getElementById('elevProf');
  const readout = document.getElementById('elevReadout');
  const liveReadout = document.getElementById('tdElevLive');
  const rangeReadout = document.getElementById('tdElevRange');
  wrap.hidden = false;

  const profile = t.elevationProfile; // [{km, elev}, ...]
  const totalKm = t.distance;
  const elevs = profile.map(p => p.elev);
  const eMin = Math.min(...elevs), eMax = Math.max(...elevs);
  if(rangeReadout) rangeReadout.textContent = `${Math.round(eMin)}–${Math.round(eMax)} m`;
  const startReadout = document.getElementById('tdElevStart');
  const highReadout = document.getElementById('tdElevHigh');
  const climbReadout = document.getElementById('tdElevClimb');
  const figures = document.getElementById('tdElevFigs');
  if(startReadout) startReadout.textContent = `${Math.round(profile[0].elev)} m`;
  if(highReadout) highReadout.textContent = `${Math.round(eMax)} m`;
  if(climbReadout) climbReadout.textContent = `${Math.round(Number(t.elevation) || 0)} m`;
  if(figures) figures.hidden = false;
  const VW = 1000, VH = 170, padL = 6, padR = 6, padT = 14, padB = 20;
  const x = km => padL + (km / totalKm) * (VW - padL - padR);
  const y = elev => padT + (1 - (elev - eMin) / ((eMax - eMin) || 1)) * (VH - padT - padB);

  const NS = 'http://www.w3.org/2000/svg';
  const mk = (tag, attrs) => {
    const el = document.createElementNS(NS, tag);
    for(const k in attrs) el.setAttribute(k, attrs[k]);
    return el;
  };

  let dLine = `M ${x(profile[0].km)} ${y(profile[0].elev)}`;
  profile.slice(1).forEach(p => { dLine += ` L ${x(p.km)} ${y(p.elev)}`; });
  const areaD = `${dLine} L ${x(profile[profile.length-1].km)} ${VH-padB} L ${x(profile[0].km)} ${VH-padB} Z`;
  svg.appendChild(mk('path', { d: areaD, fill: '#2E4034', opacity: '0.1' }));
  svg.appendChild(mk('path', { d: dLine, fill: 'none', stroke: '#2E4034', 'stroke-width': '2' }));

  [eMin, (eMin+eMax)/2, eMax].forEach(v => {
    svg.appendChild(mk('line', { x1: padL, x2: VW-padR, y1: y(v), y2: y(v), stroke: 'var(--paper-line)', 'stroke-width': '1' }));
    const label = mk('text', { x: padL+4, y: y(v)-3, 'font-size': '10', fill: 'var(--ink-soft)' });
    label.textContent = `${Math.round(v)} m`;
    svg.appendChild(label);
  });

  const cursorLine = mk('line', { y1: padT, y2: VH-padB, stroke: '#6FA8BE', 'stroke-width': '1.5', 'stroke-dasharray': '3 3', opacity: '0' });
  const cursorDot = mk('circle', { r: '4', fill: '#6FA8BE', stroke: '#fff', 'stroke-width': '1.5', opacity: '0' });
  svg.appendChild(cursorLine);
  svg.appendChild(cursorDot);

  // Map cursor marker
  map.addSource('elev-cursor', { type: 'geojson', data: { type: 'Point', coordinates: t.path[0].slice().reverse() } });
  map.addLayer({
    id: 'elev-cursor-layer', type: 'circle', source: 'elev-cursor',
    paint: { 'circle-radius': 6, 'circle-color': '#6FA8BE', 'circle-stroke-color': '#fff', 'circle-stroke-width': 2, 'circle-opacity': 0 },
  });

  function highlightAtKm(km){
    cursorLine.setAttribute('x1', x(km)); cursorLine.setAttribute('x2', x(km)); cursorLine.setAttribute('opacity', '1');
    // interpolate elevation for a smooth readout even between sparse samples
    let elev = profile[0].elev;
    for(let i = 1; i < profile.length; i++){
      if(km <= profile[i].km){
        const span = profile[i].km - profile[i-1].km;
        const frac = span > 0 ? (km - profile[i-1].km) / span : 0;
        elev = profile[i-1].elev + (profile[i].elev - profile[i-1].elev) * frac;
        break;
      }
    }
    cursorDot.setAttribute('cx', x(km)); cursorDot.setAttribute('cy', y(elev)); cursorDot.setAttribute('opacity', '1');
    readout.textContent = `${km.toFixed(1)} km · ${Math.round(elev)} m`;
    if(liveReadout) liveReadout.textContent = `${km.toFixed(1)} km · ~${Math.round(elev)} m route elevation`;

    const [lat, lng] = pointAtFraction(t.path, totalKm > 0 ? km / totalKm : 0);
    const src = map.getSource('elev-cursor');
    if(src){ src.setData({ type: 'Point', coordinates: [lng, lat] }); map.setPaintProperty('elev-cursor-layer', 'circle-opacity', 1); }
  }

  // Let hike-mode.js drive the same cursor from live GPS position.
  window._dolopawsElevHighlight = highlightAtKm;

  svg.addEventListener('mousemove', (ev) => {
    const rect = svg.getBoundingClientRect();
    const px = (ev.clientX - rect.left) / rect.width * VW;
    const km = Math.max(0, Math.min(totalKm, ((px - padL) / (VW - padL - padR)) * totalKm));
    highlightAtKm(km);
  });

  // Map -> chart: hovering near the route line highlights the matching point
  map.on('mousemove', (e) => {
    let bestKm = 0, bestDist = Infinity, acc = 0;
    for(let i = 0; i < t.path.length; i++){
      const d = distMeters([e.lngLat.lat, e.lngLat.lng], t.path[i]);
      if(d < bestDist){ bestDist = d; bestKm = (i / (t.path.length - 1)) * totalKm; }
    }
    if(bestDist < 80) highlightAtKm(bestKm); // only react when hovering near the actual route
  });
}

function makeIconEl(iconKey, bgColor){
  if(window.DoloPawsIcons) return window.DoloPawsIcons.createMarkerElement(iconKey, { color: bgColor });
  const fallback = document.createElement('div');
  fallback.className = 'dp-marker';
  fallback.style.background = bgColor;
  fallback.style.borderRadius = '50%';
  fallback.style.border = '2px solid #fff';
  fallback.textContent = '•';
  return fallback;
}

function addTerrainToggle(map, containerId, exaggeration, pitch3D, existingBtn){
  // With `existingBtn`, the toggle joins the Map · Satellite · 3D group.
  let btn = existingBtn || null;
  if(!btn){
    const container = document.getElementById(containerId);
    if(!container) return;
    container.style.position = container.style.position || 'relative';
    btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = window.t('trail.view3d');
    btn.className = 'map-btn map-btn--terrain';
    container.appendChild(btn);
  }

  let elevationVisible = false; // clean, flat, label-first map by default
  let flatCamera = null;
  btn.addEventListener('click', () => {
    if(!elevationVisible){
      const currentZoom = typeof map.getZoom === 'function' ? map.getZoom() : 12.25;
      flatCamera = {
        center: typeof map.getCenter === 'function' ? map.getCenter() : undefined,
        zoom: currentZoom,
        bearing: typeof map.getBearing === 'function' ? map.getBearing() : undefined,
      };
      map.setTerrain({ source: 'terrain-dem-3d', exaggeration });
      if(!map.getLayer('hillshade-layer')){
        const beforeLayer = map.getLayer('waymarked-hiking-layer')
          ? 'waymarked-hiking-layer'
          : (map.getStyle().layers.find(layer => layer.type === 'symbol') || {}).id;
        map.addLayer({
          id: 'hillshade-layer',
          type: 'hillshade',
          source: 'terrain-dem',
          paint: {
            'hillshade-method': 'igor',
            'hillshade-exaggeration': 0.22,
            'hillshade-shadow-color': '#81907f',
            'hillshade-highlight-color': '#fffdf6',
            'hillshade-accent-color': '#60705f',
          },
        }, beforeLayer); // keep hillshade below the trail overlay and labels
      }
      // At close trail-detail zooms the camera can sit below a 2,000–3,000 m
      // terrain surface, blanking the map. Pull back to a safe planning zoom.
      map.easeTo({ pitch: pitch3D, zoom: Math.min(currentZoom, 12.25), duration: 500 });
      if(existingBtn){ btn.classList.add('on'); btn.setAttribute('aria-pressed', 'true'); }
      else btn.textContent = window.t('trail.viewFlat');
    } else {
      map.setTerrain(null);
      if(map.getLayer('hillshade-layer')) map.removeLayer('hillshade-layer');
      map.easeTo({
        pitch: 0,
        center: flatCamera && flatCamera.center,
        zoom: flatCamera && flatCamera.zoom,
        bearing: flatCamera && flatCamera.bearing,
        duration: 500,
      });
      if(existingBtn){ btn.classList.remove('on'); btn.setAttribute('aria-pressed', 'false'); }
      else btn.textContent = window.t('trail.view3d');
    }
    elevationVisible = !elevationVisible;
  });
}

function increaseLabelDensity(map){
  const layers = map.getStyle().layers || [];
  layers.forEach(layer => {
    if(layer.type !== 'symbol') return;
    const sl = layer['source-layer'];
    // Only boost PLACE names (towns, villages, hamlets) and mountain peaks:
    // clearing their minzoom makes them appear even when zoomed far out,
    // which is the effect that was actually wanted. Everything else (POI
    // icons, road names, house numbers) keeps the style's own collision
    // rules, forcing those all visible at once made town centers like
    // Canazei unreadably dense.
    if(sl !== 'place' && sl !== 'mountain_peak') return;
    try {
      map.setLayerZoomRange(layer.id, 0, 24);
      map.setLayoutProperty(layer.id, 'text-optional', true);
      // NOTE: deliberately NOT setting text-allow-overlap/icon-allow-overlap
      // anymore, that disabled collision detection entirely and was the
      // root cause of the overcrowded map. MapLibre's collision logic now
      // prunes overlapping labels automatically at every zoom.
    } catch(e) { /* some layers may not support one of these props, skip silently */ }
  });
}

function addTerrainSource(map){
  map.addSource('terrain-dem', {
    type: 'raster-dem',
    tiles: ['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],
    tileSize: 256,
    encoding: 'terrarium',
    maxzoom: 15,
  });
  // MapLibre renders more reliably when hillshade and 3D terrain do not
  // compete for the same raster-dem source.
  map.addSource('terrain-dem-3d', {
    type: 'raster-dem',
    tiles: ['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],
    tileSize: 256,
    encoding: 'terrarium',
    maxzoom: 15,
  });
}

// Always-on subtle relief, AllTrails-style: terrain reads at a glance even
// in flat mode. The 3D toggle's own stronger hillshade layers on top.
function addBaseHillshade(map, beforeId){
  if(map.getLayer('base-hillshade') || !map.getSource('terrain-dem')) return;
  map.addLayer({
    id: 'base-hillshade',
    type: 'hillshade',
    source: 'terrain-dem',
    paint: {
      // Strengthened so the relief actually reads in flat mode: the old 0.25
      // was so faint the map looked flat beside AllTrails/Strava. A cool
      // shadow and warm highlight model the ridges like a shaded-relief map
      // without shouting over the calm base.
      //
      // Ramped, as the homepage's copy is, so the two cannot drift. It reaches
      // the same 0.45 by zoom 13 and a detail map opens no lower than that on
      // all but a handful of trails, so this map is unchanged in practice; the
      // ramp only spares the few that open at region zoom.
      'hillshade-exaggeration': [
        'interpolate', ['linear'], ['zoom'], 8, 0.16, 11, 0.3, 13, 0.45,
      ],
      'hillshade-shadow-color': '#4A5347',
      'hillshade-highlight-color': '#FBF7EC',
      'hillshade-method': 'igor',
    },
  }, beforeId && map.getLayer(beforeId) ? beforeId : undefined);
}

// Lifts on the trail detail map, ALL of them, same data as the homepage
// (the global `gondolas` array from trails-data.js). Lines and stations are
// GeoJSON layers rather than DOM markers, so rendering all ~700 lifts and
// ~1,400 stations costs nothing.
function escapeLiftPopupText(value){
  return String(value == null ? '' : value).replace(/[&<>"']/g,
    char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[char]);
}

function publicLiftNote(note){
  return escapeLiftPopupText(String(note || '')
    .replace(/Operating season not recorded\s*[—-]\s*check directly with the operator before planning around it\.\s*/gi, '')
    .replace(/Station order \(from\/to\) reflects raw OSM way direction, NOT independently verified against elevation\s*-\s*treat the endpoint labels as unconfirmed for this batch\.\s*/gi, '')
    .trim());
}

function renderAllLifts(map, options){
  if (typeof gondolas === 'undefined' || !Array.isArray(gondolas) || !gondolas.length) return;
  if (map.getSource('detail-gondolas')) return;
  const visibility = options && options.visible ? 'visible' : 'none';

  const lineFeatures = [], stationFeatures = [];
  gondolas.forEach(g => {
    if (!g.from || !g.to || typeof g.from.lat !== 'number' || typeof g.to.lat !== 'number') return;
    lineFeatures.push({
      type: 'Feature',
      properties: { name: g.name, note: g.note || '', status: g.status },
      geometry: { type: 'LineString', coordinates: [[g.from.lng, g.from.lat], [g.to.lng, g.to.lat]] },
    });
    [g.from, g.to].forEach(st => {
      stationFeatures.push({
        type: 'Feature',
        properties: { name: g.name, note: g.note || '' },
        geometry: { type: 'Point', coordinates: [st.lng, st.lat] },
      });
    });
  });

  map.addSource('detail-gondolas', { type: 'geojson', data: { type: 'FeatureCollection', features: lineFeatures } });
  map.addLayer({
    id: 'detail-gondolas-line',
    type: 'line',
    source: 'detail-gondolas',
    layout: { 'line-join': 'round', 'line-cap': 'round', visibility },
    paint: {
      'line-color': ['match', ['get', 'status'], 'summer', '#4E90A8', 'no-summer', '#9C3A25', '#5A5548'],
      'line-width': 1.5,
      'line-opacity': 0.9,
      'line-dasharray': ['match', ['get', 'status'], 'summer', ['literal', [1, 0]], ['literal', [2, 1]]],
    },
  });
  map.addSource('detail-gondola-stations', { type: 'geojson', data: { type: 'FeatureCollection', features: stationFeatures } });
  if(window.DoloPawsIcons){
    map.addLayer({
      id: 'detail-gondola-stations-layer',
      type: 'symbol',
      source: 'detail-gondola-stations',
      layout: {
        'icon-image': window.DoloPawsIcons.getMapImageName('lifts'),
        'icon-size': 1,
        visibility,
      },
    });
  } else {
    map.addLayer({
      id: 'detail-gondola-stations-layer',
      type: 'circle',
      source: 'detail-gondola-stations',
      layout: { visibility },
      paint: { 'circle-radius': 5, 'circle-color': '#4E90A8', 'circle-stroke-width': 1.5, 'circle-stroke-color': '#fff' },
    });
  }

  ['detail-gondolas-line', 'detail-gondola-stations-layer'].forEach(id => {
    map.on('mouseenter', id, () => { map.getCanvas().style.cursor = 'pointer'; });
    map.on('mouseleave', id, () => { map.getCanvas().style.cursor = ''; });
    map.on('click', id, (e) => {
      const p = e.features[0].properties;
      const note = publicLiftNote(p.note);
      new maplibregl.Popup({ offset: 10 })
        .setLngLat(e.lngLat)
        .setHTML(`<b>🚡 ${escapeLiftPopupText(p.name)}</b>${note ? '<br>' + note : ''}`)
        .addTo(map);
    });
  });
}

// ============================================================
// IMPORTED CIRCUITS, start where you can actually park.
// OSM route relations have no official start point: the import stitches
// their segments into one line and begins wherever stitching happened to
// start, so a loop's km 0 can land mid-slope, far from any access.
// Before rendering, look up real amenity=parking spots around the route
// (Overpass, cached locally for 30 days) and rotate the loop so km 0
// sits at the path point nearest a parking area. Everything downstream, // 🚩 flag, directions, arrows, weather anchor, hike mode, follows the
// rotated order automatically. Falls back silently to the imported order
// when no parking is close enough or the lookup fails or times out.
// ============================================================
const PARK_CACHE_TTL = 30 * 24 * 3600 * 1000;
const PARK_MAX_DIST_M = 350;      // parking must be this close to the route
// Parking refinement is helpful, but it is not allowed to delay the first
// trail render. The result is cached for the next visit if it arrives later.
const PARK_LOOKUP_WAIT_MS = 0;

function isLoopPath(path){
  return Array.isArray(path) && path.length > 20 &&
    distMeters(path[0], path[path.length - 1]) < 250;
}

function fetchNearbyParking(path){
  let minLat = 90, maxLat = -90, minLng = 180, maxLng = -180;
  path.forEach(([lat, lng]) => {
    if(lat < minLat) minLat = lat;
    if(lat > maxLat) maxLat = lat;
    if(lng < minLng) minLng = lng;
    if(lng > maxLng) maxLng = lng;
  });
  const PAD = 0.008; // ~800 m beyond the route's bounding box
  const bbox = `${minLat - PAD},${minLng - PAD},${maxLat + PAD},${maxLng + PAD}`;
  const query = `[out:json][timeout:8];(node["amenity"="parking"](${bbox});way["amenity"="parking"](${bbox}););out center 60;`;
  const mirrors = ['https://overpass-api.de/api/interpreter', 'https://overpass.kumi.systems/api/interpreter'];
  const tryMirror = (i) => fetch(mirrors[i], {
    method: 'POST',
    body: 'data=' + encodeURIComponent(query),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  })
    .then(r => { if(!r.ok) throw new Error('overpass ' + r.status); return r.json(); })
    .catch(err => { if(i + 1 < mirrors.length) return tryMirror(i + 1); throw err; });
  return tryMirror(0).then(data => (data.elements || []).map(el => {
    const lat = el.lat != null ? el.lat : (el.center && el.center.lat);
    const lng = el.lon != null ? el.lon : (el.center && el.center.lon);
    return (lat == null || lng == null) ? null : { lat, lng, name: (el.tags && el.tags.name) || '' };
  }).filter(Boolean));
}

function nearestPathIndex(path, pt){
  let best = 0, bestD = Infinity;
  for(let i = 0; i < path.length; i++){
    const d = distMeters(path[i], [pt.lat, pt.lng]);
    if(d < bestD){ bestD = d; best = i; }
  }
  return { index: best, dist: bestD };
}

function applyLoopRotation(trail, rot){
  if(rot.index > 0){
    const path = trail.path;
    const closed = distMeters(path[0], path[path.length - 1]) < 30;
    const open = closed ? path.slice(0, -1) : path.slice();
    const rotated = open.slice(rot.index).concat(open.slice(0, rot.index));
    rotated.push(rotated[0].slice()); // close the loop at the new start
    trail.path = rotated;
  }
  trail.startPoint = {
    lat: trail.path[0][0],
    lng: trail.path[0][1],
    label: rot.name
      ? window.t('trail.startParkName', { name: rot.name })
      : window.t('trail.startParking'),
  };
  trail.lat = trail.path[0][0];
  trail.lng = trail.path[0][1];
}

function improveLoopStart(trail, options){
  if(!trail || trail.curated !== false || !isLoopPath(trail.path)) return Promise.resolve();
  const deferOnMiss = !!(options && options.deferOnMiss);
  const cacheKey = 'dolopaws-parkstart-' + trail.id;
  try {
    const cached = JSON.parse(localStorage.getItem(cacheKey) || 'null');
    if(cached && Date.now() - cached.at < PARK_CACHE_TTL){
      if(cached.rot) applyLoopRotation(trail, cached.rot);
      return Promise.resolve();
    }
  } catch (e) { /* unreadable cache, just refetch */ }

  const lookup = fetchNearbyParking(trail.path).then(parkings => {
    let best = null;
    parkings.forEach(p => {
      const near = nearestPathIndex(trail.path, p);
      if(near.dist <= PARK_MAX_DIST_M && (!best || near.dist < best.dist)){
        best = { index: near.index, dist: near.dist, name: p.name };
      }
    });
    const rot = best ? { index: best.index, name: best.name } : null;
    try { localStorage.setItem(cacheKey, JSON.stringify({ at: Date.now(), rot })); } catch (e) {}
    return rot;
  }).catch(() => null);

  // A trail-detail navigation must never wait on Overpass. On the first visit,
  // let the lookup finish into the cache while the page renders immediately;
  // later visits can apply that cached start synchronously above.
  if(deferOnMiss) return Promise.resolve();

  // Non-navigation callers may still opt into the former bounded wait.
  const timeout = new Promise(res => setTimeout(() => res('timeout'), PARK_LOOKUP_WAIT_MS));
  return Promise.race([lookup, timeout]).then(rot => {
    if(rot && rot !== 'timeout') applyLoopRotation(trail, rot);
  });
}


// ============================================================
// "FROM PARKING TO PAWS", one named, km-ordered itinerary that
// replaces the separate directions/rifugi/water lists. Base steps
// (parking, start, decision points, finish) render immediately;
// named amenities from the OSM files arrive asynchronously via
// detail-pois.js callbacks and slot in by km.
// ============================================================
const itin = { trail: null, items: [], cumKm: null };

// Curated trail data stores labels in English; translate the known
// templates on the fly in Italian mode (same approach as imported descs).
function trLabel(label){
  if(!label || (window.DoloPawsI18n && window.DoloPawsI18n.lang) !== 'it') return label;
  const RULES = [
    [/^Start here, main parking area at (.+)$/, 'Parti qui, parcheggio principale a $1'],
    [/^Start here, main lake access & parking, by (.+)$/, 'Parti qui, accesso principale al lago e parcheggio, presso $1'],
    [/^Route start per OpenStreetMap, best parking\/access not yet verified$/, 'Inizio del percorso secondo OpenStreetMap, parcheggio/accesso migliore non ancora verificato'],
    [/^Lakeside fountain$/, 'Fontana in riva al lago'],
    [/^Trailhead fountain$/, 'Fontana alla partenza'],
    [/^Village fountain$/, 'Fontana del paese'],
    [/^Waterfall stream$/, 'Torrente della cascata'],
    [/^Stream crossing$/, 'Attraversamento del torrente'],
    [/^Drinking water \(OSM-verified location\)$/, 'Acqua potabile (posizione verificata su OSM)'],
    [/^Mountain\/upper station$/, 'Stazione a monte'],
    [/^Valley\/lower station$/, 'Stazione a valle'],
  ];
  for(const [re, out] of RULES){ if(re.test(label)) return label.replace(re, out); }
  return label;
}

function itinIcon(kind){
  const S = 'width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" style="flex:none;"';
  if(kind === 'park') return `<svg ${S}><rect x="3" y="3" width="18" height="18" rx="5" fill="#378ADD"/><path d="M9 17V7h4a3.2 3.2 0 010 6.4H9" fill="none" stroke="#fff" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  if(kind === 'flag') return `<svg ${S}><path d="M7 21V4" stroke="#2E4034" stroke-width="2" stroke-linecap="round"/><path d="M7 5h10l-2.4 3.5L17 12H7z" fill="#E24B4A"/></svg>`;
  if(kind === 'food') return `<svg ${S}><path d="M5 9h11v6a4 4 0 01-4 4H9a4 4 0 01-4-4z" fill="#BA7517"/><path d="M16 10h1.6a2.2 2.2 0 010 4.4H16" fill="none" stroke="#BA7517" stroke-width="1.8"/><path d="M8.5 6.5c0-1 .8-1.4.8-2.3M12 6.5c0-1 .8-1.4.8-2.3" stroke="#BA7517" stroke-width="1.5" stroke-linecap="round" fill="none"/></svg>`;
  if(kind === 'hut') return `<svg ${S}><path d="M4 11l8-7 8 7" fill="none" stroke="#8A5A16" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M6 10v9h12v-9" fill="#D6A038" stroke="#8A5A16" stroke-width="1.6" stroke-linejoin="round"/><path d="M10 19v-5h4v5" fill="#8A5A16"/></svg>`;
  if(kind === 'water') return `<svg ${S}><path d="M12 3c3 3.6 4.8 6.3 4.8 8.8a4.8 4.8 0 11-9.6 0C7.2 9.3 9 6.6 12 3z" fill="#378ADD"/></svg>`;
  if(kind === 'switch') return `<svg ${S}><path d="M12 20v-8M12 12L6.5 6M12 12l5.5-6" fill="none" stroke="#7F77DD" stroke-width="2.2" stroke-linecap="round"/><circle cx="6.5" cy="6" r="1.7" fill="#7F77DD"/><circle cx="17.5" cy="6" r="1.7" fill="#AFA9EC"/></svg>`;
  if(kind === 'view') return `<svg ${S}><path d="M5 8h3l1.2-2h5.6L16 8h3v10H5z" fill="none" stroke="#28736B" stroke-width="2" stroke-linejoin="round"/><circle cx="12" cy="13" r="3" fill="none" stroke="#28736B" stroke-width="2"/></svg>`;
  if(kind === 'picnic') return `<svg ${S}><path d="M4 9.5h16M8 9.5 5.5 18M16 9.5l2.5 8.5M6.6 14.5h10.8" fill="none" stroke="#4E7256" stroke-width="2" stroke-linecap="round"/></svg>`;
  if(kind === 'sight') return `<svg ${S}><path d="M8 20V4.5" stroke="#5A5548" stroke-width="2" stroke-linecap="round"/><path d="M8 5.5h8.5l-2.1 3 2.1 3H8z" fill="#5A5548"/></svg>`;
  return `<svg ${S}><ellipse cx="12" cy="15.5" rx="4" ry="3.4" fill="#1D9E75"/><ellipse cx="7" cy="10.8" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="10.5" cy="8.6" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="14" cy="8.6" rx="1.5" ry="2" fill="#5DCAA5"/><ellipse cx="17.5" cy="10.8" rx="1.5" ry="2" fill="#5DCAA5"/></svg>`;
}

function itinCumKm(path){
  const cum = [0];
  for(let i = 1; i < path.length; i++) cum.push(cum[i-1] + distMeters(path[i-1], path[i]) / 1000);
  return cum;
}

function itinEsc(x){
  return String(x).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
}

function itinRender(){
  const box = document.getElementById('trailItinerary');
  if(!box || !itin.trail) return;
  const items = itin.items.slice().sort((a, b) => a.sort - b.sort);
  box.innerHTML = items.map(it =>
    `<div class="itin-row">${itinIcon(it.icon)}<span>${it.html}</span></div>`).join('');
}

function itinAdd(icon, sort, html){
  itin.items.push({ icon, sort, html });
}

function itinKmLabel(km){
  return `<b style="font-weight:700;">Km ${km % 1 === 0 ? km : km.toFixed(1)}</b>`;
}

function buildItinerary(t){
  itin.trail = t;
  itin.items = [];
  itin.cumKm = Array.isArray(t.path) && t.path.length > 1 ? itinCumKm(t.path) : null;
  const isLoop = Array.isArray(t.path) && t.path.length > 1
    && distMeters(t.path[0], t.path[t.path.length-1]) < 200;

  // 1. Parking / access, the named startPoint label plus a directions
  // link into whatever navigation app this device prefers: Apple Maps on
  // iOS/macOS, Google Maps elsewhere. Neutral label, destination pre-filled.
  const sp = t.startPoint || { lat: t.lat, lng: t.lng, label: '' };
  const isApple = /iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent);
  const mapsUrl = isApple
    ? `https://maps.apple.com/?daddr=${sp.lat},${sp.lng}`
    : `https://www.google.com/maps/dir/?api=1&destination=${sp.lat},${sp.lng}`;
  const parkLabel = sp.label ? itinEsc(trLabel(trustedStartLabel(t, sp.label))) : window.t('trail.itinParkFallback');
  itinAdd('park', -2, `${parkLabel} · <a href="${mapsUrl}" target="_blank" rel="noopener">${window.t('trail.openMaps')}</a>`);

  // 2. The start flag.
  itinAdd('flag', -1, window.t('trail.itinStart'));

  // 3. Curated rifugi and water points (they carry real names + km).
  (Array.isArray(t.rifugi) ? t.rifugi : []).forEach(r => {
    if(r.km > 0) itinAdd('hut', r.km, `${itinKmLabel(r.km)}, ${itinEsc(r.name)}`);
  });
  (Array.isArray(t.waterSources) ? t.waterSources : []).forEach(w => {
    if(w.km > 0) itinAdd('water', w.km, `${itinKmLabel(w.km)}, ${itinEsc(trLabel(trustedWaterLabel(t, w.label)))}`);
  });

  // 4. Decision points, where the route switches numbered trails.
  (Array.isArray(t.decisionPoints) ? t.decisionPoints : []).forEach(d => {
    itinAdd('switch', d.km, `${itinKmLabel(d.km)}, ${itinEsc(d.instruction)}`);
  });

  // 5. Closing step.
  itinAdd('paw', 1e9, isLoop
    ? window.t('trail.itinLoopEnd', {d: t.distance})
    : window.t('trail.itinEnd', {d: t.distance}));

  itinRender();

  // 6. Named amenities from the OSM datasets, joined to their km on the
  // route (only places within ~120 m of the actual path).
  const MAX_OFF_M = 120;
  function kmOnPath(lat, lng){
    if(!itin.cumKm) return null;
    let best = -1, bestD = Infinity;
    for(let i = 0; i < t.path.length; i++){
      const d = distMeters(t.path[i], [lat, lng]);
      if(d < bestD){ bestD = d; best = i; }
    }
    return bestD <= MAX_OFF_M ? { km: itin.cumKm[best], off: bestD } : null;
  }
  const seen = new Set(itin.items.map(i => i.html.toLowerCase()));

  window.onDetailPoisReady = (features) => {
    let added = 0;
    (features || []).forEach(f => {
      if(added >= 4) return;
      const p = f.properties || {};
      if(!p.name) return;
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const nameKey = p.name.toLowerCase();
      if([...seen].some(h => h.includes(nameKey))) return;
      const isHut = p.tourism === 'alpine_hut' || p.tourism === 'wilderness_hut' || p.amenity === 'shelter';
      itinAdd(isHut ? 'hut' : 'food', hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)}, ${itinEsc(p.name)}`);
      seen.add(nameKey);
      added++;
    });
    if(added) itinRender();
  };

  window.onDetailWaterReady = (features) => {
    // Only fill from OSM when the trail has no curated water list.
    if(Array.isArray(t.waterSources) && t.waterSources.length) return;
    let added = 0;
    (features || []).forEach(f => {
      if(added >= 2) return;
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const label = (f.properties && f.properties.name) ? f.properties.name : window.t('legend.water');
      itinAdd('water', hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)}, ${itinEsc(label)}`);
      added++;
    });
    if(added) itinRender();
  };

  // Viewpoints, picnic spots and named sights from the trail-corridor
  // amenity sweep, a couple of each, placed at their km on the route.
  window.onDetailPlacesReady = (features) => {
    const plainT = (key, fb) => {
      if(!window.t) return fb;
      const v = window.t(key);
      return v === key ? fb : v;
    };
    const CAP = { viewpoint: 2, picnic: 2, sight: 2 };
    const added = { viewpoint: 0, picnic: 0, sight: 0 };
    let any = 0;
    (features || []).forEach(f => {
      const p = f.properties || {};
      const kind = p.kind;
      if(!(kind in CAP) || added[kind] >= CAP[kind]) return;
      if(kind === 'sight' && !p.name) return;   // unnamed crosses are noise
      const [lng, lat] = f.geometry.coordinates;
      const hit = kmOnPath(lat, lng);
      if(!hit || hit.km <= 0.05) return;
      const label = p.name
        || (kind === 'viewpoint' ? plainT('poi.viewpoint', 'Viewpoint') : plainT('poi.picnic', 'Picnic spot'));
      const nameKey = label.toLowerCase();
      if([...seen].some(h => h.includes(nameKey))) return;
      const icon = kind === 'viewpoint' ? 'view' : (kind === 'picnic' ? 'picnic' : 'sight');
      itinAdd(icon, hit.km, `${itinKmLabel(Math.round(hit.km*10)/10)}, ${itinEsc(label)}`);
      seen.add(nameKey);
      added[kind]++;
      any++;
    });
    if(any) itinRender();
  };
}

const params = new URLSearchParams(window.location.search);
// A URL may name a trail by id or by its readable slug. The loader owns that
// mapping (it has the manifest) and the id stays the key everywhere below, so
// a link shared before slugs existed resolves to exactly the same trail.
const requestedTrailParam = params.get('id');
const trailId = (window.DoloPawsRegionalData && window.DoloPawsRegionalData.resolveTrailId)
  ? window.DoloPawsRegionalData.resolveTrailId(requestedTrailParam)
  : requestedTrailParam;
const trailReturnTarget = params.get('from');
const hikeDeepLinkRequested = params.get('hike') === '1';
// The day the reader was planning for when they left the list. Without it this
// page answered for today and quietly changed the question: a Saturday walk
// read against Thursday's heat. Bounded to the fortnight the homepage offers,
// so a stale or invented date falls back to today rather than to nothing.
const plannedWalkDate = (() => {
  const value = params.get('date') || '';
  if(!/^\d{4}-\d{2}-\d{2}$/.test(value)) return '';
  const today = new Date();
  const iso = offset => {
    const day = new Date(today.getFullYear(), today.getMonth(), today.getDate() + offset);
    return `${day.getFullYear()}-${String(day.getMonth() + 1).padStart(2, '0')}-${String(day.getDate()).padStart(2, '0')}`;
  };
  return value >= iso(0) && value <= iso(14) ? value : '';
})();
window.ORMAPlannedWalkDate = plannedWalkDate;
let pendingTrailAction = params.get('action');
let trailActionConsumed = false;

window.DoloPawsTrailAction = {
  request(action){
    const url = new URL(window.location.href);
    url.searchParams.set('action', action);
    window.history.replaceState(null, '', url.pathname.split('/').pop() + url.search + url.hash);
    pendingTrailAction = action;
    trailActionConsumed = false;
    if(window.DoloPawsGuestContext){
      window.DoloPawsGuestContext.captureCurrent(action, trailId);
    }
    if(window.DoloPawsAuthUI) window.DoloPawsAuthUI.openLogin();
  },
  consume(action){
    if(trailActionConsumed || pendingTrailAction !== action) return false;
    if(window.DoloPawsGuestContext){
      const context = window.DoloPawsGuestContext.consumeAction(
        window.localStorage,
        action,
        trailId
      );
      if(!context){
        trailActionConsumed = true;
        pendingTrailAction = null;
        const staleUrl = new URL(window.location.href);
        staleUrl.searchParams.delete('action');
        window.history.replaceState(
          null,
          '',
          staleUrl.pathname.split('/').pop() + staleUrl.search + staleUrl.hash
        );
        return false;
      }
    }
    trailActionConsumed = true;
    pendingTrailAction = null;
    const url = new URL(window.location.href);
    url.searchParams.delete('action');
    window.history.replaceState(null, '', url.pathname.split('/').pop() + url.search + url.hash);
    return true;
  },
  get pending(){ return pendingTrailAction; },
};

// Where "back" goes, restricted to this site's own list pages so a crafted
// address cannot bounce a reader somewhere else. The homepage was not on the
// list, which is why the main discovery surface -- the one that ranks trails
// for your dog -- was the one surface you could not get back to.
function safeTrailReturn(value){
  if(!value || /^(?:[a-z]+:|\/\/)/i.test(value)) return '';
  if(/^\/(?:\?[^#]*)?(?:#.*)?$/.test(value)) return value;
  if(/^\//.test(value)) return '';
  return /^(?:browse-trails|compare|saved|journal)\.html(?:\?[^#]*)?(?:#.*)?$/i.test(value) ? value : '';
}

let trailInitStarted = false;
function init(){
  if(trailInitStarted) return;
  trailInitStarted = true;
  if(window.DoloPawsRegions && typeof trails !== 'undefined') window.DoloPawsRegions.assign(trails);
  const trail = (typeof trails !== 'undefined') ? trails.find(x => x.id === trailId) : null;

  if(!trail){
    document.title = window.t('trail.notFound') + ' | ORMA';
    const wrap = document.querySelector('.td-wrap');
    if(wrap){
      wrap.innerHTML = `
        <div style="max-width:620px;margin:48px auto;text-align:center;">
          <h1>${window.t('trail.notFound')}</h1>
          <p style="margin:14px 0 24px;color:var(--ink-soft);">${window.t('trail.notFoundSub')}</p>
          <div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;">
            <a class="auth-submit" href="browse-trails.html" style="display:inline-block;width:auto;padding:11px 22px;text-decoration:none;">Browse all trails</a>
            <a class="fav-btn" href="/" style="display:inline-block;padding:11px 22px;text-decoration:none;">Go to homepage</a>
          </div>
        </div>`;
    }
    return;
  }

  // Cached real-world starts are applied before rendering. A cache miss starts
  // the lookup in the background so a slow third-party service cannot hold a
  // mobile navigation on the loading shell.
  improveLoopStart(trail, { deferOnMiss:true })
    .then(() => renderTrail(trail), () => renderTrail(trail));
}

function renderTrail(t){
  buildItinerary(t);
  const hasRoutePath = Array.isArray(t.path) && t.path.length > 1;
  const routeDataNotice = document.getElementById('routeDataNotice');
  if(routeDataNotice){
    routeDataNotice.hidden = hasRoutePath;
    routeDataNotice.textContent = window.t('trail.routeUnavailable');
  }
  const breadcrumb = document.getElementById('tdBreadcrumb');
  const returnTarget = safeTrailReturn(trailReturnTarget);
  if(breadcrumb && returnTarget){
    breadcrumb.href = returnTarget;
    breadcrumb.textContent = returnTarget.startsWith('saved.html') ? '← Back to saved trails'
      : returnTarget.startsWith('journal.html') ? '← Back to journal'
      : returnTarget.startsWith('compare.html') ? '← Back to comparison'
      : returnTarget.startsWith('/') ? '← Back to your matches'
      : '← Back to trail results';
  }
  const logWalkBtn = document.getElementById('logWalkBtn');
  if(logWalkBtn){
    const journalReturn = encodeURIComponent(`trail.html?id=${encodeURIComponent((window.DoloPawsRegionalData && window.DoloPawsRegionalData.slugFor ? window.DoloPawsRegionalData.slugFor(t.id) : (t.id)))}`);
    logWalkBtn.href = `journal.html?trail=${encodeURIComponent(t.id)}&from=${journalReturn}`;
  }
  // Do not reserve an empty elevation panel for routes without profile data.
  const elevationCard = document.getElementById('tdElevationPanel');
  const hasElevationProfile = Array.isArray(t.elevationProfile) && t.elevationProfile.length > 1;
  if(elevationCard){
    elevationCard.hidden = !hasElevationProfile;
    const experienceGrid = elevationCard.closest('.trail-experience-grid');
    if(experienceGrid) experienceGrid.classList.toggle('trail-experience-grid--itinerary-only', !hasElevationProfile);
  }
  document.title = `${t.name} | ORMA`;
  document.getElementById('pageTitle').textContent = `${t.name} | ORMA`;
  document.getElementById('trailName').textContent = t.name;
  // What the name means, under the name. 109 of the 162 trails are signed in
  // German, French or Italian; the name stays as the signpost has it, and this
  // says what it means for a reader who does not.
  const gloss = document.getElementById('trailNameGloss');
  if(gloss){
    gloss.textContent = t.nameGloss || '';
    gloss.hidden = !t.nameGloss;
  }
  document.getElementById('trailName').removeAttribute('aria-busy');
  // The homepage's Explore menu lists the last trails opened. Kept in this
  // browser only, never sent anywhere, and capped so it stays a shortlist.
  try{
    const recentKey = 'orma-recent-trails-v1';
    const recent = JSON.parse(localStorage.getItem(recentKey) || '[]');
    const kept = (Array.isArray(recent) ? recent : []).filter(item => item && item.id !== t.id);
    kept.unshift({ id:t.id, name:t.name, area:t.valley || t.area || '', at:Date.now() });
    localStorage.setItem(recentKey, JSON.stringify(kept.slice(0, 8)));
  }catch(error){ /* Storage can be unavailable in private browsing. */ }
  // Photo-backed hero (per prototype): trail photo under a dark gradient.
  // Trails without an image keep the flat dark hero.
  if(t.imageIcon){
    const heroPhoto = document.getElementById('tdHeroPhoto');
    const heroVeil = document.getElementById('tdHeroVeil');
    if(heroPhoto && heroVeil){
      const responsivePhotoByTrailId = {
        'lago-braies':'images/lago-di-braies.webp',
        'lago-carezza':'images/lago-di-carezza.webp',
        'osm-16322228':'images/boucle-du-marais-des-chassettes.webp',
        'osm-10116380':'images/itineraire-decouverte-de-la-nature.webp',
      };
      const responsiveSource = responsivePhotoByTrailId[t.id] || t.imageIcon;
      const responsiveWidths = {
        'images/lago-di-braies.webp':[480,900],
        'images/lago-di-carezza.webp':[480,900],
        'images/boucle-du-marais-des-chassettes.webp':[480,960,1280],
        'images/itineraire-decouverte-de-la-nature.webp':[480,960,1280],
      }[responsiveSource];
      if(responsiveWidths){
        const stem = responsiveSource.replace(/\.webp$/, '');
        heroPhoto.src = `${stem}.jpg`;
        heroPhoto.srcset = responsiveWidths.map((width, index) =>
          `${width === 900 ? responsiveSource : `${stem}-${width}.webp`} ${width}w`
        ).join(', ');
        heroPhoto.sizes = '(max-width: 700px) 100vw, 1200px';
      } else if(/^https:\/\/commons\.wikimedia\.org\/wiki\/Special:Redirect\/file\//i.test(t.imageIcon)){
        const separator = t.imageIcon.includes('?') ? '&' : '?';
        heroPhoto.src = `${t.imageIcon}${separator}width=960`;
        heroPhoto.srcset = [480, 960, 1600].map(width =>
          `${t.imageIcon}${separator}width=${width} ${width}w`
        ).join(', ');
        heroPhoto.sizes = '(max-width: 700px) 100vw, 1200px';
      } else {
        heroPhoto.src = t.imageIcon;
      }
      heroPhoto.decoding = 'async';
      heroPhoto.fetchPriority = 'high';
      heroPhoto.alt = t.imageAlt || `${t.name} trail photograph`;
      heroPhoto.hidden = false;
      heroVeil.hidden = false;
      const creditEl = document.getElementById('tdHeroCredit');
      const creditText = document.getElementById('tdHeroCreditText');
      const credit = window.DoloPawsPhotoProvenance
        ? window.DoloPawsPhotoProvenance.heroCredit(t)
        : null;
      if(creditEl && creditText && credit){
        creditEl.open=false;
        creditText.replaceChildren();
        // Creative Commons requires the creator and the licence, not just a link to
        // the source. The static generator already renders both; a trail served
        // only by this dynamic page must not be credited more thinly.
        if(credit.url){
          const link=document.createElement('a');
          link.href=credit.url;link.target='_blank';link.rel='noopener nofollow';link.textContent=credit.label;
          creditText.appendChild(link);
        }else creditText.appendChild(document.createTextNode(credit.label));
        if(t.imageCreator){
          creditText.appendChild(document.createTextNode(` by ${t.imageCreator}`));
        }
        if(t.imageLicence){
          creditText.appendChild(document.createTextNode(' · '));
          if(t.imageLicenceUrl){
            const licence=document.createElement('a');
            licence.href=t.imageLicenceUrl;licence.rel='license noopener';licence.target='_blank';
            licence.textContent=t.imageLicence;
            creditText.appendChild(licence);
          }else creditText.appendChild(document.createTextNode(t.imageLicence));
        }
        creditEl.hidden=false;
      }
    }
  }
  document.getElementById('trailMeta').textContent =
    `${t.area} · ${t.distance} km · ${t.elevation} m gain · ${t.hours} h · ${t.terrainType}`;
  document.getElementById('trailBadges').innerHTML =
    trailProductBadge(t.safetyLevel, trailSafetyLabel(t)) +
    (t.paid ? trailProductBadge('neutral', window.t('card.paid')) : '');
  const rawDescription = trField(t, 'desc');
  const descriptionSentences = String(rawDescription).match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [rawDescription];
  let conciseDescription = '';
  for (const sentence of descriptionSentences) {
    const candidate = `${conciseDescription}${conciseDescription ? ' ' : ''}${sentence.trim()}`;
    if (candidate.length > 330) break;
    conciseDescription = candidate;
    if (conciseDescription.length > 190) break;
  }
  if (!conciseDescription) conciseDescription = String(rawDescription).slice(0, 327).trimEnd() + (String(rawDescription).length > 327 ? '…' : '');
  document.getElementById('trailDesc').textContent = conciseDescription;
  document.getElementById('trailTips').textContent = t.tips ? window.t('trail.tip', {tip: trField(t, 'tips')}) : '';

  // Community v0: "N dogs hiked this trail this week", anonymous counts
  // from hike-mode starts. Deliberately renders NOTHING at zero: an empty
  // trail should look quiet, not dead.
  function showWeeklyHikes(){
    if (!window.DoloPawsCommunity) return;
    window.DoloPawsCommunity.getWeeklyHikeCount(t.id).then(n => {
      if (!n || n < 1) return;
      const chip = document.getElementById('dogsChip');
      if (!chip) return;
      const weeklyLabel = n === 1 ? window.t('trail.dogsWeek1') : window.t('trail.dogsWeek', {n});
      chip.innerHTML = window.DoloPawsIcons
        ? window.DoloPawsIcons.renderIconSvg('dog', { mode:'inline', color:'currentColor', size:14 }) + `<span>${itinEsc(weeklyLabel)}</span>`
        : itinEsc(weeklyLabel);
      chip.classList.add('dp-inline-status');
      chip.hidden = false;
    });
  }
  if (window.DoloPawsCommunity) showWeeklyHikes();
  else window.addEventListener('dolopaws-auth-ready', showWeeklyHikes, { once: true });

  // Provenance banner: imported (OSM) vs verified (curated) trails.
  (function () {
    const descEl = document.getElementById('trailDesc');
    if (!descEl || document.getElementById('osmProvenance')) return;
    const box = document.createElement('div');
    box.id = 'osmProvenance';
    box.className = 'trail-provenance';
    const trust = window.DoloPawsTrailTrust;
    const provStyle = trust && trust.tierBadgeStyle ? trust.tierBadgeStyle(t) : (t.curated === false ? 'imported' : 'verified');
    const provenanceIcon = window.DoloPawsIcons
      ? window.DoloPawsIcons.renderIconSvg(provStyle, { mode:'inline', color:'currentColor', size:16 })
      : '';
    box.style.cssText = 'margin:10px 0 14px;padding:10px 14px;border-left:4px solid #2E4034;background:#eef3ef;border-radius:6px;font-size:13px;line-height:1.5;';
    box.innerHTML = provenanceIcon + '<strong>Trail planning information.</strong> Based on mapped route data and available ORMA sources. Conditions can change, so check locally before setting out.';
    descEl.parentNode.insertBefore(box, descEl);

    // Trail hazards, surfaceHazards used to feed only the match scoring;
    // surface them to the reader too, right under the provenance banner.
    const surfaceVerified = !trust || !trust.categoryVerified || trust.categoryVerified(t, 'surfaceHazards');
    if (surfaceVerified && Array.isArray(t.surfaceHazards) && t.surfaceHazards.length && !document.getElementById('trailHazards')) {
      const hz = document.createElement('div');
      hz.id = 'trailHazards';
      hz.style.cssText = 'margin:0 0 14px;padding:10px 14px;border-left:4px solid #9C3A25;background:#faeeea;border-radius:6px;font-size:13px;line-height:1.5;';
      const warningIcon = window.DoloPawsIcons ? window.DoloPawsIcons.renderIconSvg('warning', { mode:'inline', color:'currentColor', size:16 }) : '';
      hz.innerHTML = '<strong class="dp-inline-status">' + warningIcon + '<span>' + itinEsc(window.t('trail.hazardsTitle') || 'Trail hazards') + '</span></strong><ul style="margin:6px 0 0 18px;padding:0;">'
        + t.surfaceHazards.map(h => '<li>' + String(h).replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])) + '</li>').join('')
        + '</ul>';
      descEl.parentNode.insertBefore(hz, descEl);
    }
  })();

  // Quick facts, ascent/descent, highest/lowest point.
  // Note: summing the sparse elevationProfile points (usually just 5-6
  // samples) systematically UNDERSTATES real ascent, since it misses the
  // smaller ups and downs between samples, confirmed by comparing against
  // Tre Cime's already-researched 430m gain figure, which came out much
  // higher than summing its profile points did. Using the existing
  // `elevation` field for ascent is more trustworthy, and since every trail
  // here is a loop (same start/end point), descent is the same figure, // net elevation change over a full loop is ~0 by definition.
  // Facts live inside the dark hero now, one place, no duplicates.
  (function(){
    const factsEl = document.getElementById('trailFacts');
    if(!factsEl) return;
    const facts = [
      [`${t.distance} km`, window.t('trail.fact.distance')],
      [`${t.elevation} m`, window.t('trail.fact.ascent')],
      [`${t.hours} h`, window.t('trail.fact.duration')],
    ].filter(([val]) => !/^null|^undefined/.test(val)); // hide facts the data honestly lacks
    if(Array.isArray(t.elevationProfile) && t.elevationProfile.length > 1){
      facts.splice(2, 0, [`${Math.max(...t.elevationProfile.map(p => p.elev))} m`, window.t('trail.fact.high')]);
    }
    // Difficulty cell, mirrors the homepage's derivation from real fields so
    // the hero stat strip matches the design's five-cell layout.
    (function(){
      const asc = Number(t.elevation) || 0;
      const rank = Number(t.terrainRank) || 0;
      const km = Number(t.distance) || 0;
      const diff = (asc >= 400 || (rank >= 2 && asc >= 250)) ? 'Hard'
        : (asc >= 180 || km >= 6 || rank >= 2) ? 'Moderate' : 'Easy';
      facts.push([diff, window.t('trail.fact.difficulty')]);
    })();
    // The design's stat strip leads with a Match cell ("94% · Match · Rufus").
    // It's rendered here so it lives inside the same strip; paintMatch()
    // below fills it with the real score, or an honest create-profile
    // invitation for guests.
    // A route too long for a day gets an explicit label, so a visitor who lands
    // here from a search or link knows it is a multi-day itinerary, not a walk.
    const multiDayCell = (window.DoloPawsTrailTrust && window.DoloPawsTrailTrust.isMultiDay(t))
      ? '<span class="f f-multiday"><b>Multi-day</b><span>route</span></span>' : '';
    factsEl.innerHTML =
      '<span class="f match" id="statMatch" hidden><a class="td2-match-link" id="statMatchLink" href="how-scoring-works.html"><b id="statMatchVal"></b><span id="statMatchSub"></span></a></span>'
      + multiDayCell
      + facts.map(([val, label]) =>
        `<span class="f"><b>${val}</b><span>${label}</span></span>`).join('');
    const statMatch = document.getElementById('statMatch');
    const statMatchLink = document.getElementById('statMatchLink');
    const statMatchVal = document.getElementById('statMatchVal');
    const statMatchSub = document.getElementById('statMatchSub');

    // Personal match, needs a logged-in profile. Guests see the facts
    // plus an honest invitation: the score exists, it just isn't theirs yet.
    function paintMatchTeaser(){
      applyDetailRouteColor(detailRouteColorForScore(guestMatchScore(t)));
      const actions = document.querySelector('.td-actions');
      if(actions) actions.classList.add('guest-actions');
      if(statMatch){
        statMatchVal.textContent = '?';
        statMatchSub.textContent = window.t('trail.matchCellTeaser');
        statMatchLink.href = '/?profile=1';
        statMatchLink.setAttribute('aria-label', window.t('trail.matchCellTeaser'));
        statMatch.hidden = false;
      }
      // Legacy slot retained for the main personalised match summary.
      const el = document.getElementById('trailMatch');
      if(el){ el.innerHTML = `<a href="/?profile=1">${window.t('trail.matchTeaser')}</a>`; el.hidden = false; }
    }
    function paintMatch(){
      if(typeof recommendTrail !== 'function') return;
      if(!window.DoloPawsAuth || !window.DoloPawsAuth.currentUser){
        paintMatchTeaser();
        return;
      }
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if(!profile){ paintMatchTeaser(); return; }
        const recommendation = recommendTrail(t, effectiveOverrides(profile, null),
          window.ORMAScoringConditions && window.ORMAScoringConditions.forTrail(t));
        const n = recommendation.score;
        applyDetailRouteColor(detailRouteColorForScore(n));
        const actions = document.querySelector('.td-actions');
        if(actions) actions.classList.remove('guest-actions');
        const name = profile.name || window.t('trail.yourDog');
        if(statMatch){
          statMatchVal.innerHTML = (t.curated === false ? '≈' : '') + n + '<span class="pct">%</span>';
          statMatchSub.textContent = 'Match · ' + name;
          statMatchLink.href = 'how-scoring-works.html';
          statMatchLink.setAttribute('aria-label', `Learn how ORMA calculates the ${n}% trail match for ${name}`);
          statMatch.dataset.scoringVersion = recommendation.scoringVersion;
          statMatch.dataset.recommendationCategory = recommendation.category;
          statMatch.dataset.recommendationConfidence = recommendation.confidence;
          statMatch.hidden = false;
        }
        const el = document.getElementById('trailMatch');
        if(el){
          el.textContent = (t.curated === false ? '≈' : '') + n + '% ' +
            window.t('trail.matchFor', {name});
          el.dataset.scoringVersion = recommendation.scoringVersion;
          el.dataset.recommendationCategory = recommendation.category;
          el.dataset.recommendationConfidence = recommendation.confidence;
          el.hidden = false;
        }
      });
    }
    if(window.DoloPawsAuth) paintMatch();
    else window.addEventListener('dolopaws-auth-ready', paintMatch, { once: true });
    // Repaint when auth state resolves or changes, so a logged-in visitor
    // never keeps the guest teaser (and vice versa after logout).
    window.addEventListener('dolopaws-auth-changed', paintMatch);
  })();

  paintOnRouteCard(t);

  // "Good to know", curated insights (history, geology, best practice)
  // with cited sources, for trails that have them in trails-data.js.
  if (Array.isArray(t.insights) && t.insights.length){
    const lang = (window.DoloPawsI18n && window.DoloPawsI18n.lang) || 'en';
    const box = document.createElement('div');
    box.style.cssText = 'margin-top:20px;';
    box.innerHTML = `<h2 style="font-size:18px;margin-bottom:10px;">${window.t('trail.insightsTitle')}</h2>` +
      t.insights.map(i => `
        <div style="background:var(--card);border:1px solid var(--paper-line);border-radius:12px;padding:12px 16px;margin-bottom:10px;font-size:13.5px;color:var(--ink);line-height:1.55;">
          ${(lang === 'it' && i.it) ? i.it : i.en}
          <div style="font-size:11.5px;color:var(--ink-soft);margin-top:6px;">${window.t('trail.source')}: ${i.url ? `<a href="${i.url}" target="_blank" rel="noopener">${i.source}</a>` : i.source}</div>
        </div>`).join('');
    const gtk = document.getElementById('goodToKnowBox');
    if (gtk){
      box.style.cssText = '';
      box.querySelector('h2').remove(); // card already has the heading
      gtk.appendChild(box);
    } else {
      const detail = document.getElementById('trailDetailContent');
      if (detail) detail.appendChild(box);
    }
  } else {
    // No hand-researched notes yet, fill the card with honest facts
    // derived from the route data itself, clearly labelled as such.
    const gtk = document.getElementById('goodToKnowBox');
    if (gtk){
      const facts = [];
      if (Array.isArray(t.elevationProfile) && t.elevationProfile.length){
        facts.push(window.t('gtk.autoAltitude', {m: Math.max(...t.elevationProfile.map(p => p.elev))}));
      }
      if (t.terrainType) facts.push(window.t('gtk.autoTerrain', {surface: t.terrainType}));
      const isLoopG = Array.isArray(t.path) && t.path.length > 1
        && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
      facts.push(isLoopG ? window.t('gtk.autoLoop', {d: t.distance}) : window.t('gtk.autoPointToPoint', {d: t.distance}));
      gtk.innerHTML = facts.map(f =>
        `<div style="border:1px solid var(--paper-line);border-radius:12px;padding:10px 14px;margin-bottom:8px;font-size:13px;color:var(--ink);line-height:1.55;">${f}</div>`).join('')
        + `<p style="font-size:11px;color:var(--ink-soft);margin:6px 0 0;">${window.t('gtk.autoNote')}</p>`;
    }
  }

  // Build turn-by-turn directions for trails stitched from more than one
  // numbered route, or a simpler start-only note for single-path loops
  // (a lake loop doesn't need "switch trails" instructions, but it still
  // deserves a clear "start here" pointer).
  if(Array.isArray(t.path) && ((Array.isArray(t.decisionPoints) && t.decisionPoints.length > 0) || t.startPoint)){
    const totalKm = t.distance;
    const firstStep = t.startPoint
      ? window.t('trail.dirStart', {label: trLabel(trustedStartLabel(t, t.startPoint.label))})
      : window.t('trail.dirStartAt', {name: (t.rifugi || []).find(r => r.km === 0)?.name || t.area});
    const steps = [firstStep];

    if(Array.isArray(t.decisionPoints) && t.decisionPoints.length > 0){
      // Merge rifugi and decision points that share a km value into one step,
      // rather than listing "pass X" and "switch trails at X" separately when
      // they're literally the same spot.
      const byKm = new Map();
      (t.rifugi || []).filter(r => r.km > 0).forEach(r => {
        byKm.set(r.km, [...(byKm.get(r.km) || []), { text: window.t('trail.dirPass', {name: r.name}), name: r.name }]);
      });
      t.decisionPoints.forEach(d => {
        const existing = byKm.get(d.km) || [];
        const instructionText = d.instruction.charAt(0).toLowerCase() + d.instruction.slice(1);
        // If a rifugio at this exact km is already named inside the decision
        // instruction, drop the separate "pass X" so the name isn't repeated.
        const deduped = existing.filter(e => !instructionText.toLowerCase().includes(e.name.toLowerCase()));
        byKm.set(d.km, [...deduped, { text: instructionText }]);
      });
      const events = [...byKm.entries()].sort((a, b) => a[0] - b[0]);
      events.forEach(([km, items]) => steps.push(`Km ${km}: ${items.map(i => i.text).join(window.t('trail.dirThen'))}.`));
    }

    steps.push(window.t('trail.dirEnd', {n: totalKm}));

    document.getElementById('trailDirections').innerHTML = steps.map(s => `<li>${s}</li>`).join('');
    document.getElementById('directionsWrap').hidden = false;
  }

  // Hike recording must not wait for the remote map engine or map tiles. QR
  // deep links initialise the GPS/readiness flow immediately; the map attaches
  // later when its normal lazy-load completes.
  const detailMapTarget = document.getElementById('trailMapBox') || document.getElementById('trailDetailMap');
  const hikeModeContainer = document.getElementById('trailDetailMap');
  const hikeModeController = typeof initHikeMode === 'function'
    ? initHikeMode(null, t, { container:hikeModeContainer })
    : null;

  // The detail map is expensive and sits below the trail summary. Load its
  // engine only as the map approaches the viewport (or a control is focused).
  const initDetailMap = () => {
  if(typeof maplibregl !== 'undefined' && typeof t.lat === 'number' && typeof t.lng === 'number'){
    const detailMapOptions = {
      container: 'trailDetailMap',
      style: 'https://tiles.openfreemap.org/styles/liberty',
      center: [t.lng, t.lat],
      zoom: 14,
      pitch: 0, // clean, flat, label-first by default, 3D is opt-in via the toggle
      attributionControl: { compact: true },
    };
    const map = new maplibregl.Map(window.DoloPawsMapRuntime
      ? window.DoloPawsMapRuntime.mapOptions(detailMapOptions) : detailMapOptions);
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
    window._dolopawsTrailMap = map; // debug/test handle
    // trail-hazards.js is injected separately and has no way to reach either the
    // map or the route it draws. Publishing both, with a ready signal for
    // whoever arrives first, is what lets a reader place a hazard on the path
    // rather than describing where it was in prose.
    window.DoloPawsTrailMapContext = { map, trail: t };
    window.dispatchEvent(new CustomEvent('dolopaws-trail-map-ready'));
    initNearestTrailDirections(map, t);

    // Fullscreen map, manual ⤢ toggle, and automatic during hike mode.
    const mapBox = document.getElementById('trailMapBox');
    const expandBtn = document.getElementById('mapExpandBtn');
    const elevationPanel = document.getElementById('tdElevationPanel');
    const elevationHome = elevationPanel && elevationPanel.parentNode;
    function setMapFS(on){
      if(!mapBox) return;
      mapBox.classList.toggle('map-fs', on);
      document.body.classList.toggle('map-fs-open', on);
      if(elevationPanel && !elevationPanel.hidden){
        if(on) mapBox.appendChild(elevationPanel);
        else if(elevationHome) elevationHome.appendChild(elevationPanel);
      }
      if(expandBtn) expandBtn.innerHTML = on
        ? '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg> <span>Close map</span>'
        : '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></svg> <span>Expand map</span>';
      if(expandBtn) expandBtn.setAttribute('aria-label', on ? 'Close map' : 'Expand map');
      if(expandBtn) expandBtn.setAttribute('aria-expanded', String(on));
      setTimeout(() => map.resize(), 60);
    }
    window.DoloPawsMapFS = { enter: () => setMapFS(true), exit: () => setMapFS(false) };
    if(expandBtn) expandBtn.addEventListener('click', () => setMapFS(!mapBox.classList.contains('map-fs')));
    document.addEventListener('keydown', event => {
      if(event.key === 'Escape' && mapBox && mapBox.classList.contains('map-fs')) setMapFS(false);
    });
    // Live blue-dot location control, tap to see yourself on the map,
    // with heading arrow and follow-me tracking (Google Maps-style).
    map.addControl(new maplibregl.GeolocateControl({
      positionOptions: { enableHighAccuracy: true },
      trackUserLocation: true,
      showUserHeading: true,
      fitBoundsOptions: { maxZoom: 15.5 },
    }), 'top-right');

    // ---- Terrain / Satellite layer switch --------------------------------
    // Bound outside the 'load' handler so the buttons respond as soon as the
    // style is parsed, even while tiles are still streaming in on a slow
    // connection. The imagery slots in below the basemap's text labels, so
    // the route line, POIs and place names stay readable on top of it.
    const layerSwitch = document.getElementById('tdLayerSwitch');
    if (layerSwitch){
      const ensureSatelliteLayer = () => {
        if (map.getLayer('satellite-layer')) return true;
        if (!map.isStyleLoaded()) return false;
        map.addSource('satellite', {
          type: 'raster',
          tiles: ['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],
          tileSize: 256,
          maxzoom: 19,
          attribution: 'Imagery © Esri',
        });
        const firstSymbol = map.getStyle().layers.find(l => l.type === 'symbol');
        map.addLayer({
          id: 'satellite-layer',
          type: 'raster',
          source: 'satellite',
          layout: { visibility: 'none' },
          paint: { 'raster-resampling': 'linear', 'raster-fade-duration': 100 },
        }, firstSymbol && firstSymbol.id);
        return true;
      };
      layerSwitch.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-maplayer]');
        if (!btn || !ensureSatelliteLayer()) return;
        const sat = btn.getAttribute('data-maplayer') === 'satellite';
        map.setLayoutProperty('satellite-layer', 'visibility', sat ? 'visible' : 'none');
        // The vector style's building fills sit above the raster and would
        // paint every roof grey over the photo imagery, hide them on
        // satellite.
        map.getStyle().layers.forEach(layer => {
          if(layer['source-layer'] === 'building' || /building/i.test(layer.id)){
            try { map.setLayoutProperty(layer.id, 'visibility', sat ? 'none' : 'visible'); } catch(err){}
          }
        });
        // Base buttons only, the 3D toggle keeps its own pressed state.
        layerSwitch.querySelectorAll('[data-maplayer]').forEach(b => {
          const on = b === btn;
          b.classList.toggle('on', on);
          b.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
      });
    }

    map.on('load', async () => {
      if(hikeModeController && hikeModeController.attachMap) hikeModeController.attachMap(map);
      if(window.DoloPawsMapRuntime) window.DoloPawsMapRuntime.enhance(map);
      const attribution = document.querySelector('#trailDetailMap .maplibregl-ctrl-attrib');
      if(attribution){
        attribution.classList.add('maplibregl-compact');
        attribution.classList.remove('maplibregl-compact-show');
        const toggle = attribution.querySelector('.maplibregl-ctrl-attrib-button');
        if(toggle) toggle.setAttribute('aria-expanded', 'false');
      }
      let liftsVisible = false;        // Lifts are optional planning context
      // Everyday trail context is visible immediately; only optional planning
      // overlays remain in Layers.
      // Water and huts are what a dog walker needs without asking; food and
      // sights are planning extras and stay behind Layers so the route, not a
      // field of identical pins, is what you see first. Mirrors
      // DEFAULT_VISIBLE_GROUPS in detail-pois.js.
      const poiStates = { fountains: true, huts: true, food: false, places: false };
      const amenityMarkers = [];       // { marker, group } for curated fallbacks
      if(window.DoloPawsIcons) await window.DoloPawsIcons.registerMapImages(map);
      const setLayerChipLabel = (button, iconKey, label) => {
        if(!button) return;
        button.innerHTML = window.DoloPawsIcons
          ? window.DoloPawsIcons.chipHtml(iconKey, label)
          : label;
      };
      setLayerChipLabel(document.getElementById('routesToggle'), 'routes', 'Trail routes');
      setLayerChipLabel(document.getElementById('liftsToggle'), 'lifts', 'Lift stations');
      setLayerChipLabel(document.getElementById('nearbyToggle'), 'nearby', 'Nearby trails');
      addTerrainSource(map);
      increaseLabelDensity(map);
      addTerrainToggle(map, 'trailDetailMap', 1.5, 45,
        document.querySelector('#tdLayerSwitch [data-map3d]'));
      const loadSecondaryPois = () => {
        renderAllLifts(map, { visible: liftsVisible });
        if (typeof initDetailPois === 'function') initDetailPois(map, t);
      };
      if(window.DoloPawsMapRuntime) window.DoloPawsMapRuntime.onIdle(loadSecondaryPois, 1400);
      else setTimeout(loadSecondaryPois, 900);

      // ---- Layers dropdown -------------------------------------------------
      // Match the main map: one compact control with independent route and
      // POI categories, instead of a tall stack of unrelated buttons.
      const layersBtn = document.getElementById('detailLayersBtn');
      const layersPanel = document.getElementById('detailLayersPanel');
      if(layersBtn && layersPanel){
        layersBtn.addEventListener('click', event => {
          event.stopPropagation();
          const open = layersPanel.style.display === 'flex';
          layersPanel.style.display = open ? 'none' : 'flex';
          layersBtn.textContent = open ? 'Layers' : 'Close ✕';
          layersBtn.setAttribute('aria-expanded', String(!open));
        });
        layersPanel.addEventListener('click', event => event.stopPropagation());
        document.addEventListener('click', () => {
          layersPanel.style.display = 'none';
          layersBtn.textContent = 'Layers';
          layersBtn.setAttribute('aria-expanded', 'false');
        });
      }

      const POI_SOURCES = {
        fountains: ['detail-water'],
        huts: ['detail-huts'],
        food: ['detail-bars'],
        places: ['detail-places'],
      };
      const POI_SUFFIXES = ['-layer', '-layer-lowzoom', '-cluster', '-cluster-count'];
      function applyPoiVisibility(group){
        const visible = poiStates[group];
        (POI_SOURCES[group] || []).forEach(source => POI_SUFFIXES.forEach(suffix => {
          const id = source + suffix;
          if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visible ? 'visible' : 'none');
        }));
        amenityMarkers.filter(item => item.group === group).forEach(item => {
          item.marker.getElement().style.display = visible ? '' : 'none';
        });
      }
      // Water / huts / food / places each get their own chip so nothing that
      // used to be visible is merely gone, it moved behind a control.
      const POI_CHIPS = [
        { id:'fountainsToggle', group:'fountains', icon:'water', label:'Drinking water' },
        { id:'hutsToggle', group:'huts', icon:'hut', label:'Huts & shelters' },
        { id:'foodToggle', group:'food', icon:'food', label:'Food & drink' },
        { id:'placesToggle', group:'places', icon:'sight', label:'Points of interest' },
      ];
      POI_CHIPS.forEach(chip => {
        const button = document.getElementById(chip.id);
        if(!button) return;
        setLayerChipLabel(button, chip.icon, chip.label);
        const on = !!poiStates[chip.group];
        button.classList.toggle('on', on);
        button.setAttribute('aria-pressed', String(on));
        button.addEventListener('click', () => {
          poiStates[chip.group] = !poiStates[chip.group];
          button.classList.toggle('on', poiStates[chip.group]);
          button.setAttribute('aria-pressed', String(poiStates[chip.group]));
          applyPoiVisibility(chip.group);
        });
      });

      // No veterinary layer. It showed whatever OpenStreetMap happened to have
      // mapped within a wide radius, and across this catalogue that is thin
      // enough to mislead: an empty map reads as "no vet nearby" rather than
      // "nobody has mapped one", which is the wrong thing to tell an owner.
      // Removed from the homepage and from here on 2026-10-15, and
      // veterinary-care.js went with it.

      // detail-pois.js adds its layers asynchronously (after a fetch), so
      // reapply whenever a POI source finishes loading.
      map.on('sourcedata', (e) => {
        if(!e.sourceId || !e.isSourceLoaded) return;
        Object.keys(POI_SOURCES).forEach(group => {
          if(POI_SOURCES[group].includes(e.sourceId)) applyPoiVisibility(group);
        });
      });

      // ---- Lifts toggle -------------------------------------------------
      // Lift lines and stations start hidden, then remain available as an
      // explicit planning layer. The state also applies if the deferred lift
      // data finishes loading after the customer has pressed the control.
      function applyLiftVisibility(){
        const visibility = liftsVisible ? 'visible' : 'none';
        ['detail-gondolas-line', 'detail-gondola-stations-layer'].forEach(id => {
          if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visibility);
        });
      }
      const liftsToggleBtn = document.getElementById('liftsToggle');
      if(liftsToggleBtn){
        liftsToggleBtn.addEventListener('click', () => {
          liftsVisible = !liftsVisible;
          liftsToggleBtn.classList.toggle('on', liftsVisible);
          liftsToggleBtn.setAttribute('aria-pressed', liftsVisible ? 'true' : 'false');
          applyLiftVisibility();
        });
      }


      // Waymarked Trails' own public hiking overlay, same underlying OSM
      // data as our base map, but with their dedicated trail-route styling
      // (numbered routes, waymarking) that a general basemap doesn't draw.
      //
      // Drawn in Waymarked's own colours by map-style.js. The previous
      // treatment desaturated it by -0.90 and pushed contrast, which turned
      // their red route lines and route-number shields into unreadable grey
      // smudges, the "illegible signs" complaint. Inserting before the first
      // label layer keeps it above roads and fills but below every place name.
      const firstLabelId = window.ORMAMapStyle.firstLabelLayerId(map);
      window.ORMAMapStyle.quietBasemap(map);
      window.ORMAMapStyle.addWaymarkedHiking(map, { beforeId: firstLabelId });
      if (typeof addBaseHillshade === 'function') addBaseHillshade(map, 'waymarked-hiking-layer');
      // Elevation contours from the same DEM -- the detail a street basemap
      // lacks. Lazy-loaded and fully guarded: if the plugin fails, the map is
      // unchanged.
      if (window.DoloPawsMapRuntime && window.DoloPawsMapRuntime.loadContour) {
        window.DoloPawsMapRuntime.loadContour()
          .then(() => window.ORMAMapStyle.addContours(map))
          .catch(() => {});
      }
      const routesToggleBtn = document.getElementById('routesToggle');
      if (routesToggleBtn){
        routesToggleBtn.classList.add('on');
        routesToggleBtn.setAttribute('aria-pressed', 'true');
        routesToggleBtn.addEventListener('click', () => {
          const showing = routesToggleBtn.classList.toggle('on');
          routesToggleBtn.setAttribute('aria-pressed', showing ? 'true' : 'false');
          if (map.getLayer('waymarked-hiking-layer')) {
            map.setLayoutProperty('waymarked-hiking-layer', 'visibility', showing ? 'visible' : 'none');
          }
        });
      }

      // ---- Other trails' routes, browse and switch without going back ----
      // Every other trail with a real GPS route renders as a secondary line;
      // clicking one pops up its name and a link straight to its page. Added
      // BEFORE the main route's layers so the current trail always draws on
      // top of its neighbours.
      // Re-runnable, because a trail page now paints from its own detail file
      // and the rest of the region arrives after the paint: at first render
      // there are no neighbours to draw. Every layer here is inserted with an
      // explicit beforeId, so adding them later still keeps the current trail
      // drawn on top of its neighbours.
      let nearbyLayersAdded = false;
      function renderNearbyTrailLayers(){
        if(nearbyLayersAdded) return;
        // No isStyleLoaded() gate here. It reports false transiently while
        // tiles and sources are still arriving -- which is not the same as
        // being unable to add a layer -- and gating on it skipped the inline
        // call entirely on the live site, then deferred to map.once('load'),
        // which never fires again once load has passed. The toggle stayed
        // hidden with five neighbours available.
        //
        // This call site is the one the original code ran in, so it adds
        // directly. A call driven by a late region may genuinely arrive before
        // the style can take a layer, so that failure is caught and retried on
        // the next styledata rather than predicted.
        const nearbyTrails = nearbyTrailCandidates(t, typeof trails !== 'undefined' ? trails : []);
        const otherTrails = nearbyTrails.map(item => item.trail);
        const nearbyToggleBtn = document.getElementById('nearbyToggle');
        if(nearbyToggleBtn){
          nearbyToggleBtn.hidden = nearbyTrails.length === 0;
          if(nearbyTrails.length){
            setLayerChipLabel(nearbyToggleBtn, 'nearby', `Nearby trails (${nearbyTrails.length})`);
          }
        }
        if(otherTrails.length){
          // Set before the adds, so a retry cannot double-add; cleared again if
          // the style refuses them.
          nearbyLayersAdded = true;
          try {
          map.addSource('other-trails', {
            type: 'geojson',
            data: {
              type: 'FeatureCollection',
              features: otherTrails.map(x => ({
                type: 'Feature',
                properties: { id: x.id, name: x.name, safetyLevel: x.safetyLevel, distance: x.distance },
                geometry: { type: 'LineString', coordinates: x.path.map(([lat, lng]) => [lng, lat]) },
              })),
            },
          });
          map.addLayer({
            id: 'other-trails-line',
            type: 'line',
            source: 'other-trails',
            minzoom: 9,
            layout: { visibility: 'none', 'line-join': 'round', 'line-cap': 'round' },
            paint: {
              'line-color': '#858D88',
              'line-width': 3.5,
              'line-opacity': 0.52,
              'line-dasharray': [1.5, 1.25],
            },
          }, 'waymarked-hiking-layer');
          // Wide invisible twin so the thin neighbour lines are easy to hit.
          map.addLayer({
            id: 'other-trails-hit',
            type: 'line',
            source: 'other-trails',
            minzoom: 9,
            layout: { visibility: 'none', 'line-join': 'round', 'line-cap': 'round' },
            paint: { 'line-color': '#000', 'line-width': 16, 'line-opacity': 0.01 },
          }, 'waymarked-hiking-layer');
          map.addSource('nearby-trail-points', {
            type: 'geojson',
            data: {
              type: 'FeatureCollection',
              features: nearbyTrails.map(item => ({
                type: 'Feature',
                properties: {
                  id: item.trail.id,
                  name: item.trail.name,
                  safetyLevel: item.trail.safetyLevel,
                  distance: item.trail.distance,
                  awayKm: Math.round(item.distanceKm * 10) / 10,
                },
                geometry: { type: 'Point', coordinates: [item.mapPoint[1], item.mapPoint[0]] },
              })),
            },
          });
          map.addLayer({
            id: 'nearby-trail-points-circle',
            type: 'circle',
            source: 'nearby-trail-points',
            layout: { visibility: 'none' },
            paint: {
              'circle-radius': 6,
              'circle-color': '#929A95',
              'circle-stroke-color': '#ffffff',
              'circle-stroke-width': 2,
            },
          });
          map.addLayer({
            id: 'nearby-trail-points-label',
            type: 'symbol',
            source: 'nearby-trail-points',
            minzoom: 8,
            layout: {
              visibility: 'none',
              'text-field': ['get', 'name'],
              'text-size': 11,
              'text-font': ['Noto Sans Regular'],
              'text-offset': [0, 1.25],
              'text-anchor': 'top',
            },
            paint: {
              'text-color': '#59615C',
              'text-halo-color': '#ffffff',
              'text-halo-width': 2,
            },
          });
          const escName = s => String(s == null ? '' : s).replace(/[&<>"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch]));
          const openNearbyPopup = (e) => {
            // If this click also lands on the current trail's own route,
            // let the main route win, no neighbour popup on top of it.
            if(e.type === 'click' && e.features && e.features[0] && e.features[0].geometry.type === 'LineString' && map.getLayer('single-trail-path-line')){
              const onMain = map.queryRenderedFeatures(e.point, { layers: ['single-trail-path-line'] });
              if(onMain.length) return;
            }
            const f = e.features && e.features[0];
            if(!f) return;
            const p = f.properties;
            new maplibregl.Popup({ offset: 12, maxWidth: '260px' })
              .setLngLat(e.lngLat)
              .setHTML(
                `<div style="font:700 14px 'Bricolage Grotesque',sans-serif;color:#2E4034;">${escName(p.name)}</div>` +
                `<div style="font:600 11.5px 'Inter',sans-serif;color:#6B7A6E;margin-top:3px;">${escName(String(p.distance))} km trail${p.awayKm != null ? ` · ${escName(String(p.awayKm))} km away` : ''}</div>` +
                `<a href="trail.html?id=${encodeURIComponent((window.DoloPawsRegionalData && window.DoloPawsRegionalData.slugFor ? window.DoloPawsRegionalData.slugFor(p.id) : (p.id)))}" style="display:inline-block;margin-top:9px;font:700 12.5px 'Inter',sans-serif;color:#fff;background:#2E4034;padding:8px 14px;border-radius:9px;text-decoration:none;">Open this trail →</a>`
              )
              .addTo(map);
          };
          map.on('click', 'other-trails-hit', openNearbyPopup);
          map.on('click', 'nearby-trail-points-circle', openNearbyPopup);
          map.on('mouseenter', 'other-trails-hit', () => { map.getCanvas().style.cursor = 'pointer'; });
          map.on('mouseleave', 'other-trails-hit', () => { map.getCanvas().style.cursor = ''; });
          map.on('mouseenter', 'nearby-trail-points-circle', () => { map.getCanvas().style.cursor = 'pointer'; });
          map.on('mouseleave', 'nearby-trail-points-circle', () => { map.getCanvas().style.cursor = ''; });

          if(nearbyToggleBtn){
            let showingNearbyOverview = false;
            nearbyToggleBtn.addEventListener('click', () => {
              showingNearbyOverview = !showingNearbyOverview;
              nearbyToggleBtn.classList.toggle('on', showingNearbyOverview);
              nearbyToggleBtn.setAttribute('aria-pressed', showingNearbyOverview ? 'true' : 'false');
              ['other-trails-line', 'other-trails-hit', 'nearby-trail-points-circle', 'nearby-trail-points-label'].forEach(id => {
                if(map.getLayer(id)) map.setLayoutProperty(id, 'visibility', showingNearbyOverview ? 'visible' : 'none');
              });
              const bounds = new maplibregl.LngLatBounds();
              t.path.forEach(([lat, lng]) => bounds.extend([lng, lat]));
              if(showingNearbyOverview){
                otherTrails.forEach(trail => trail.path.forEach(([lat, lng]) => bounds.extend([lng, lat])));
                setLayerChipLabel(nearbyToggleBtn, 'routes', 'Focus this trail');
                map.fitBounds(bounds, { padding: 54, maxZoom: 13 });
              } else {
                setLayerChipLabel(nearbyToggleBtn, 'nearby', `Nearby trails (${nearbyTrails.length})`);
                map.fitBounds(bounds, { padding: 60, maxZoom: 17 });
              }
            });
          }
          } catch (error) {
            // The style was not ready to take these layers. Undo the flag and
            // try again when more style data lands; the adds above are the only
            // thing that can fail, and a partial add is cleaned up by removing
            // whatever went in before the throw.
            nearbyLayersAdded = false;
            ['other-trails-line', 'other-trails-hit', 'nearby-trail-points-circle', 'nearby-trail-points-label']
              .forEach(id => { if(map.getLayer(id)) map.removeLayer(id); });
            ['other-trails', 'nearby-trail-points']
              .forEach(id => { if(map.getSource(id)) map.removeSource(id); });
            map.once('styledata', renderNearbyTrailLayers);
          }
        }
      }
      renderNearbyTrailLayers();
      window.addEventListener('dolopaws-region-loaded', renderNearbyTrailLayers);

      if(Array.isArray(t.path) && t.path.length > 1){
        const selectedRouteColor = window._dolopawsTrailRouteColor || detailRouteColorForScore(guestMatchScore(t));
        map.addSource('single-trail-path', {
          type: 'geojson',
          data: {
            type: 'Feature',
            properties: {},
            geometry: { type: 'LineString', coordinates: t.path.map(([lat, lng]) => [lng, lat]) },
          },
        });
        // The route is a highlight UNDER the hiking network, not a line over
        // it: a translucent match-colour corridor with a white casing, with
        // the waymarked raster drawing on top. Waymarked's own route line and
        // its numbered shields then run down the middle of the highlight, so
        // the numbers a walker actually follows stay visible and we no longer
        // reprint them ourselves.
        window.ORMAMapStyle.addRouteLine(map, {
          id: 'single-trail-path-line',
          source: 'single-trail-path',
          color: selectedRouteColor,
          beforeId: window.ORMAMapStyle.WAYMARKED_LAYER,
        });

        // Closed loops are intentionally direction-neutral: hikers can join
        // anywhere and walk clockwise or anticlockwise. Keep arrows only for
        // routes whose start and end are genuinely different.
        const routeIsLoop = distMeters(t.path[0], t.path[t.path.length - 1]) <= 75;
        if(!routeIsLoop){
          map.addLayer({
            id: 'single-trail-direction-arrows',
            type: 'symbol',
            source: 'single-trail-path',
            layout: {
              'symbol-placement': 'line',
              'symbol-spacing': 70,
              'text-field': '➤',
              'text-size': 18,
              'text-rotation-alignment': 'map',
              'text-keep-upright': false,
              'text-allow-overlap': true,
              'text-ignore-placement': true,
            },
            paint: {
              'text-color': '#ffffff',
              'text-halo-color': selectedRouteColor,
              'text-halo-width': 2,
            },
          // Above the hiking raster so they stay visible, below the labels so
          // they never sit on a place name.
          }, firstLabelId);
        }
        // No ORMA route-number shields here any more. They existed only
        // because the old opaque route line hid Waymarked's baked-in numbers;
        // now the raster draws above the highlight and those real numbers are
        // visible, so a second set of our own would just be duplicates
        // fighting them for space. The reference list still renders as text in
        // the trail details column via trail-blueprint.js.
        const bounds = new maplibregl.LngLatBounds();
        t.path.forEach(([lat, lng]) => bounds.extend([lng, lat]));
        map.fitBounds(bounds, { padding: 60, maxZoom: 17 });

        setupElevationProfile(map, t);

        // NOTE: curated rifugi/water emoji markers used to be placed here
        // from the trail's km data, removed: they duplicated the real OSM
        // amenity dots (detail-pois.js), showing two markers for the same
        // rifugio. The OSM dot layers are now the single amenity language
        // on every map; the curated km list still renders as text in the
        // "Trail details" column. Emoji markers remain only for things OSM
        // can't know: recommended start, decision points, community flags.

        // Decision points, where a hiker needs to switch from one numbered
        // route onto another. Always real, verified coordinates (these come
        // from actual confirmed junctions between two GPX tracks, never
        // interpolated) so no fallback branch is needed here.
        (t.decisionPoints || []).forEach(d => {
          new maplibregl.Marker({ element: makeIconEl('switch', '#D6A038'), offset: [14, -14] })
            .setLngLat([d.lng, d.lat])
            .setPopup(new maplibregl.Popup({ offset: 16 }).setHTML(`<b>Km ${d.km}</b><br>${d.instruction}`))
            .addTo(map);
        });

        // Only draw a trail-owned waypoint when it has verified GPS
        // coordinates. Interpolating from a rounded kilometre can put an icon
        // on the wrong bend or side of a loop. OSM-backed points already render
        // at their source coordinates through detail-pois.js, so do not draw a
        // duplicate marker on top of them here.
        if(Array.isArray(t.path) && t.path.length > 1){
          const addWaypoint = (waypoint, icon, label) => {
            if(!waypoint || waypoint.osmId || typeof waypoint.lat !== 'number' || typeof waypoint.lng !== 'number') return;
            const mk = new maplibregl.Marker({ element: makeIconEl(icon), offset: [0, -6] })
              .setLngLat([waypoint.lng, waypoint.lat])
              .setPopup(new maplibregl.Popup({ offset: 14 }).setHTML(`<b>${itinEsc(label)}</b>${typeof waypoint.km === 'number' ? `<br>Km ${waypoint.km}` : ''}`))
              .addTo(map);
            amenityMarkers.push({ marker: mk, group: icon === 'hut' ? 'huts' : 'fountains' });
            mk.getElement().style.display = poiStates[icon === 'hut' ? 'huts' : 'fountains'] ? '' : 'none';
          };
          (t.rifugi || []).forEach(r => addWaypoint(r, 'hut', trLabel(r.name)));
          (t.waterSources || []).forEach(w => {
            addWaypoint(w, 'water', trLabel(trustedWaterLabel(t, w.label)));
          });
        }

        // Recommended starting point, a loop can technically be walked
        // from anywhere on it, but a real, well-marked access/parking point
        // is worth calling out explicitly rather than leaving people to
        // guess where to begin.
        if(t.startPoint){
          new maplibregl.Marker({ element: makeIconEl('start', '#2E4034'), offset: [-14, -14] })
            .setLngLat([t.startPoint.lng, t.startPoint.lat])
            .setPopup(new maplibregl.Popup({ offset: 16 }).setHTML(`<b>${trLabel(trustedStartLabel(t, t.startPoint.label))}</b>`))
            .addTo(map);
        }
      } else {
        new maplibregl.Marker({ color: '#6FA8BE' }).setLngLat([t.lng, t.lat]).addTo(map);
      }

      if (typeof makeBasemapPoisClickable === 'function') makeBasemapPoisClickable(map);

      // Community dog-safety flags, list, map markers, report modal.
      if (typeof initTrailReports === 'function') initTrailReports(map, t);
    });
  }
  };
  if(window.DoloPawsMapRuntime){
    const mobileMapLoadBtn = document.getElementById('mobileMapLoadBtn');
    const deferMobileMap = !!(window.matchMedia && window.matchMedia('(max-width: 700px)').matches && !hikeDeepLinkRequested);
    let detailMapSchedule;
    if(deferMobileMap){
      let mapStartPromise = null;
      detailMapTarget.dataset.mapState = 'waiting';
      const startMobileMap = () => {
        if(mapStartPromise) return mapStartPromise;
        detailMapTarget.dataset.mapState = 'loading';
        if(mobileMapLoadBtn) mobileMapLoadBtn.hidden = true;
        mapStartPromise = window.DoloPawsMapRuntime.load()
          .then(initDetailMap)
          .then(result => {
            detailMapTarget.dataset.mapState = 'ready';
            return result;
          })
          .catch(error => {
            detailMapTarget.dataset.mapState = 'error';
            detailMapTarget.setAttribute('aria-label', 'Map unavailable. Trail details remain available below.');
            console.error('ORMA map failed to initialise:', error);
            return null;
          });
        return mapStartPromise;
      };
      detailMapSchedule = { start:startMobileMap, get promise(){ return mapStartPromise; } };
      if(mobileMapLoadBtn) mobileMapLoadBtn.addEventListener('click', startMobileMap, { once:true });
      // Once the document itself has finished, prepare the map in idle time.
      // A direct tap always wins and starts it immediately.
      window.addEventListener('load', () => {
        if(typeof requestIdleCallback === 'function') requestIdleCallback(startMobileMap, { timeout:8000 });
        else setTimeout(startMobileMap, 4000);
      }, { once:true });
    }else{
      detailMapSchedule = window.DoloPawsMapRuntime.whenVisible(detailMapTarget, initDetailMap, {
        rootMargin:'360px 0px',
        triggers:[document.getElementById('mapExpandBtn')],
      });
    }
    window.DoloPawsStartTrailMap = () => detailMapSchedule && detailMapSchedule.start
      ? detailMapSchedule.start()
      : Promise.resolve(window._dolopawsTrailMap || null);
    const expand = document.getElementById('mapExpandBtn');
    if(expand){
      expand.addEventListener('click', async event => {
        if(window._dolopawsTrailMap || !detailMapSchedule || !detailMapSchedule.start) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        await detailMapSchedule.start();
        if(window._dolopawsTrailMap) expand.click();
      }, { capture:true });
    }
    // Let the map prepare in the background for hike guidance, but do not
    // block the readiness sheet or GPS recording on that network work.
    if(hikeDeepLinkRequested && detailMapSchedule && detailMapSchedule.start){
      detailMapSchedule.start();
    }
  } else {
    window.DoloPawsStartTrailMap = () => Promise.resolve(initDetailMap());
    initDetailMap();
  }

  // Save button, reflects and updates real account state, same pattern as the trail cards.
  const saveBtn = document.getElementById('detailSaveBtn');
  let saveStatusTimer = null;
  function showSaveStatus(message){
    let status = document.getElementById('detailSaveStatus');
    if(!status){
      status = document.createElement('div');
      status.id = 'detailSaveStatus';
      status.className = 'dw-toast';
      status.setAttribute('role', 'status');
      status.setAttribute('aria-live', 'polite');
      document.body.appendChild(status);
    }
    if(saveStatusTimer) clearTimeout(saveStatusTimer);
    status.textContent = message;
    status.hidden = false;
    status.className = 'dw-toast dw-toast--in';
    saveStatusTimer = setTimeout(() => {
      status.hidden = true;
      status.className = 'dw-toast';
    }, 4200);
  }
  function paintSaveBtn(isFav){
    const heart = isFav
      ? '<svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 21S3.5 14.6 3.5 8.8A4.8 4.8 0 0 1 12 6a4.8 4.8 0 0 1 8.5 2.8C20.5 14.6 12 21 12 21z"/></svg>'
      : '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20.4S4.2 14.5 4.2 9.2A4.3 4.3 0 0 1 12 6.6a4.3 4.3 0 0 1 7.8 2.6c0 5.3-7.8 11.2-7.8 11.2z"/></svg>';
    saveBtn.innerHTML = heart + (isFav ? ' Saved' : ' Save');
    saveBtn.classList.toggle('saved', isFav);
  }
  async function handleSaveAuth(user){
    if(!user || !window.DoloPawsAuth){
      saveBtn.onclick = () => {
        if(window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('save');
      };
      paintSaveBtn(false);
      return;
    }
    const favorites = await window.DoloPawsAuth.getFavorites();
    if(window.DoloPawsTrailAction && window.DoloPawsTrailAction.consume('save') && !favorites[t.id]){
      favorites[t.id] = true;
      const saved = await window.DoloPawsAuth.setFavorites(favorites);
      if(saved) showSaveStatus(window.t('save.added'));
      else {
        delete favorites[t.id];
        showSaveStatus(window.t('save.error'));
      }
    }
    paintSaveBtn(!!favorites[t.id]);
    saveBtn.onclick = async () => {
      saveBtn.disabled = true;
      const current = await window.DoloPawsAuth.getFavorites();
      const wasSaved = !!current[t.id];
      if(wasSaved) delete current[t.id]; else current[t.id] = true;
      const saved = await window.DoloPawsAuth.setFavorites(current);
      if(saved){
        paintSaveBtn(!wasSaved);
        showSaveStatus(window.t(wasSaved ? 'save.removed' : 'save.added'));
      } else {
        paintSaveBtn(wasSaved);
        showSaveStatus(window.t('save.error'));
      }
      saveBtn.disabled = false;
    };
  }
  window.addEventListener('dolopaws-auth-changed', e => handleSaveAuth(e.detail.user));
  if(window.DoloPawsAuth) handleSaveAuth(window.DoloPawsAuth.currentUser);

  // GPX export is intentionally account-gated. The file contains the ordered
  // route and trailhead, but not the richer safety context shown on ORMA.
  const exportGpxBtn = document.getElementById('exportGpxBtn');
  if(exportGpxBtn){
    let exportStatusTimer = null;
    function showExportStatus(message){
      let status = document.getElementById('exportGpxStatus');
      if(!status){
        status = document.createElement('div');
        status.id = 'exportGpxStatus';
        status.className = 'dw-toast';
        status.setAttribute('role', 'status');
        status.setAttribute('aria-live', 'polite');
        document.body.appendChild(status);
      }
      if(exportStatusTimer) clearTimeout(exportStatusTimer);
      status.textContent = message;
      status.hidden = false;
      status.className = 'dw-toast dw-toast--in';
      exportStatusTimer = setTimeout(() => {
        status.hidden = true;
        status.className = 'dw-toast';
      }, 5200);
    }
    function runGpxExport(){
      if(!window.DoloPawsGpxExport){
        showExportStatus('GPX export could not load. Please refresh and try again.');
        return false;
      }
      try {
        window.DoloPawsGpxExport.download(t);
        showExportStatus('GPX downloaded. It contains the route only, check ORMA for safety context.');
        return true;
      } catch(error){
        showExportStatus(error && error.message
          ? error.message : 'This trail could not be exported.');
        return false;
      }
    }
    function handleExportAuth(user){
      exportGpxBtn.onclick = () => {
        if(!(user && window.DoloPawsAuth)){
          if(window.DoloPawsTrailAction) window.DoloPawsTrailAction.request('export-gpx');
          return;
        }
        runGpxExport();
      };
      if(user && window.DoloPawsTrailAction
        && window.DoloPawsTrailAction.consume('export-gpx')){
        runGpxExport();
      }
    }
    window.addEventListener('dolopaws-auth-changed', event => handleExportAuth(event.detail.user));
    handleExportAuth(window.DoloPawsAuth && window.DoloPawsAuth.currentUser);
  }
}

// This file is deferred, so the trail DOM and synchronous regional payload
// are available even if authentication is still delaying DOMContentLoaded.
if(document.querySelector('.td2')){
  init();
} else if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
;

// ---- trail-blueprint.js ----
/**
 * trail-blueprint.js, the "answer-first" layer of the trail page.
 *
 * Fills the new blueprint sections WITHOUT touching trail.js logic:
 *   - Verified/Imported seal in the hero
 *   - Answer strip: "Right for your dog?" · "Today?" · "Getting there"
 *   - Nearby trails (same valley, via regions-config)
 *
 * Everything is derived from data that already exists (trail fields,
 * the live weather chip trail.js populates, the same scoreTrail() the
 * hero match uses). Nothing is invented. Load AFTER trail.js.
 */
(function () {
  'use strict';

  const params = new URLSearchParams(window.location.search);
  // The URL may name the trail by its readable slug; the loader owns that
  // mapping. Reading the raw param here made every slug URL miss the lookup
  // below, and the whole blueprint returned early.
  const trailId = (window.DoloPawsRegionalData && window.DoloPawsRegionalData.resolveTrailId ? window.DoloPawsRegionalData.resolveTrailId(params.get('id')) : (params.get('id')));
  const t = (typeof trails !== 'undefined') ? trails.find(x => x.id === trailId) : null;
  if (!t) return;

  const $ = (id) => document.getElementById(id);
  const trust = window.DoloPawsTrailTrust;
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  // Where ORMA got a route is not something a walker asked. 123 of 162 trails
  // still described themselves as "imported from the OpenStreetMap hiking
  // network", and 70 start points as an "(OSM-verified access point)" -- the
  // provenance of the record leaking into the copy a reader is given. The
  // number it cites is already shown as a waymark badge, so nothing is lost by
  // dropping it, and the screening sentence says the same fact in a reader's
  // words instead of the pipeline's.
  const readerVoice = (s) => String(s)
    .replace(/,?\s*imported from the OpenStreetMap hiking network(\s*\(trail [^)]*\))?/gi, '')
    .replace(/\s*\(OSM-verified access point\)/gi, '')
    .replace(/Passed automated dog-suitability screening:\s*no\s+([^.]+?)\s+on record\./i,
      (match, items) => `No ${items} are recorded on this route.`)
    .replace(/^\s*Imported route[.:,\s-]*/i, '');
  const cardCopy = (s) => readerVoice(String(s == null ? '' : s))
    .trim()
    .replace(/\s*(?:—|--)+\s*/g, '. ')
    .replace(/\.\s*\./g, '.')
    .replace(/\s{2,}/g, ' ')
    .replace(/(^|[.!?]\s+)([a-z])/g, (match, lead, letter) => lead + letter.toUpperCase());
  const dpIcon = (key, size = 14) => window.DoloPawsIcons
    ? window.DoloPawsIcons.renderIconSvg(key, { mode:'inline', color:'currentColor', size })
    : '';
  const tt = (key, vars, fallback) => {
    const out = (typeof window.t === 'function') ? window.t(key, vars) : null;
    return (out && out !== key) ? out : fallback;
  };
  const accessTarget = (() => {
    const start = t.startPoint || {};
    const lat = typeof start.lat === 'number' ? start.lat : t.lat;
    const lng = typeof start.lng === 'number' ? start.lng : t.lng;
    return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
  })();
  const wireTrailheadDirections = (element, statusElement) => {
    if(!element || !accessTarget) return;
    element.removeAttribute('target');
    element.removeAttribute('rel');
    element.href = '#';
    element.addEventListener('click', async event => {
      event.preventDefault();
      const access = window.DoloPawsTrailAccess;
      if(!access){
        if(statusElement) statusElement.textContent = 'Directions are unavailable right now.';
        return;
      }
      element.setAttribute('aria-disabled', 'true');
      if(statusElement) statusElement.textContent = 'Checking your distance from the trailhead…';
      try{
        const plan = await access.planFromCurrent(navigator, accessTarget, navigator.userAgent, 100);
        if(!plan.allowed){
          if(statusElement) statusElement.textContent =
            `Directions are available when you are within 100 km of the trail (${Math.round(plan.distanceKm)} km away).`;
          return;
        }
        if(statusElement) statusElement.textContent = `${Math.round(plan.distanceKm)} km away · opening directions…`;
        window.open(plan.url, '_blank', 'noopener');
      }catch(error){
        if(statusElement) statusElement.textContent =
          'Allow location access to check that you are within 100 km of this trail.';
      }finally{
        element.removeAttribute('aria-disabled');
      }
    });
  };

  /* ---- Tier seal in the hero ------------------------------------- */
  (function seal() {
    const el = $('verifiedSeal');
    if (!el) return;
    const style = trust && trust.tierBadgeStyle ? trust.tierBadgeStyle(t) : (t.curated === false ? 'imported' : 'verified');
    const label = trust ? trust.provenanceLabel(t) : (t.curated === false ? 'Imported trail' : 'Verified by ORMA');
    // Render the same pill the browse-trail cards use, not a bespoke inline seal.
    el.innerHTML = (window.DoloPawsIcons && window.DoloPawsIcons.badgeHtml)
      ? window.DoloPawsIcons.badgeHtml(style, label)
      : dpIcon(style) + '<span>' + esc(label) + '</span>';
    el.hidden = false;
  })();

  /* ---- Public review record --------------------------------------
     Claim-level evidence remains in the Trail Verification Desk. */
  (function reviewRecord() {
    const meta = $('trailReviewMeta');
    if (!meta) return;
    // The record follows the same tier as the seal, so the pill and the
    // sentence can never disagree. Only an earned verification claims the date;
    // a reviewed-but-unverified listing says exactly that.
    const tier = trust && trust.tierOf ? trust.tierOf(t) : null;
    if (tier === 'route-audited' || tier === 'dolopaws-walked') {
      const date = trust.formatReviewDate(t.reviewedAt || (t.verified && t.verified.date));
      meta.textContent = `Verified by ORMA on ${date}. Check current conditions before setting out.`;
    } else if (tier === 'route-reviewed') {
      meta.textContent = 'Trail details prepared and reviewed by ORMA — not yet field-verified. Check local access rules and current conditions before setting out.';
    } else {
      meta.textContent = 'This mapped trail has not yet been field-verified by ORMA. Check local access rules and current conditions before setting out.';
    }
  })();

  /* ---- Answer strip ---------------------------------------------- */
  const strip = $('qaStrip');
  // The personalised match below now carries the decision context, so these
  // older answer cards stay out of the visual flow.
  if (strip) strip.hidden = true;

  // Card 1, Right for your dog? Three honest states.
  function paintDogCard() {
    const title = $('qaDogTitle'), sub = $('qaDogSub');
    if (!title || !sub) return;

    const factBits = [];
    if (t.safetyLevel) {
      const baseRisk = safetyLabel(t.safetyLevel);
      factBits.push((trust ? trust.riskLabel(t, baseRisk) : baseRisk).toLowerCase());
    }
    if (typeof t.distance === 'number') factBits.push(t.distance <= 6 ? 'easy distance' : `${t.distance} km`);
    if (typeof t.shadeCoverage === 'number') factBits.push(t.shadeCoverage >= 40 ? 'good shade' : 'little shade');
    const factLine = factBits.join(' · ');

    function guest() {
      title.textContent = tt('qa.dogGuest', null, 'Would this suit your dog?');
      const returnToTrail = encodeURIComponent(location.pathname.split('/').pop() + location.search);
      sub.innerHTML = esc(factLine) + (factLine ? ' · ' : '') +
        '<a href="account.html?next=' + returnToTrail + '">' + tt('qa.dogGuestCta', null, 'create a free profile to find out') + ' →</a>';
    }
    function noProfile() {
      title.textContent = tt('qa.dogNoProfile', null, 'Whose paws are we scoring?');
      const returnToTrail = encodeURIComponent(location.pathname.split('/').pop() + location.search);
      sub.innerHTML = '<a href="account.html?next=' + returnToTrail + '">' + tt('qa.dogNoProfileCta', null, 'Add your dog, 2 minutes') + ' →</a>';
    }
    function paint() {
      if (typeof scoreTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) { guest(); return; }
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) { noProfile(); return; }
        const n = scoreTrail(t, (typeof effectiveOverrides === 'function') ? effectiveOverrides(profile, null) : profile,
          conditionsForScoring(t));
        const name = profile.name || tt('trail.yourDog', null, 'your dog');
        const approx = t.curated === false ? '≈' : '';
        title.textContent = tt('qa.dogScored', { n: approx + n, name },
          `Right for ${name}? ${approx}${n}%`);
        sub.textContent = factLine;
      }).catch(guest);
    }
    if (window.DoloPawsAuth) paint();
    else window.addEventListener('dolopaws-auth-ready', paint, { once: true });
    window.addEventListener('dolopaws-auth-changed', paint);
  }
  paintDogCard();

  // Card 3, Getting there. Start point label + directions link.
  (function paintAccessCard() {
    const card = $('qaAccess'), title = $('qaAccessTitle'), sub = $('qaAccessSub');
    if (!card) return;
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    if (typeof lat !== 'number') return;
    title.textContent = tt('qa.accessTitle', null, 'Getting there');
    const rawLabel = sp.label || tt('trail.itinParkFallback', null, 'Trailhead');
    const label = esc(trust ? trust.startPointLabel(t, rawLabel) : rawLabel);
    sub.innerHTML = label +
      ` · <a href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}" target="_blank" rel="noopener">` +
      tt('trail.openMaps', null, 'get directions') + ' →</a>';
    card.hidden = false;
  })();

  /* ---- Nearby trails (same valley first, then same region) ------- */
  // Re-runnable on purpose. A trail page loads its own detail file first and
  // the rest of the region after the paint, so the first call here sees one
  // trail, finds no neighbours and returns; the region announces itself when it
  // lands and this runs again with a real pool.
  function nearby() {
    const wrapEl = $('nearbyTrails'), grid = $('nearbyGrid');
    if (!wrapEl || !grid || typeof trails === 'undefined') return;
    const pool = trails.filter(o => o.id !== t.id);
    const sameValley = pool.filter(o => o.valley && o.valley === t.valley);
    const sameRegion = pool.filter(o => o.region === t.region && o.valley !== t.valley);
    const picks = sameValley.slice(0, 4);
    for (const o of sameRegion) { if (picks.length >= 4) break; picks.push(o); }
    if (!picks.length) return;
    // Reference gallery card: photo, floating match % chip, serif name, meta.
    const cardPhoto = source => ({
      'images/lago-di-braies.webp':'images/lago-di-braies-480.webp',
      'images/lago-di-carezza.webp':'images/lago-di-carezza-480.webp',
      'images/boucle-du-marais-des-chassettes.webp':'images/boucle-du-marais-des-chassettes-480.webp',
      'images/itineraire-decouverte-de-la-nature.webp':'images/itineraire-decouverte-de-la-nature-480.webp',
    }[source] || source);
    grid.innerHTML = picks.map(o => `
      <a class="near-card" href="trail.html?id=${encodeURIComponent((window.DoloPawsRegionalData && window.DoloPawsRegionalData.slugFor ? window.DoloPawsRegionalData.slugFor(o.id) : (o.id)))}" data-near-id="${esc(o.id)}">
        <div class="ph"${o.imageIcon ? ` style="background-image:url('${esc(cardPhoto(o.imageIcon))}');"` : ''}><span class="pct near-pct" hidden></span></div>
        <div class="bd">
          <div class="nm">${esc(o.name)}</div>
          <div class="mt">${esc(o.valley || o.area || '')} · ${o.distance} km · ${esc(trust ? trust.riskLabel(o, safetyLabel(o.safetyLevel)) : safetyLabel(o.safetyLevel))}</div>
        </div>
      </a>`).join('');
    wrapEl.hidden = false;
    const seeAll = $('nearbySeeAll');
    if (seeAll && (t.valley || t.area)) seeAll.textContent = 'See all in ' + (t.valley || t.area) + ' \u2192';

    // Personalise: retitle the section and fill each pick's real match %
    // chip, same scoreTrail() as everywhere else.
    function personalise() {
      if (typeof scoreTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) return;
        const heading = $('nearbyTitle');
        if (heading && profile.name) heading.textContent = 'Nearby trails, ranked for ' + profile.name;
        const ov = (typeof effectiveOverrides === 'function') ? effectiveOverrides(profile, null) : profile;
        for (const o of picks) {
          const slot = grid.querySelector(`[data-near-id="${CSS.escape(o.id)}"] .near-pct`);
          if (!slot) continue;
          slot.textContent = (o.curated === false ? '≈' : '') + scoreTrail(o, ov, conditionsForScoring(o)) + '%';
          slot.hidden = false;
        }
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) personalise();
    else window.addEventListener('dolopaws-auth-ready', personalise, { once: true });
    window.addEventListener('dolopaws-auth-changed', personalise);
  }
  nearby();
  window.addEventListener('dolopaws-region-loaded', nearby);

  /* ---- Dog tips note (verified trails only) ----------------------- */
  (function tipsNote() {
    const note = $('dogTipsNote');
    if (note && t.curated !== false && t.tips) note.hidden = false;
  })();

  /* ---- Decision-first hero and safety dashboard ------------------ */
  (function decisionFlow() {
    // Hero photo behind the title (reference: dimmed photo + cream veil).
    const heroPhoto = $('tdHeroPhoto');
    if (heroPhoto && t.imageIcon && heroPhoto.tagName !== 'IMG') {
      const stem = String(t.imageIcon).replace(/\.webp$/, '');
      const wideSources = [
        'images/boucle-du-marais-des-chassettes.webp',
        'images/itineraire-decouverte-de-la-nature.webp',
      ];
      const background = wideSources.includes(t.imageIcon)
        ? `${stem}-${window.matchMedia('(max-width: 700px)').matches ? '960' : '1280'}.webp`
        : t.imageIcon;
      heroPhoto.style.backgroundImage = `url("${background.replace(/["')]/g, '')}")`;
    }

    // Breadcrumb: "← Trails · {region} · {valley}"
    const crumb = $('tdBreadcrumb');
    if (crumb && /^browse-trails\.html(?:[?#]|$)/.test(crumb.getAttribute('href') || '')) {
      const regionName = t.region === 'savoy' ? 'Savoy' : 'Dolomites';
      crumb.textContent = '← Trails · ' + regionName + (t.valley ? ' · ' + t.valley : '');
    }

    // Safety rating as the same coloured pill the browse cards use.
    const riskLine = $('tdRiskLine');
    if (riskLine && t.safetyLevel) {
      const labels = { 'low-risk': 'Low-risk terrain', 'moderate': 'Moderate terrain', 'caution': 'Caution terrain' };
      const baseRisk = labels[t.safetyLevel] || '';
      const riskText = trust ? trust.riskLabel(t, baseRisk) : baseRisk;
      riskLine.innerHTML = (window.DoloPawsIcons && window.DoloPawsIcons.badgeHtml)
        ? window.DoloPawsIcons.badgeHtml(t.safetyLevel, riskText)
        : esc(riskText);
      riskLine.hidden = false;
    }
    // A route that rides an open chairlift says so at the top, to everyone.
    // The recommendation card grades it; this is the plain fact.
    const lift = t.liftAccess || {};
    const openChairlift = lift.dependency === 'required' && ['chairlift', 'mixed', 'unknown'].includes(lift.type);
    const tags = document.querySelector('.td2-hero .td2-tags');
    if (openChairlift && tags && !tags.querySelector('.td-lift-warning')) {
      const warning = document.createElement('span');
      warning.className = 'td-lift-warning';
      warning.innerHTML = (window.DoloPawsIcons && window.DoloPawsIcons.badgeHtml)
        ? window.DoloPawsIcons.badgeHtml('caution', 'Chairlift-assisted · not for most dogs')
        : esc('Chairlift-assisted · not for most dogs');
      tags.appendChild(warning);
    }

    // Elevation figures under the real chart; hide the block honestly
    // when the trail has no profile data.
    const prof = Array.isArray(t.elevationProfile) ? t.elevationProfile.map(p => Number(p.elev) || 0) : [];
    if (prof.length > 1) {
      const figs = $('tdElevFigs');
      if (figs) {
        $('tdElevStart').textContent = prof[0].toLocaleString() + ' m';
        $('tdElevHigh').textContent = Math.max(...prof).toLocaleString() + ' m';
        $('tdElevClimb').textContent = '+' + (t.elevation != null ? t.elevation : Math.max(...prof) - Math.min(...prof)) + ' m';
        figs.hidden = false;
      }
    } else {
      const h = $('tdElevH'), svg = $('elevProf');
      if (h) h.hidden = true;
      if (svg) svg.style.display = 'none';
    }

    const easyTerrain = Number(t.terrainRank) === 0;
    const lowRisk = t.safetyLevel === 'low-risk';
    const verdict = openChairlift
      ? 'This route depends on an open chairlift' + (lift.name ? ' (' + lift.name + ')' : '') + '. Only for a dog of 8 kg or under that rides calmly held on a lap; a hard stop for every other dog.'
      : t.curated === false
      ? 'Automated estimate from mapped route data. Exposure, shade, livestock and current conditions are not field verified.'
      : lowRisk && easyTerrain
      ? 'A gentle, low-risk choice for most dogs.'
      : t.safetyLevel === 'caution'
        ? 'A more demanding trail: check the hazards and your dog’s confidence before committing.'
        : 'A manageable trail for prepared dogs; review the route constraints before committing.';
    const heroVerdict = $('heroVerdict');
    if (heroVerdict) heroVerdict.textContent = verdict;

    const svg = (kind) => {
      const paths = {
        paw: '<circle cx="8" cy="8.2" r="1.6" fill="#5DCAA5"/><circle cx="12" cy="6.6" r="1.6" fill="#5DCAA5"/><circle cx="16" cy="8.2" r="1.6" fill="#5DCAA5"/><path d="M8.4 16.5c0-2.4 1.5-4.2 3.6-4.2s3.6 1.8 3.6 4.2c0 1.4-1.1 2.5-2.5 2.5-.7 0-1.1-.3-1.7-.7-.5.4-1 .7-1.7.7-1.3 0-2.3-1.1-2.3-2.5Z" fill="#1D9E75"/>',
        shade: '<path d="M12 5v14M7 19h10M6 12c0-3 2.7-6 6-6s6 3 6 6Z" fill="none" stroke="#4A7856" stroke-width="1.8"/><path d="m7 12-3 3M17 12l3 3" fill="none" stroke="#4A7856" stroke-width="1.8"/>',
        water: '<path d="M12 4c2.8 3.4 4.5 6 4.5 8.4a4.5 4.5 0 1 1-9 0C7.5 10 9.2 7.4 12 4Z" fill="#378ADD"/>',
        heat: '<circle cx="12" cy="12" r="4" fill="#D6A038"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4" fill="none" stroke="#D6A038" stroke-width="1.8" stroke-linecap="round"/>',
        park: '<rect x="4.5" y="4.5" width="15" height="15" rx="3.5" fill="#fff" stroke="#4C87C6" stroke-width="1.6"/><path d="M10 16.2V7.8h3.1a2.6 2.6 0 0 1 0 5.2H10" fill="none" stroke="#4C87C6" stroke-width="1.9" stroke-linecap="round"/>',
        route: '<path d="M6 18c2-5 5.5-9 12-12" fill="none" stroke="#2C5C34" stroke-width="2" stroke-linecap="round"/><circle cx="7" cy="18" r="1.7" fill="#2C5C34"/><path d="M17.5 4.2l2.6 1-1 2.5-2.6-1z" fill="#E24B4A"/>',
        crowd: '<ellipse cx="5" cy="8" rx="2.5" ry="4.5" fill="#8B6F47" transform="rotate(-20 5 8)"/><ellipse cx="19" cy="8" rx="2.5" ry="4.5" fill="#8B6F47" transform="rotate(20 19 8)"/><circle cx="12" cy="14" r="7" fill="#8B6F47"/><ellipse cx="12" cy="16" rx="4" ry="3" fill="#A08060"/><circle cx="9.5" cy="12" r="1.2" fill="#3D2817"/><circle cx="9.8" cy="11.5" r="0.4" fill="#fff"/><circle cx="14.5" cy="12" r="1.2" fill="#3D2817"/><circle cx="14.8" cy="11.5" r="0.4" fill="#fff"/><circle cx="12" cy="16" r="1" fill="#3D2817"/><path d="M12 17 Q11 18 10 17.5" fill="none" stroke="#3D2817" stroke-width="0.8" stroke-linecap="round"/><path d="M12 17 Q13 18 14 17.5" fill="none" stroke="#3D2817" stroke-width="0.8" stroke-linecap="round"/>',
        mountain: '<path d="m4 18 6-10 3 5 2-3 5 8Z" fill="none" stroke="#BA7517" stroke-width="1.8" stroke-linejoin="round"/>',
        loop: '<path d="M18 8a7 7 0 1 0 1 7M18 4v4h-4" fill="none" stroke="#3E7A91" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>'
      };
      return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[kind]}</svg>`;
    };
    const signalEl = $('matchSignals');
    const isLoop = Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
    const climb = Number(t.elevation) || 0;
    const signalData = [
      ['paw', easyTerrain ? 'Gentle paw surface' : 'Mixed paw surface', easyTerrain ? 'Flat or packed underfoot based on route information' : (t.terrainType || 'Check pads at breaks')],
      ['route', 'Route effort', `${t.distance} km${climb ? ` · +${climb} m` : ''}`],
      ['loop', isLoop ? 'Loop route' : 'One-way route', isLoop ? 'Returns to the starting point' : 'Plan the return journey']
    ];
    if (signalEl) {
      signalEl.innerHTML = signalData.map(([icon, title, sub]) =>
        `<div class="match-signal"><span class="mark" aria-hidden="true">✦</span><span><b>${esc(title)}</b><small>${esc(sub)}</small></span></div>`).join('');
    }
    // "Why this fits {name}" heading follows the profile when one exists.
    function paintWhyTitle() {
      if (!window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(p => {
        if (p && p.name && $('tdWhyTitle')) $('tdWhyTitle').textContent = 'Why this fits ' + p.name;
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) paintWhyTitle();
    else window.addEventListener('dolopaws-auth-ready', paintWhyTitle, { once: true });

    // Assessment note ABOVE the box, below the heading
    const assessmentNote = $('assessmentNote');
    if (assessmentNote) {
      assessmentNote.innerHTML = trust ? trust.assessmentNote(t) : `<strong style="color: var(--ink);">Our assessment of this trail:</strong> route facts are weighed against your dog's profile. Current conditions can still change.`;
    }

    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const startBtn = $('startNavigationBtn');
    if (startBtn) {
      startBtn.addEventListener('click', (event) => {
        const mapStart = $('mapStartHikeBtn');
        if (!mapStart) return;
        event.preventDefault();
        mapStart.click();
      });
    }
    const directionsBtn = $('getDirectionsBtn');
    wireTrailheadDirections(directionsBtn, $('getDirectionsStatus'));

    // Share popover (reference): Copy link with inline "✓ Link copied",
    // Message a walking buddy (sms:), Email this trail (mailto:).
    const shareBtn = $('detailShareBtn');
    const sharePop = $('tdSharePop');
    if (shareBtn && sharePop) {
      const smsLink = $('tdShareSms'), mailLink = $('tdShareMail');
      const shareDetails = () => {
        const url = new URL(location.pathname, location.href);
        url.searchParams.set('id', t.id);
        const activeTab = new URLSearchParams(location.search).get('tab');
        if (/^(?:safety|reviews)$/.test(activeTab || '')) url.searchParams.set('tab', activeTab);
        const shareUrl = url.href;
        return {
          url: shareUrl,
          text: t.name + ' on ORMA: ' + shareUrl
        };
      };
      const closeShare = () => {
        sharePop.hidden = true;
        shareBtn.setAttribute('aria-expanded', 'false');
      };
      const updateShareLinks = () => {
        const details = shareDetails();
        if (smsLink) smsLink.href = 'sms:?body=' + encodeURIComponent(details.text);
        if (mailLink) mailLink.href = 'mailto:?subject=' + encodeURIComponent(t.name + ' | ORMA') + '&body=' + encodeURIComponent(details.text);
      };
      shareBtn.addEventListener('click', () => {
        sharePop.hidden = !sharePop.hidden;
        shareBtn.setAttribute('aria-expanded', sharePop.hidden ? 'false' : 'true');
        if (!sharePop.hidden) updateShareLinks();
      });
      document.addEventListener('click', (e) => {
        if (!sharePop.hidden && !sharePop.contains(e.target) && e.target !== shareBtn && !shareBtn.contains(e.target)) {
          closeShare();
        }
      });
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !sharePop.hidden) {
          closeShare();
          shareBtn.focus();
        }
      });
      const copyBtn = $('tdCopyLink');
      if (copyBtn) copyBtn.addEventListener('click', async () => {
        const shareUrl = shareDetails().url;
        try {
          await navigator.clipboard.writeText(shareUrl);
          copyBtn.textContent = '✓ Link copied';
          copyBtn.style.color = '#2f5138';
          setTimeout(() => {
            copyBtn.textContent = 'Copy link';
            copyBtn.style.color = '';
            closeShare();
          }, 1400);
        } catch (e) {
          window.prompt(tt('trail.copyLink', null, 'Copy this link'), shareUrl);
        }
      });
    }

    const aboutFacts = $('aboutFacts');
    if (false && aboutFacts) {
      const facts = [
        ['paw', 'Comfortable underpaw', easyTerrain ? 'Paved and packed-gravel surfaces' : (t.terrainType || 'Mixed trail')],
        ['water', hasWater ? 'Water at the trailhead' : 'Bring water', hasWater ? 'Fill up before joining the route' : 'No source is listed on this route'],
        ['loop', 'Loop route', Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200 ? `${t.distance} km, back to the same parking area` : 'Check your return transport'],
        ['mountain', `${Math.max(...(t.elevationProfile || [{ elev: 0 }]).map(p => p.elev))} m altitude`, 'Mountain weather can change quickly'],
      ];
      aboutFacts.innerHTML = facts.map(([icon, title, sub]) => `<div class="about-fact">${svg(icon)}<span><b>${esc(title)}</b><small>${esc(sub)}</small></span></div>`).join('');
      
      // Add loop callout if it's a loop
      const isLoop = Array.isArray(t.path) && t.path.length > 1 && distMeters(t.path[0], t.path[t.path.length-1]) < 200;
      if (isLoop && $('loopCallout')) {
        if ($('loopCallout')) {
        $('loopCallout').innerHTML = `<div class="loop-callout" style="display: flex; gap: 8px; align-items: center; padding: 8px 10px; background: var(--sage-dim); border-radius: 8px; margin-bottom: 16px; border-left: 3px solid var(--success); font-size: 11px;">
          <svg style="width: 14px; height: 14px; flex: none; color: var(--success);" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M18 8a7 7 0 1 0 1 7M18 4v4h-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          <div style="color: var(--ink);"><b style="display: block; line-height: 1.2;">Loop</b><span style="color: var(--ink-soft); font-size: 10px;">${t.distance} km</span></div>
        </div>`;
      }
      }
    }

    const avatar = $('matchDogAvatar');
    const matchTitle = $('personalMatchTitle');
    const matchSummary = $('matchSummary');
    const personalScore = $('personalScore');
    const fallbackPaw = svg('paw');
    if (avatar) avatar.innerHTML = fallbackPaw;
    // The forecast is fetched separately and lands whenever it lands, so the
    // score is painted either with today's conditions or explicitly without
    // them -- never with a stale snapshot dressed up as live. scoringConditions
    // applies the shared thirty-minute expiry.
    // One accessor, so the same dog on the same trail gets the same number
    // wherever it is read. It answers for the trail asked about, so the nearby
    // picks are never handed this trail's weather. See scoring-conditions.js.
    function conditionsForScoring(subject) {
      const shared = window.ORMAScoringConditions;
      return shared ? shared.forTrail(subject || t) : undefined;
    }

    function paintPersonalMatch() {
      if (typeof recommendTrail !== 'function' || !window.DoloPawsAuth || !window.DoloPawsAuth.currentUser) return;
      window.DoloPawsAuth.getDogProfile().then(profile => {
        if (!profile) return;
        const name = profile.name || 'your dog';
        const recommendation = recommendTrail(
          t,
          typeof effectiveOverrides === 'function' ? effectiveOverrides(profile, null) : profile,
          conditionsForScoring()
        );
        const score = recommendation.score;
        // Reference action card: 96px conic ring on an #e6e0cf track, with
        // "MATCH FOR {NAME}" as the kicker and the breed line underneath.
        if (personalScore) {
          // The ring is the verdict, read as colour. Its own boundaries were
          // 70 and 50, so a score of 72 drew a green ring beside the words
          // "Possible with cautions" -- and colour is what a reader takes in
          // first. Same source as the words now, cut-offs and palette both.
          const ringVerdict = window.OrmaMatchVerdict
            ? window.OrmaMatchVerdict.verdictFor(recommendation)
            : null;
          const ringColor = ringVerdict ? ringVerdict.color : '#e6e0cf';
          personalScore.innerHTML =
            `<div class="td-ring" style="background:conic-gradient(${ringColor} ${Math.round((score / 100) * 360)}deg,#e6e0cf 0);">` +
            `<div class="td-ring-in">${t.curated === false ? '≈' : ''}${score}%</div></div>`;
          personalScore.dataset.scoringVersion = recommendation.scoringVersion;
          personalScore.dataset.recommendationCategory = recommendation.category;
          personalScore.dataset.recommendationConfidence = recommendation.confidence;
          personalScore.hidden = false;
        }
        const label = $('tdMatchLabel');
        if (label) {
          $('tdMatchName').textContent = 'MATCH FOR ' + name.toUpperCase();
          $('tdMatchBreed').textContent = profile.breed || '';
          label.hidden = false;
        }
        if (matchTitle) matchTitle.textContent = `Match for ${name}`;
        if (matchSummary) {
          // The verdict's words, and the line about how well it is known, both
          // come from match-verdict.js. This read from a copy of the table and
          // appended the confidence unconditionally, so an audited route said
          // "Strong option · high confidence" -- the confident case announcing
          // its confidence, which is what evidenceLine exists to stop.
          const verdict = window.OrmaMatchVerdict
            ? window.OrmaMatchVerdict.verdictFor(recommendation)
            : null;
          const qualifier = window.OrmaMatchVerdict
            ? window.OrmaMatchVerdict.evidenceLine({
              confidence: recommendation.confidence ? `${recommendation.confidence} confidence` : '',
            })
            : '';
          matchSummary.textContent = [verdict ? verdict.label : 'Personal recommendation', qualifier]
            .filter(Boolean).join(' · ');
          matchSummary.dataset.scoringVersion = recommendation.scoringVersion;
        }
        if (avatar && profile.photo) avatar.innerHTML = `<img src="${esc(profile.photo)}" alt="${esc(name)}">`;
      }).catch(() => {});
    }
    if (window.DoloPawsAuth) paintPersonalMatch();
    else window.addEventListener('dolopaws-auth-ready', paintPersonalMatch, { once: true });
    window.addEventListener('dolopaws-auth-changed', paintPersonalMatch);
    // The forecast usually arrives after the first paint. Without this the card
    // keeps a score calculated before the day was known.
    window.addEventListener('dolopaws-conditions-ready', paintPersonalMatch);

    // Trail description inside the white box
    const descEl = $('matchDescription');
    if (descEl && t.desc) {
      descEl.textContent = cardCopy(t.desc);
    }
    
    // In-page tabs: Overview / Dog safety / Reviews & photos.
    const tabsNav = $('trailTabsNav');
    if (tabsNav) {
      const panelIds = ['tabOverview', 'tabSafety', 'tabReviews'];
      const tabNames = {
        tabOverview: 'overview',
        tabSafety: 'safety',
        tabReviews: 'reviews'
      };
      const activateTab = (btn, historyMode) => {
        tabsNav.querySelectorAll('[data-tab]').forEach(b => {
          const on = b === btn;
          b.classList.toggle('active', on);
          b.setAttribute('aria-selected', on ? 'true' : 'false');
        });
        panelIds.forEach(id => {
          const panel = $(id);
          if (panel) panel.hidden = id !== btn.dataset.tab;
        });
        if (historyMode && window.history) {
          const url = new URL(window.location.href);
          const tabName = tabNames[btn.dataset.tab];
          if (tabName === 'overview') url.searchParams.delete('tab');
          else if (tabName) url.searchParams.set('tab', tabName);
          const target = url.pathname + url.search + url.hash;
          if (target !== window.location.pathname + window.location.search + window.location.hash) {
            if (historyMode === 'push') window.history.pushState({}, '', target);
            else window.history.replaceState({}, '', target);
          }
        }
      };

      tabsNav.querySelectorAll('[data-tab]').forEach(btn => {
        btn.addEventListener('click', () => activateTab(btn, 'push'));
      });

      const requestedTab = new URLSearchParams(window.location.search).get('tab');
      const requestedPanel = Object.keys(tabNames).find(id => tabNames[id] === requestedTab);
      const initialTab = requestedPanel
        ? tabsNav.querySelector('[data-tab="' + requestedPanel + '"]')
        : tabsNav.querySelector('[data-tab].active') || tabsNav.querySelector('[data-tab]');
      if (initialTab) activateTab(initialTab, false);
      window.addEventListener('popstate', () => {
        const tabName = new URLSearchParams(window.location.search).get('tab') || 'overview';
        const panelId = Object.keys(tabNames).find(id => tabNames[id] === tabName) || 'tabOverview';
        const tab = tabsNav.querySelector('[data-tab="' + panelId + '"]');
        if (tab) activateTab(tab, false);
      });
    }
  })();

  /* ---- Dog safety tab: Good/Caution rows from real trail fields ---- */
  (function safetyRows() {
    const box = $('dogSafetyRows');
    if (!box) return;
    const text = `${t.tips || ''} ${t.desc || ''} ${(t.surfaceHazards || []).join(' ')}`.toLowerCase();
    const hasWater = Array.isArray(t.waterSources) && t.waterSources.length > 0;
    const shade = typeof t.shadeCoverage === 'number' ? t.shadeCoverage : null;
    const maxAlt = Math.max(0, ...(t.elevationProfile || []).map(p => Number(p.elev) || 0));
    const rows = [];
    const caution = (title, sub, guideId) => rows.push({ title, sub, guideId });
    const addAssessment = (item, guideId) => {
      if (!item || item.ok) return;
      caution(item.title, item.detail, guideId);
    };

    addAssessment(trust ? trust.exposureAssessment(t) : (t.exposure
      ? { ok: false, title: 'Exposure', detail: 'Narrow ledges or unprotected drop-offs occur on parts of the route.' }
      : null), 'exposure');
    addAssessment(trust ? trust.livestockAssessment(t, text) : null, 'livestock');
    addAssessment(trust ? trust.surfaceAssessment(t) : (Number(t.terrainRank) !== 0
      ? { ok: false, title: 'Surface hazards', detail: (t.terrainType || 'Gravel and mixed rock') + '. Check pads at breaks; consider booties for tender paws.' }
      : null), 'paws');
    addAssessment(trust ? trust.heatAssessment(t) : null, 'heat');
    addAssessment(trust ? trust.waterAssessment(t) : (hasWater
      ? { ok: true, title: 'Water', detail: 'A water source is mapped on this route. Bring a bowl.' }
      : { ok: false, title: 'Water', detail: 'No water source is mapped. Carry enough for the dog.' }), 'water');
    if (maxAlt >= 1800) caution('Season & altitude', `Tops out around ${maxAlt} m. Snow lingers into early summer and weather turns quickly.`, 'altitude');

    if (!rows.length) {
      box.innerHTML = '<p class="safety-clear">No additional route cautions are highlighted. Continue to check live weather and local signs.</p>';
      return;
    }
    const rowMarkup = r => `
      <div class="safety-row is-caution"${r.guideId ? ` data-guide-id="${esc(r.guideId)}"` : ''}>
        <span class="pill">Caution</span>
        <span class="safety-row-copy"><b>${esc(r.title)}</b><small>${esc(r.sub)}</small></span>
      </div>`;
    box.innerHTML = rows.map(rowMarkup).join('');
  })();

  /* ---- Getting there + getting around, keep travel to the trailhead
     separate from the numbered waymarks used once the walk begins. ----- */
  (function parking() {
    const card = $('td2ParkingCard'), grid = $('td2ParkingGrid'), maps = $('td2MapsLink');
    const aroundCard = $('td2GettingAroundCard'), aroundGrid = $('td2GettingAroundGrid');
    if (!card || !grid || !aroundCard || !aroundGrid) return;
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const pin = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#2E4034" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 21s-7-5.5-7-11a7 7 0 0 1 14 0c0 5.5-7 11-7 11z"></path><circle cx="12" cy="10" r="2.5"></circle></svg>';
    const routeRefs = window.DoloPawsTrailRouteRefs
      ? window.DoloPawsTrailRouteRefs.forTrail(t)
      : [];
    const startLabel = cardCopy(sp.label || t.valley || t.area || 'the marked trailhead')
      // `Start here, Lift station Vinouve` -- the comma is part of the prefix,
      // and leaving it printed "Head to , Lift station Vinouve". trail-trust
      // strips the same prefix with `/^Start here\s*[,—-]\s*/i`; this copy of
      // the rule did not list the comma at all.
      .replace(/^Start here\s*[,.:;—–-]*\s*/i, '');
    const routeSequence = routeRefs.join(' → ');
    const hasSectionOnlyRefs = Array.isArray(t.routeRefSegments) && t.routeRefSegments.length > 0;
    const routeSwitches = window.DoloPawsTrailRouteRefs
      ? window.DoloPawsTrailRouteRefs.switchesForTrail(t)
      : [];
    const verifiedRouteGuidance = t.routeNumberGuidance && typeof t.routeNumberGuidance === 'object'
      ? t.routeNumberGuidance
      : null;
    const guidanceIsLandmarkLed = verifiedRouteGuidance && verifiedRouteGuidance.mode === 'landmarks';
    const routeBadges = routeRefs.length
      ? `<div class="td2-route-ref-list" aria-label="Trail numbers in order">${routeRefs.map((ref, index) =>
          `${index ? '<span class="td2-route-ref-arrow" aria-hidden="true">→</span>' : ''}<span class="td2-route-ref">${esc(ref)}</span>`
        ).join('')}</div>`
      : '';
    const switchGuidance = routeSwitches.length
      ? `<ol class="td2-route-switch-list">
          <li>Begin the hike on trail <b>${esc(routeSwitches[0].from)}</b>.</li>
          ${routeSwitches.map(item => {
            const atKm = item.km == null ? 'At the mapped junction' : `At approximately km ${esc(item.km.toFixed(1).replace(/\.0$/, ''))}`;
            const nearby = (Array.isArray(t.rifugi) ? t.rifugi : []).find(place =>
              Number.isFinite(Number(place && place.km)) && item.km != null && Math.abs(Number(place.km) - item.km) <= 0.15);
            return `<li>${atKm}${nearby ? `, near ${esc(nearby.name)}` : ''}, switch from trail <b>${esc(item.from)}</b> to trail <b>${esc(item.to)}</b>.</li>`;
          }).join('')}
          <li>Stay on trail <b>${esc(routeSwitches[routeSwitches.length - 1].to)}</b> for the final section to the route finish.</li>
        </ol>`
      : '';
    const noRouteNumbers = '<div class="s"><p><b>Trail numbers:</b> No verified numbered sequence is currently recorded for this route. Follow the mapped ORMA line and local destination signs.</p></div>';
    // The status sentence says whether ORMA confirmed how the numbers appear on
    // local signs -- what a reader standing at a junction needs. It was being
    // dropped, so the card stated a number sequence as though the signage were
    // settled. Printed when the record carries one: the five walks published
    // before the pipeline wrote that field have none.
    const guidanceStatus = verifiedRouteGuidance && String(verifiedRouteGuidance.status || '').trim();
    const routeRefMarkup = verifiedRouteGuidance
      ? `${routeBadges}<div class="s"><p><b>Start:</b> ${esc(verifiedRouteGuidance.start)}</p>${
        guidanceStatus ? `<p><b>Trail numbers:</b> ${esc(guidanceStatus)}</p>` : ''
      }<p><b>${guidanceIsLandmarkLed ? 'Route' : 'Trail numbers and route'}:</b> ${esc(verifiedRouteGuidance.sequence)}</p><p><b>${guidanceIsLandmarkLed ? 'Key turns' : 'Where to switch'}:</b> ${esc(verifiedRouteGuidance.switches)}</p></div>`
      : routeRefs.length
      ? `${routeBadges}${switchGuidance || `<div class="s">${hasSectionOnlyRefs
          ? `${routeRefs.length === 1 ? 'Trail' : 'Trails'} ${esc(routeSequence)} ${routeRefs.length === 1 ? 'is' : 'are'} marked only on the verified section${routeRefs.length === 1 ? '' : 's'} shown on the map. Follow the mapped ORMA line for the full route and confirm destination names at junctions.`
          : routeRefs.length === 1
            ? `Follow waymarked trail <b>${esc(routeRefs[0])}</b> along the mapped hike. No change to another numbered trail is recorded in the current route source; confirm destination names at junctions.`
            : `This hike uses trails ${esc(routeSequence)}, but the exact numbered switch point${routeRefs.length > 2 ? 's are' : ' is'} still awaiting verification. Follow the mapped ORMA line and local destination signs; do not rely on the number sequence alone.`}</div>`}`
      // Nothing sourced to say about following this route. This card used to
      // fall back to the first paragraph of t.desc, which "About this trail"
      // prints in full a few centimetres above: on 76 of 109 Dolomites trails
      // the visitor read the same sentence twice on one card. A route with no
      // recorded numbers says so, and says it once.
      : noRouteNumbers;
    const routeCard = {
      ic:'',
      t:verifiedRouteGuidance ? 'How to follow this route' : (routeSwitches.length ? 'Waymarked trail numbers and switches' : (routeRefs.length ? 'Waymarked trail numbers' : 'Following the route')),
      s:routeRefMarkup,
      routeRefs:true,
    };
    const renderCards = cards => cards.map(c => `<div class="td2-park${c.routeRefs ? ' td2-route-refs' : ''}"><span class="ic">${c.ic}</span><div><div class="t">${esc(c.t)}</div>${c.routeRefs ? c.s : `<div class="s">${c.s}</div>`}</div></div>`).join('');
    aroundGrid.innerHTML = routeRefMarkup ? renderCards([routeCard]) : '';
    aroundCard.hidden = !routeRefMarkup;
    if (typeof lat !== 'number' || typeof lng !== 'number') {
      grid.innerHTML = renderCards([{
        ic:pin,
        t:'Recommended starting point',
        s:'Trailhead directions are not yet available for this route.',
      }]);
      if (maps) maps.hidden = true;
      card.hidden = false;
      return;
    }
    const cards = [{
      ic:pin,
      t:'Recommended starting point',
      s:`Head to ${esc(startLabel)}. Use the directions link to navigate to the route start.`,
    }];
    grid.innerHTML = renderCards(cards);
    if (maps) maps.hidden = false;
    wireTrailheadDirections(maps, $('td2MapsStatus'));
    card.hidden = false;
  })();

  /* ---- Sticky sidebar: today's conditions + walking forecast --------
     Reference markup, real Open-Meteo data at the trailhead. ---------- */
  (function sidebar() {
    const sp = t.startPoint || {};
    const lat = typeof sp.lat === 'number' ? sp.lat : t.lat;
    const lng = typeof sp.lng === 'number' ? sp.lng : t.lng;
    const condCard = $('tdConditions'), fcCard = $('sideForecast'), fcDays = $('tdForecastDays');
    const publishWeather = detail => {
      window.DoloPawsWeatherSnapshot = detail;
      window.dispatchEvent(new CustomEvent('dolopaws-weather-ready', { detail }));
    };
    if (typeof lat !== 'number') {
      publishWeather({ status: 'unavailable', capturedAt: Date.now() });
      return;
    }

    const valleyEl = $('sideFcValley');
    if (valleyEl) valleyEl.textContent = (t.valley || t.area) ? '· ' + (t.valley || t.area) : '';

    const WMO = (c) => c === 0 ? 'Clear' : c <= 2 ? 'Mostly clear' : c === 3 ? 'Overcast'
      : c <= 48 ? 'Fog' : c <= 57 ? 'Drizzle' : c <= 67 ? 'Rain' : c <= 77 ? 'Snow'
      : c <= 82 ? 'Showers' : c <= 86 ? 'Snow showers' : 'Thunderstorms';

    // Prototype weather glyphs: a sun for clear/mostly-clear, a cloud otherwise.
    const SUN = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#E8A93A" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4.2" fill="#F7C96B" stroke="none"></circle><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5 5l1.4 1.4M17.6 17.6L19 19M19 5l-1.4 1.4M6.4 17.6L5 19"></path></svg>';
    const CLOUD = '<svg width="18" height="16" viewBox="0 0 24 24" fill="#B7C6C9"><path d="M7 18h10a4 4 0 0 0 .5-7.97A5.5 5.5 0 0 0 6.5 9 4 4 0 0 0 7 18z"></path></svg>';
    const iconFor = (code) => code <= 2 ? SUN : CLOUD;
    // Paw-safety badge from the day's high (same thresholds as the score's heat rules).
    const dayBadge = (hi) => hi >= 22 ? { t: 'Heat', bg: '#F5E4C6', fg: '#8A5A16' } : { t: 'Good', bg: '#E4EADF', fg: '#2C5C34' };

    fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lng}&current=temperature_2m,weathercode&daily=weathercode,temperature_2m_max,temperature_2m_min,precipitation_probability_max,sunrise,sunset&hourly=temperature_2m&forecast_days=6&timezone=auto`)
      .then(r => r.json())
      .then(d => {
        if (!d || !d.daily) {
          publishWeather({ status: 'unavailable', capturedAt: Date.now() });
          return;
        }
        publishWeather({
          status: 'ready',
          capturedAt: Date.now(),
          temperatureC: d.current && d.current.temperature_2m,
          trailId: t.id,
        });
        // ---- Today's conditions card ----
        if (d.current) {
          const cur = Math.round(d.current.temperature_2m);
          const tempEl = $('tdCondTemp');
          if (tempEl) tempEl.textContent = cur + '°C';
          const paw = cur >= 28 ? { t: 'Caution', bg: '#F3D9D2', fg: '#9C3A25' }
            : cur >= 22 ? { t: 'Warm', bg: '#F5E4C6', fg: '#8A5A16' }
            : { t: 'Good', bg: '#E4EADF', fg: '#2C5C34' };
          const pawEl = $('tdCondPaw');
          if (pawEl) { pawEl.textContent = paw.t; pawEl.style.background = paw.bg; pawEl.style.color = paw.fg; }
          // The day the reader chose on the homepage, carried in the address.
          // Six days of hourly data are already in hand, so answering for
          // Saturday costs no extra request -- only the decision to use it.
          const planned = window.ORMAPlannedWalkDate || '';
          const win = window.DoloPawsWeatherWindow
            ? window.DoloPawsWeatherWindow.recommendation({
              currentTime:d.current.time,
              durationHours:t.hours,
              dailyDates:d.daily.time,
              sunrises:d.daily.sunrise,
              sunsets:d.daily.sunset,
              hourlyTimes:d.hourly && d.hourly.time,
              hourlyTemps:d.hourly && d.hourly.temperature_2m,
              preferredDate:planned,
            })
            : null;
          // Today's heat, in the vocabulary the recommendation engine reads.
          // Until now nothing supplied currentConditions, so the score never
          // reflected the day it was being read on.
          if (window.DoloPawsWeatherWindow) {
            // For a future day the reference point is that day's forecast, not
            // the temperature outside right now -- otherwise the score answers
            // a different question from the start time beside it.
            const plannedHours = planned
              ? (d.hourly && d.hourly.time || []).map((time, index) => ({
                time, temp:Number(d.hourly.temperature_2m[index]),
              })).filter(point => String(point.time).startsWith(`${planned}T`) && Number.isFinite(point.temp))
              : [];
            const reference = plannedHours.length
              ? (plannedHours.find(point => String(point.time).slice(11, 16) === '09:00') || plannedHours[0])
              : null;
            const conditions = window.DoloPawsWeatherWindow.currentConditions(reference ? {
              currentTime:reference.time,
              temperatureC:reference.temp,
              hourlyTimes:plannedHours.map(point => point.time),
              hourlyTemps:plannedHours.map(point => point.temp),
            } : {
              currentTime:d.current.time,
              temperatureC:d.current.temperature_2m,
              hourlyTimes:d.hourly && d.hourly.time,
              hourlyTemps:d.hourly && d.hourly.temperature_2m,
            });
            window.DoloPawsCurrentConditions = conditions;
            // Say which trail this forecast was fetched for, so nothing hands
            // it to a different one.
            if (window.ORMAScoringConditions) window.ORMAScoringConditions.declareForTrail(t.id, conditions);
            window.dispatchEvent(new CustomEvent('dolopaws-conditions-ready', { detail:conditions }));
          }

          const winEl = $('sideCondWindow');
          if (winEl) winEl.innerHTML = window.DoloPawsWeatherWindow
            ? window.DoloPawsWeatherWindow.markup(win)
            : 'No route-length daylight recommendation is available. Check the official forecast and plan to finish well before dusk.';
        }
        const hasWater = Array.isArray(t.waterSources) && t.waterSources.length > 0;
        const waterEl = $('tdCondWater');
        if (waterEl) { waterEl.textContent = hasWater ? 'On route' : 'Carry own'; waterEl.style.color = hasWater ? '#BDEBD9' : '#FFE6A6'; }
        if (condCard) condCard.hidden = false;

        // ---- 6-day forecast card ----
        if (fcDays) {
          let heatDay = null;
          fcDays.innerHTML = d.daily.time.map((iso, i) => {
            const label = i === 0 ? 'Today' : new Date(iso).toLocaleDateString(undefined, { weekday: 'short' });
            const hi = Math.round(d.daily.temperature_2m_max[i]);
            const lo = Math.round(d.daily.temperature_2m_min[i]);
            const b = dayBadge(hi);
            if (b.t === 'Heat' && !heatDay) heatDay = i === 0 ? 'Today' : new Date(iso).toLocaleDateString(undefined, { weekday: 'long' });
            return `<div class="td2-fcday${i ? ' brd' : ''}">`
              + `<span class="d${i ? '' : ' now'}">${label}</span>`
              + `<span class="ic">${iconFor(d.daily.weathercode[i])}</span>`
              + `<span class="tp"><b class="num">${hi}°</b> <span class="lo">${lo}°</span></span>`
              + `<span class="bd"><span class="td2-badge" style="background:${b.bg};color:${b.fg};">${b.t}</span></span>`
              + `</div>`;
          }).join('');
          const noteEl = $('tdForecastNote');
          if (noteEl && heatDay) {
            noteEl.innerHTML = `<b style="color:#8A5A16">${heatDay}</b> is warm. Walk early and carry extra water.`;
            noteEl.hidden = false;
          }
        }
        if (fcCard) fcCard.hidden = false;
      })
      .catch(() => publishWeather({ status: 'unavailable', capturedAt: Date.now() }));
  })();
})();
;

// ---- trail-detail-ui.js ----
/**
 * trail-detail-ui.js, small UI glue for the redesigned (single-scroll,
 * Strava-style) trail detail page. Self-contained: it only reads state the
 * other modules already own and reflects it into the new markup. No data
 * layer of its own. Runs only on pages that use the `.td2` layout.
 *
 * Responsibilities:
 *   1. Hero "Start the hike" button proxies hike-mode.js's map button, and a
 *      live recording banner mirrors the hike state.
 *   2. "Active now" pill on the hazards card follows #trailFlagsList content.
 *   3. Relevant section headings are personalised with the active dog's name.
 */
(function () {
  'use strict';
  if (!document.querySelector('.td2')) return;

  // ---- 1. Hero Start-the-hike proxy + live banner -------------------------
  const heroBtn = document.getElementById('heroStartHike');
  const liveBanner = document.getElementById('td2LiveBanner');
  const mapBox = document.getElementById('trailMapBox');
  const hikeHome = heroBtn && heroBtn.parentElement;
  const hikeNext = heroBtn && heroBtn.nextSibling;

  function placeHikeAction() {
    if (!heroBtn || !hikeHome) return;
    if (heroBtn.parentElement !== hikeHome) {
      hikeHome.insertBefore(heroBtn, hikeNext);
    }
  }
  placeHikeAction();

  function recording() {
    return !!(mapBox && mapBox.classList.contains('hike-status-visible'));
  }

  // Live progress mirrored from hike-mode (elapsed clock + km walked), shown
  // in the banner and in the hero End button ("End · 12:34", per prototype).
  let hikeStartedAt = null;
  let elapsedTimer = null;
  function fmtElapsed() {
    if (!hikeStartedAt) return '0:00';
    const s = Math.max(0, Math.floor((Date.now() - hikeStartedAt) / 1000));
    const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
    return h ? h + ':' + String(m).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0')
             : m + ':' + String(s % 60).padStart(2, '0');
  }
  function tickElapsed() {
    const el = document.getElementById('tdLiveElapsed');
    if (el) el.textContent = fmtElapsed();
    if (heroBtn && heroBtn.classList.contains('recording')) {
      const t = heroBtn.querySelector('.hike-elapsed');
      if (t) t.textContent = fmtElapsed();
    }
  }
  window.addEventListener('dolopaws-hike-progress', function (e) {
    hikeStartedAt = (e.detail && e.detail.startedAt) || hikeStartedAt;
    const dist = document.getElementById('tdLiveDist');
    if (dist && e.detail && typeof e.detail.km === 'number') dist.textContent = e.detail.km.toFixed(1) + ' km';
    if (!elapsedTimer) elapsedTimer = setInterval(tickElapsed, 1000);
    tickElapsed();
  });

  function syncHike() {
    const mapBtn = document.getElementById('mapStartHikeBtn');
    const rec = recording();
    if (heroBtn) {
      const nextHidden = !mapBtn;
      if (heroBtn.hidden !== nextHidden) heroBtn.hidden = nextHidden;
      heroBtn.classList.toggle('recording', rec);
      // The map observer calls syncHike whenever hike mode changes. Replacing
      // identical markup on every callback creates
      // a self-triggering mutation loop that locks the page. Only rewrite the
      // button when its actual state changes.
      const nextState = rec ? 'recording' : 'idle';
      if (heroBtn.dataset.hikeUiState !== nextState) {
        heroBtn.dataset.hikeUiState = nextState;
        heroBtn.innerHTML = rec
          ? '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/></svg> End · <span class="hike-elapsed">' + fmtElapsed() + '</span>'
          : '<svg width="13" height="13" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg> Start the hike';
      }
    }
    if (liveBanner) liveBanner.hidden = !rec;
    if (!rec && elapsedTimer) { clearInterval(elapsedTimer); elapsedTimer = null; hikeStartedAt = null; }
  }
  if (heroBtn) {
    heroBtn.addEventListener('click', function () {
      const mapBtn = document.getElementById('mapStartHikeBtn');
      if (mapBtn) mapBtn.click();
    });
  }
  if (mapBox) {
    // hike-mode.js injects #mapStartHikeBtn and toggles .hike-status-visible.
    new MutationObserver(syncHike).observe(mapBox, {
      attributes: true, attributeFilter: ['class'], childList: true, subtree: true,
    });
  }
  // Poll briefly until hike-mode has injected its button, then let the
  // observer take over.
  let tries = 0;
  const iv = setInterval(function () {
    syncHike();
    if (document.getElementById('mapStartHikeBtn') || ++tries > 40) clearInterval(iv);
  }, 250);
  syncHike();

  // ---- 2. "Active now" hazard pill + section counts ----------------------
  const flags = document.getElementById('trailFlagsList');
  const hazardCard = document.getElementById('td2Hazards');
  const photos = document.getElementById('trailPhotosList');
  const reviews = document.getElementById('trailReviewsList');

  // Count real items in a list (children that aren't the empty-state block).
  function itemCount(list) {
    if (!list) return 0;
    if (list.querySelector('.empty-state')) return 0;
    return list.children.length;
  }
  function setCount(id, n) {
    const el = document.getElementById(id);
    if (el) el.textContent = n > 0 ? ' · ' + n : '';
  }
  function syncHazards() {
    if (!flags) return;
    const publicCount = flags.querySelectorAll('[data-hazard-item]').length;
    const pendingCount = flags.querySelectorAll('[data-hazard-pending]').length;
    const empty = document.getElementById('trailHazardsEmpty');
    if (hazardCard) hazardCard.classList.toggle('has-active', publicCount > 0);
    if (empty) empty.hidden = publicCount + pendingCount > 0;
    setCount('td2HazardCount', publicCount);
  }
  function syncCounts() {
    const pc = itemCount(photos);
    setCount('td2PhotoCount', pc);
    const rc = itemCount(reviews);
    setCount('td2ReviewCount', rc);
    const photoCard = document.getElementById('td2PhotosCard');
    const reviewCard = document.getElementById('td2ReviewsCard');
    if (photoCard) photoCard.classList.toggle('is-empty', pc === 0);
    if (reviewCard) reviewCard.classList.toggle('is-empty', rc === 0);
    // Average rating from the rendered review ratings (aria-label "X out of 5").
    const avgEl = document.getElementById('td2ReviewAvg');
    if (avgEl && reviews) {
      const rated = [].map.call(reviews.querySelectorAll('.community-review__rating[aria-label]'), function (r) {
        const m = (r.getAttribute('aria-label') || '').match(/([\d.]+)\s*out of\s*5/i);
        return m ? parseFloat(m[1]) : null;
      }).filter(function (v) { return v != null; });
      if (rated.length) {
        const avg = rated.reduce(function (a, b) { return a + b; }, 0) / rated.length;
        avgEl.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style="flex:none;"><path d="M12 2.5l2.9 6.1 6.6.8-4.9 4.5 1.3 6.6L12 18l-5.9 3.1 1.3-6.6L2.5 9.4l6.6-.8z"/></svg> ' + avg.toFixed(1);
        avgEl.hidden = false;
      } else { avgEl.hidden = true; }
    }
  }
  if (flags) { new MutationObserver(syncHazards).observe(flags, { childList: true, subtree: true }); syncHazards(); }
  window.addEventListener('orma-hazards-changed', syncHazards);
  if (photos) { new MutationObserver(syncCounts).observe(photos, { childList: true, subtree: true }); }
  if (reviews) { new MutationObserver(syncCounts).observe(reviews, { childList: true, subtree: true }); }
  syncCounts();

  // ---- 3. Personalise section headers with the dog's name ----------------
  // (The sidebar dog card with its own match % is gone, the hero already
  // shows "N% match for <dog>", so repeating it below was redundant.)
  function syncDog() {
    let name = '';
    try {
      const s = JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null');
      if (s && s.hasProfile) name = s.name || '';
    } catch (e) { /* private mode, no summary */ }

    const safetyDog = document.getElementById('td2SafetyDog');
    if (safetyDog) safetyDog.textContent = name ? ' · ' + name : '';
    const nearbyTitle = document.getElementById('nearbyTitle');
    if (nearbyTitle && name) nearbyTitle.textContent = 'Nearby trails, ranked for ' + name;
    const liveTitle = document.getElementById('tdLiveTitle');
    if (liveTitle && name) liveTitle.textContent = 'Recording ' + name + '’s walk';
  }
  window.addEventListener('dolopaws-auth-changed', syncDog);
  syncDog();
})();
;

// ---- trail-mobile.js ----
/* Mobile app layout for the logged-in trail detail (≤700px), ported from
   the Claude Design prototype "ORMA Trail Detail (Logged in) - Mobile".

   Same pattern as homepage-mobile.js: purely additive chrome on top of the
   desktop .td2 layout. Injects a compact top bar (back · brand · dog
   avatar) and a scroll progress bar. The complete set of
   real trail actions stays in the hero, so mobile has the same capabilities
   as desktop without mirrored handlers. All visual re-layout lives in
   trail-mobile.css under
   body.mtrail-active. Activates only for signed-in visitors (the same
   dolopaws-profile-summary signal trail-detail-ui.js already uses); guests
   keep the plain responsive page. */
(function(){
  'use strict';

  var page = document.querySelector('.td2');
  if(!page) return;

  var mq = window.matchMedia('(max-width:700px)');
  var active = false;
  var weather = document.querySelector('.td2-hero-weather');
  var weatherHome = weather && weather.parentElement;
  var weatherNext = weather && weather.nextSibling;
  var about = document.getElementById('td2AboutCard');
  var aboutHome = about && about.parentElement;
  var aboutNext = about && about.nextSibling;
  var offlinePanel = document.getElementById('offlinePackagePanel');
  var offlineHome = offlinePanel && offlinePanel.parentElement;
  var offlineNext = offlinePanel && offlinePanel.nextSibling;

  function placeWeather(){
    var slot = document.getElementById('mobileWeatherSlot');
    if(!weather || !weatherHome || !slot) return;
    if(mq.matches && weather.parentElement !== slot) slot.appendChild(weather);
    if(!mq.matches && weather.parentElement !== weatherHome){
      weatherHome.insertBefore(weather, weatherNext);
    }
  }

  function placeDownloadAction(){
    var row = document.querySelector('.td2-actrow');
    if(!offlinePanel || !offlineHome || !row) return;
    if(mq.matches && offlinePanel.parentElement !== row){
      row.insertBefore(offlinePanel, row.firstChild);
    }
    if(!mq.matches && offlinePanel.parentElement !== offlineHome){
      offlineHome.insertBefore(offlinePanel, offlineNext);
    }
  }

  function placeAboutAfterRecommendation(){
    var recommendation = document.getElementById('recommendationDecision');
    if(!about || !aboutHome || !recommendation || !recommendation.parentElement) return;
    if(about.previousElementSibling !== recommendation){
      recommendation.insertAdjacentElement('afterend', about);
    }
  }

  function restoreAbout(){
    if(!about || !aboutHome || about.parentElement === aboutHome) return;
    if(aboutNext && aboutNext.parentElement === aboutHome) aboutHome.insertBefore(about, aboutNext);
    else aboutHome.appendChild(about);
  }

  function initMobileDisclosures(){
    document.querySelectorAll('.td2-mobile-card-toggle').forEach(function(button){
      if(button.dataset.mobileDisclosureReady === 'true') return;
      button.dataset.mobileDisclosureReady = 'true';
      button.addEventListener('click', function(){
        var card = button.closest('.td2-mobile-collapsible');
        if(!card) return;
        var collapsed = card.classList.toggle('is-mobile-collapsed');
        button.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        var action = button.querySelector('.td2-mobile-toggle-action');
        if(action) action.innerHTML = (collapsed ? 'Show <span aria-hidden="true">⌄</span>' : 'Hide <span aria-hidden="true">⌃</span>');
      });
    });
  }

  function profileSummary(){
    try { return JSON.parse(localStorage.getItem('dolopaws-profile-summary') || 'null'); }
    catch(e){ return null; }
  }
  function signedIn(){
    if(window.DoloPawsAuth && window.DoloPawsAuth.currentUser) return true;
    // Same dev-preview contract as the homepage (?view=returning).
    try { if(new URLSearchParams(window.location.search).get('view') === 'returning') return true; } catch(e){}
    var s = profileSummary();
    return !!(s && s.hasProfile);
  }

  function dogAvatarHtml(){
    var s = profileSummary();
    var active = s && Array.isArray(s.dogs)
      ? (s.dogs.find(function(dog){ return dog.id === s.activeDogId; }) || s.dogs[0])
      : null;
    var name = active && active.name ? String(active.name) : (s && s.name ? String(s.name) : '');
    var photo = active && typeof active.photo === 'string' && active.photo.indexOf('data:image/') === 0
      ? active.photo : null;
    if(photo) return '<span class="av" style="background-image:url(' + photo + ')" aria-hidden="true"></span>';
    return '<span class="av" aria-hidden="true">' + (name ? name.charAt(0).toUpperCase() : '🐾') + '</span>';
  }

  function ensureUi(){
    if(!document.getElementById('mtrailTop')){
      var top = document.createElement('div');
      top.className = 'mtrail-top';
      top.id = 'mtrailTop';
      top.innerHTML =
        '<a class="back" href="browse-trails.html">← <span>Trails</span></a>' +
        '<a class="brand" href="/"><img src="logo.svg" alt="">ORMA</a>' +
        '<a class="avlink" href="account.html" aria-label="Your account">' + dogAvatarHtml() + '</a>' +
        '<div class="mtrail-progress" aria-hidden="true"><span id="mtrailProgress"></span></div>';
      document.body.insertBefore(top, document.body.firstChild);
    }
  }

  function measure(){
    var top = document.getElementById('mtrailTop');
    if(top) document.body.style.setProperty('--mtrail-top', top.offsetHeight + 'px');
  }

  function onScroll(){
    if(!active) return;
    var fill = document.getElementById('mtrailProgress');
    if(!fill) return;
    var doc = document.documentElement;
    var max = (doc.scrollHeight - window.innerHeight) || 1;
    var pct = Math.max(0, Math.min(1, (window.scrollY || doc.scrollTop || 0) / max));
    fill.style.width = (pct * 100).toFixed(1) + '%';
  }

  function activate(){
    if(active) return;
    active = true;
    ensureUi();
    placeAboutAfterRecommendation();
    document.body.classList.add('mtrail-active');
    measure();
    setTimeout(function(){ if(active){ measure(); onScroll(); } }, 120);
  }

  function deactivate(){
    if(!active) return;
    active = false;
    restoreAbout();
    document.body.classList.remove('mtrail-active');
    document.body.style.removeProperty('--mtrail-top');
  }

  function update(){
    initMobileDisclosures();
    placeWeather();
    placeDownloadAction();
    if(mq.matches && signedIn()) activate();
    else deactivate();
  }

  if(mq.addEventListener) mq.addEventListener('change', update);
  else if(mq.addListener) mq.addListener(update);
  window.addEventListener('dolopaws-auth-changed', function(){ setTimeout(update, 0); });
  window.addEventListener('resize', function(){ update(); if(active) measure(); });
  window.addEventListener('scroll', onScroll, { passive: true });

  update();
})();
;

// ---- recommendation-decision.js ----
(function(root, factory){
  const api = factory(root);
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.DoloPawsRecommendationDecision = api;
})(typeof window !== 'undefined' ? window : globalThis, function(root){
  'use strict';

  const CATEGORY = Object.freeze({
    'strong-option': { label:'Strong option', tone:'strong' },
    'possible-with-cautions': { label:'Possible with cautions', tone:'caution' },
    'not-recommended': { label:'Not recommended', tone:'stop' },
  });

  // `extra` carries what the engine does not know, such as the dog's name, so
  // a translation can say "fine for Teo" where the engine said "this dog".
  function translatedMessage(item, translate, extra){
    if(!(item && item.message)) return '';
    if(typeof translate !== 'function') return item.message;
    const key = `recommendation.reason.${item.messageKey || item.code}`;
    const vars = extra || item.vars ? { ...(extra || {}), ...(item.vars || {}) } : undefined;
    const value = translate(key, vars);
    return value && value !== key ? value : item.message;
  }

  function messages(items, translate, extra){
    return (Array.isArray(items) ? items : [])
      .map(item => translatedMessage(item, translate, extra))
      .filter(Boolean);
  }

  // A positive that cost nothing is not worth a sentence of its own. These
  // are the short forms that let the card say "Fine for Teo: the 7.5 km
  // distance, the 150 m climb and today's temperatures." in one line. A
  // positive without a short form keeps its own row.
  const FINE_PHRASES = Object.freeze({
    'trail.distance.within-range': 'the {distance} km distance',
    'trail.ascent.within-range': 'the {ascent} m climb',
    'trail.terrain.within-tolerance': 'the terrain',
    'trail.duration.within-preference': 'the walking time',
    'conditions.heat.low': 'today’s temperatures',
    'trail.heat.low': 'heat exposure',
    'trail.shade.good': 'shade',
    'trail.exposure.none-known': 'no exposed sections',
    'trail.surface-hazards.none-known': 'no recorded surface hazards',
    'trail.water.reviewed': 'water on the route',
    'trail.dog-access.allowed': 'dog access',
    'trail.dog-access.leash': 'dog access on a leash',
    'trail.livestock.none': 'no livestock recorded',
    'trail.wildlife.low': 'low wildlife activity',
    'trail.road.none': 'no road sections',
    'trail.crowding.quiet': 'a quiet route',
    'trail.sightlines.open': 'open sightlines',
  });

  /**
   * The same positives as whole sentences, for a card that lists them instead
   * of folding them into one line.
   *
   * The homepage card shows "Why it fits Teo" beside "What to know today", and
   * the second column is short sentences -- "No confirmed water on the route,
   * so carry it all." Joining the phrases above under that heading produced a
   * seven-item fragment with no verb in it, so the two columns read as two
   * different voices on one card.
   *
   * No name in them. The heading already says who it fits, and the fold-line
   * above was written to stop the name landing twice in eleven words; once per
   * bullet would be worse. The heading binds the subject, so "The terrain is
   * manageable." is read as manageable *for this dog*, which is what the
   * engine actually said -- these are per-dog fit statements, never claims
   * about the trail in the abstract.
   *
   * "recorded" stays wherever the phrase above has it. Mapped absence of a
   * hazard is not evidence the hazard is absent, and the sentence must not
   * quietly upgrade it.
   */
  const FIT_SENTENCES = Object.freeze({
    'trail.distance.within-range': 'The {distance} km distance is comfortable.',
    'trail.ascent.within-range': 'The {ascent} m climb is gentle.',
    'trail.terrain.within-tolerance': 'The terrain is manageable.',
    'trail.duration.within-preference': 'The walking time fits.',
    'conditions.heat.low': 'Today is cool enough.',
    'trail.heat.low': 'The route does not get too hot.',
    'trail.shade.good': 'There is good shade.',
    'trail.exposure.none-known': 'No exposed sections are recorded.',
    'trail.surface-hazards.none-known': 'No surface hazards are recorded.',
    'trail.water.reviewed': 'There is water on the route.',
    'trail.dog-access.allowed': 'Dogs are allowed.',
    'trail.dog-access.leash': 'Dogs are allowed on a leash.',
    'trail.livestock.none': 'No livestock is recorded.',
    'trail.wildlife.low': 'Wildlife activity is low.',
    'trail.road.none': 'There are no road sections.',
    'trail.crowding.quiet': 'The route is usually quiet.',
    'trail.sightlines.open': 'The sightlines are open.',
  });

  // Calm framing: confidence describes data completeness, not danger. "low"
  // must not read as a warning, missing data never lowers the score. The words
  // live in match-verdict.js, beside the rule about when they are worth saying
  // -- this file held the only copy that agreed with them, and the homepage
  // held one that did not.
  function confidenceWords(level, translate){
    const shared = root && root.OrmaMatchVerdict;
    return shared ? shared.confidenceLabel(level, translate) : '';
  }

  function present(recommendation, context){
    recommendation = recommendation || {};
    context = context || {};
    const category = CATEGORY[recommendation.category] || {
      label:'Recommendation unavailable',
      tone:'unknown',
    };
    const translate = context.translate;
    const tr = (key, fallback, vars) => {
      if(typeof translate === 'function'){
        const value = translate(key, vars);
        if(value && value !== key) return value;
      }
      let output = fallback;
      for(const name of Object.keys(vars || {})){
        output = output.split(`{${name}}`).join(vars[name]);
      }
      return output;
    };
    // Only four reasons and four cautions reach the card, so what survives the
    // cut decides whether the explanation reads as specific to this dog or as
    // boilerplate. The engine emits in calculation order, which puts every
    // behaviour and positioned advisory last, exactly the lines worth
    // showing. Rank before slicing; ties keep the engine's own order.
    const rank = (tiers, fallback) => item => {
      const code = typeof item.code === 'string' ? item.code : '';
      const index = tiers.findIndex(tier => tier.some(prefix => code.startsWith(prefix)));
      return index === -1 ? fallback : index;
    };
    const ordered = (items, tiers, fallback) => {
      const score = rank(tiers, fallback);
      return items
        .map((item, index) => ({ item, index, tier:score(item) }))
        .sort((a, b) => a.tier - b.tier || a.index - b.index)
        .map(entry => entry.item);
    };

    const REASON_TIERS = [
      // What the owner asked for: does this route fit this dog, this walk?
      ['trail.distance.within-range', 'trail.duration.within-preference'],
      // Present properties an owner plans around, and that are true of this
      // dog in particular.
      ['trail.sightlines.', 'trail.water.reviewed'],
      // Absences rank below presences: "no livestock recorded" is weaker
      // information than "water at two points", and reads as filler when it
      // crowds out a fact the owner can act on.
      ['trail.livestock.none', 'trail.wildlife.low', 'trail.road.none',
        'trail.crowding.quiet', 'trail.dog-access.'],
    ];
    const CAUTION_TIERS = [
      // Route facts that can end a walk.
      ['trail.dog-access.', 'trail.exposure.present', 'trail.terrain.above-tolerance',
        'segment.avoid'],
      // Positioned and behavioural: specific, and actionable on the day.
      ['segment.', 'trail.livestock.', 'trail.wildlife.', 'trail.road.',
        'trail.sightlines.', 'trail.crowding.'],
    ];
    const dogName = String(context.dogName || '').trim();
    const subject = dogName || tr('recommendation.subject.guest', 'a medium dog');
    const extra = { name:subject };

    const codesOf = items => new Set((Array.isArray(items) ? items : [])
      .filter(Boolean).map(item => item.code).filter(Boolean));
    const positiveCodes = codesOf(recommendation.positiveReasons);
    const stopCodes = codesOf(recommendation.hardStops);
    const kindOf = entry => stopCodes.has(entry.code) ? 'stop'
      : positiveCodes.has(entry.code) ? 'positive'
      : 'caution';

    const allFactors = (Array.isArray(recommendation.factors) ? recommendation.factors : [])
      .filter(entry => entry && typeof entry.message === 'string');
    const floorEntry = allFactors.find(entry => entry.code === 'score.floor') || null;
    const breakdownFactors = allFactors
      .filter(entry => entry !== floorEntry)
      .map(entry => ({
        impact:Number.isFinite(entry.impact) ? entry.impact : 0,
        message:translatedMessage(entry, translate, extra),
        code:entry.code,
        kind:kindOf(entry),
      }));
    // The rows the card lists one by one, and the positives it folds into a
    // single "fine for" line. Cost rows keep their points; a positive stays a
    // row only when it has no short form.
    const finePhrase = entry => {
      const fallback = FINE_PHRASES[entry.code];
      if(!fallback) return null;
      return tr(`recommendation.fine.${entry.code}`, fallback, { ...extra, ...(entry.vars || {}) });
    };
    const fitSentence = entry => {
      const fallback = FIT_SENTENCES[entry.code];
      if(!fallback) return null;
      return tr(`recommendation.fits.${entry.code}`, fallback, { ...extra, ...(entry.vars || {}) });
    };
    /**
     * What the card leads with, when it can only show a few.
     *
     * The engine emits positives in calculation order and every one of them
     * costs nothing, so that order ranks nothing -- taking the first four was
     * taking an arbitrary four. These are not equally worth the space:
     * VERIFICATION.md states the rule this follows, that "a long or hot route
     * with no mapped water is the single interaction that most often harms
     * dogs". Heat and water are the two an owner most needs to see confirmed,
     * and shade is the heat half of that pair, so they go first.
     *
     * Then what the owner actually asked for -- how far, how long, how steep,
     * what underfoot. Everything else keeps the engine's order behind them,
     * which preserves the existing principle that absences rank below
     * presences without restating it.
     *
     * Ordering only, never selection: nothing is added or dropped here, and
     * ties keep the engine's own order.
     */
    const FIT_TIERS = [
      ['trail.water.', 'conditions.heat.', 'trail.heat.', 'trail.shade.'],
      ['trail.distance.', 'trail.duration.', 'trail.ascent.', 'trail.terrain.'],
    ];
    const foldable = [];
    const rows = [];
    for(const entry of breakdownFactors){
      const source = allFactors.find(factor => factor.code === entry.code) || entry;
      const phrase = entry.kind === 'positive' && entry.impact >= 0 ? finePhrase(source) : null;
      if(phrase){
        // Phrase and sentence are taken together, so a positive that has one
        // and not the other cannot silently vanish from whichever list renders.
        foldable.push({ code:entry.code, phrase, sentence:fitSentence(source) || phrase });
      }
      else rows.push(entry);
    }
    // fine keeps the engine's order, because fineLine is a prose sentence on
    // the trail page and reordering it would rewrite that page's wording.
    // fits is the card's list and is ordered for what the card has to do:
    // show the few that matter when it cannot show them all.
    const fine = foldable.map(item => item.phrase);
    /**
     * The heat-and-water cluster leads, but it does not take the whole lead.
     *
     * On a route that is cool, shaded and watered, all three are positives and
     * they filled every slot the card shows -- so a reader learned three ways
     * of saying the walk will not overheat the dog and nothing about how far
     * or how steep it is. Two makes the point; the third says it again.
     *
     * The surplus is demoted, never dropped, so the card still carries every
     * positive and the trail page's full line is unchanged. This stays an
     * ordering, which is the property the tests hold it to.
     */
    const FIT_CLUSTER_LEAD = 2;
    const inCluster = item => FIT_TIERS[0].some(prefix => item.code.startsWith(prefix));
    const ranked = ordered(foldable, FIT_TIERS, FIT_TIERS.length);
    const cluster = ranked.filter(inCluster);
    const fits = [
      ...cluster.slice(0, FIT_CLUSTER_LEAD),
      ...ranked.filter(item => !inCluster(item)),
      ...cluster.slice(FIT_CLUSTER_LEAD),
    ].map(item => item.sentence);
    const joined = fine.length <= 1 ? fine.join('') : tr('recommendation.list.and', '{first} and {last}', {
      first:fine.slice(0, -1).join(', '),
      last:fine[fine.length - 1],
    });

    const rankedReasons = ordered(
      (Array.isArray(recommendation.positiveReasons) ? recommendation.positiveReasons : [])
        .filter(Boolean),
      REASON_TIERS, REASON_TIERS.length);
    const rankedCautions = ordered(
      (Array.isArray(recommendation.cautions) ? recommendation.cautions : []).filter(Boolean),
      CAUTION_TIERS, CAUTION_TIERS.length);

    const reasons = messages(rankedReasons, translate, extra);
    // Hard stops always lead: nothing below them changes the decision.
    const cautions = messages(recommendation.hardStops, translate, extra)
      .concat(messages(rankedCautions, translate, extra));
    const rawUnknowns = (Array.isArray(recommendation.unknowns) ? recommendation.unknowns : [])
      .filter(Boolean);
    const unknowns = messages(rawUnknowns, translate, extra);
    // The unknown codes encode their owner: dog.* gaps are fixable by the
    // user right now (profile fields); everything else is trail data.
    const isDogGap = item => typeof item.code === 'string' && item.code.startsWith('dog.');
    const dogGapFields = rawUnknowns
      .filter(isDogGap)
      .map(item => item.code.split('.')[1])
      .filter(Boolean);
    // A gap the card turns into "add Eddie's weight" must not also sit above
    // it as a finding: said twice, one missing field reads as two problems.
    // Callers that render the prompt list these instead of `unknowns`.
    const trailUnknowns = messages(rawUnknowns.filter(item => !isDogGap(item)), translate, extra);

    return {
      confidenceLabel:confidenceWords(recommendation.confidence, translate) || null,
      dogGapFields,
      trailUnknownCount:rawUnknowns.length - dogGapFields.length,
      conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
      tone:category.tone,
      score:Number.isFinite(recommendation.score) ? recommendation.score : null,
      confidence:recommendation.confidence || 'unknown',
      scoringVersion:recommendation.scoringVersion || 'unknown',
      evidenceTier:recommendation.evidenceTier || 'unknown',
      contextLabel:dogName
        ? tr('recommendation.context.dog', 'Recommendation for {name}', { name:dogName })
        : tr('recommendation.context.guest', 'Unpersonalized planning view'),
      dogName:dogName || null,
      reasons:reasons.slice(0, 4),
      cautions:cautions.slice(0, 4),
      // P0-1: the full ordered breakdown, most negative first. Unlike the two
      // summary lists above this is not truncated, the acceptance criterion
      // is that it lists exactly the factors the score was computed from.
      breakdownFor:subject,
      breakdown:breakdownFactors,
      breakdownRows:rows,
      fine,
      // The same positives as sentences, for a card that lists them rather
      // than folding them into fineLine.
      fits,
      fineLine:fine.length
        ? tr('recommendation.fine.line', 'Fine for {name}: {items}.', { name:subject, items:joined })
        : null,
      // The floor is not a factor the reader can act on, and rendering its
      // positive impact alongside the costs reads as a bonus. It closes the
      // list as a note instead, explaining why the total stops where it does.
      breakdownNote:floorEntry ? translatedMessage(floorEntry, translate, extra) : null,
      unknowns:unknowns.slice(0, 5),
      trailUnknowns:trailUnknowns.slice(0, 5),
      additionalUnknowns:Math.max(0, unknowns.length - 5),
      heroSummary:dogName
        ? tr('recommendation.hero.dog', '{conclusion} for {name}.', {
          conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
          name:dogName,
        })
        : tr('recommendation.hero.guest', '{conclusion} in an unpersonalized planning view.', {
          conclusion:tr(`recommendation.category.${recommendation.category || 'unavailable'}`, category.label),
        }),
    };
  }

  // P0-3: what changed when the reader added their own dog. A move of two
  // points or less is not a move, claiming one would be inventing drama the
  // score does not support -- and saying "same score" out loud is a banner
  // whose whole content is that nothing happened. Below the tolerance the
  // callout says nothing at all.
  const SAME_SCORE_TOLERANCE = 2;

  function firstRunCallout(before, after, translate){
    if(!before || !after) return null;
    if(!Number.isFinite(before.score) || !Number.isFinite(after.score)) return null;
    if(!before.forName || !after.forName || before.forName === after.forName) return null;

    const tr = (key, fallback, vars) => {
      if(typeof translate === 'function'){
        const value = translate(key, vars);
        if(value && value !== key) return value;
      }
      let output = fallback;
      for(const name of Object.keys(vars || {})) output = output.split(`{${name}}`).join(vars[name]);
      return output;
    };

    if(Math.abs(after.score - before.score) <= SAME_SCORE_TOLERANCE) return null;
    return tr('recommendation.firstRun.moved',
      'Was {beforeScore}% for {before} · now {afterScore}% for {name}. See why below.',
      { beforeScore:before.score, before:before.forName, afterScore:after.score, name:after.forName });
  }

  return Object.freeze({ CATEGORY, SAME_SCORE_TOLERANCE, present, translatedMessage, firstRunCallout });
});
;

// ---- recommendation-guides.js ----
(function(root, factory){
  const api = factory();
  if(typeof module === 'object' && module.exports) module.exports = api;
  if(root) root.DoloPawsRecommendationGuides = api;
})(typeof window !== 'undefined' ? window : globalThis, function(){
  'use strict';

  const GUIDES = Object.freeze({
    heat:Object.freeze({
      id:'heat',
      href:'guides/heat-overheating.html',
      label:'Recognising overheating early',
      summary:'Know the early signs and when to stop.',
    }),
    water:Object.freeze({
      id:'water',
      href:'guides/water-for-dogs-on-trail.html',
      label:'Water for dogs on alpine trails',
      summary:'Plan the full supply when reliable water is not confirmed.',
    }),
    paws:Object.freeze({
      id:'paws',
      href:'guides/paw-protection.html',
      label:'Protecting paw pads on rocky terrain',
      summary:'Prepare for rough surfaces and recognise pad damage.',
    }),
    exposure:Object.freeze({
      id:'exposure',
      href:'safety-guide.html',
      label:'Dog hiking safety guide',
      summary:'Review turn-back decisions and emergency preparation.',
    }),
    livestock:Object.freeze({
      id:'livestock',
      href:'guides/livestock-guard-dogs.html',
      label:'Livestock and guardian dogs',
      summary:'Cross grazed pasture calmly and avoid confrontations.',
    }),
    altitude:Object.freeze({
      id:'altitude',
      href:'guides/altitude-with-your-dog.html',
      label:'Hiking safely at altitude',
      summary:'Plan for thinner air, rapid weather changes and lingering snow.',
    }),
    lifts:Object.freeze({
      id:'lifts',
      href:'guides/dogs-on-cable-cars.html#chairlifts',
      label:'Lifts with your dog: open chairs and closed cabins',
      summary:'Why an open chairlift is a different risk from a gondola, and who can ride one.',
    }),
  });

  function guideId(code){
    code = String(code || '');
    if(/^(?:trail\.(?:heat|shade)|conditions\.heat)\./.test(code)) return 'heat';
    if(/^trail\.water\./.test(code)) return 'water';
    if(/^trail\.(?:surface-hazards|terrain|descent)\./.test(code)) return 'paws';
    if(/^trail\.exposure\./.test(code)) return 'exposure';
    if(/^trail\.livestock\./.test(code)) return 'livestock';
    if(/^trail\.altitude\./.test(code)) return 'altitude';
    if(/^trail\.lift\./.test(code)) return 'lifts';
    return null;
  }

  function select(recommendation, maximum){
    const candidates = []
      .concat(Array.isArray(recommendation && recommendation.hardStops)
        ? recommendation.hardStops : [])
      .concat(Array.isArray(recommendation && recommendation.cautions)
        ? recommendation.cautions : []);
    const selected = [];
    const seen = new Set();
    const cap = Number.isFinite(maximum) ? Math.max(0, maximum) : 2;
    for(const caution of candidates){
      const id = guideId(caution && caution.code);
      if(!id || seen.has(id)) continue;
      seen.add(id);
      selected.push(GUIDES[id]);
      if(selected.length >= cap) break;
    }
    return selected;
  }

  function selectIds(ids, maximum){
    const selected = [];
    const seen = new Set();
    const cap = Number.isFinite(maximum) ? Math.max(0, maximum) : 3;
    for(const id of Array.isArray(ids) ? ids : []){
      if(!GUIDES[id] || seen.has(id)) continue;
      seen.add(id);
      selected.push(GUIDES[id]);
      if(selected.length >= cap) break;
    }
    return selected;
  }

  return Object.freeze({ GUIDES, select, selectIds });
});
;

// ---- trail-recommendation.js ----
(function(){
  'use strict';

  function esc(value){
    return String(value == null ? '' : value).replace(/[&<>"']/g, char => ({
      '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;',
    })[char]);
  }

  function tr(key, fallback, vars){
    if(typeof window.t === 'function'){
      const value = window.t(key, vars);
      if(value && value !== key) return value;
    }
    let output = fallback;
    for(const name of Object.keys(vars || {})){
      output = output.split(`{${name}}`).join(vars[name]);
    }
    return output;
  }

  function list(items, emptyText){
    if(!items.length) return `<p class="recommendation-empty">${esc(emptyText)}</p>`;
    return `<ul>${items.map(item => `<li>${esc(item)}</li>`).join('')}</ul>`;
  }

  // P0-1: the breakdown sits directly under the Match %, headed in the dog's
  // name, and lists every factor the score was computed from in descending
  // order of impact. Each cost row carries both the points and the reason, so
  // no factor ever reads as a bare label or a bare number. What cost nothing
  // is folded into one closing line rather than listed sentence by sentence.
  function breakdown(view, tr){
    if(!view.breakdown.length) return '';
    const rows = (view.breakdownRows || view.breakdown).map(factor => {
      const points = factor.impact < 0
        ? `\u2212${Math.abs(factor.impact)}`
        : factor.impact > 0
          ? `+${factor.impact}`
          : factor.kind === 'stop'
            ? tr('recommendation.breakdown.stop', 'stop')
            : factor.kind === 'caution'
              ? tr('recommendation.breakdown.note', 'note')
              : tr('recommendation.breakdown.noCost', 'fine');
      const tone = factor.impact < 0 || factor.kind === 'stop' ? 'cost' : 'clear';
      return `<li><span class="recommendation-factor-impact is-${tone}">${esc(points)}</span>` +
        `<span class="recommendation-factor-reason">${esc(factor.message)}</span></li>`;
    }).join('');
    const fine = view.fineLine
      ? `<p class="recommendation-fine">${esc(view.fineLine)}</p>`
      : '';
    const note = view.breakdownNote
      ? `<p class="recommendation-breakdown-note">${esc(view.breakdownNote)}</p>`
      : '';
    const title = view.score === null
      ? tr('recommendation.breakdown.titleNoScore', 'Why this score for {name}', { name:view.breakdownFor })
      : tr('recommendation.breakdown.title', 'Why {score}% for {name}', { score:view.score, name:view.breakdownFor });
    return `<section class="recommendation-breakdown">` +
      `<h3>${esc(title)}</h3>` +
      (rows ? `<ol class="recommendation-factors">${rows}</ol>` : '') +
      fine + note + `</section>`;
  }

  function sections(entries){
    const rendered = entries
      .filter(([, items]) => items.length)
      .map(([title, items]) =>
        `<section><h3>${esc(title)}</h3>${list(items)}</section>`)
      .join('');
    return rendered ? `<div class="recommendation-columns">${rendered}</div>` : '';
  }

  function renderGuideLinks(recommendation){
    const root = document.getElementById('trailGuideLinks');
    const api = window.DoloPawsRecommendationGuides;
    if(!root || !api){ return; }
    const safetyRows = document.getElementById('dogSafetyRows');
    if(!safetyRows) return;
    safetyRows.querySelectorAll('[data-guide-id]').forEach(row => {
      const guide = api.GUIDES[row.dataset.guideId];
      if(!guide || row.querySelector('.safety-row-guide')) return;
      const copy = row.querySelector('.safety-row-copy') || row;
      copy.insertAdjacentHTML('beforeend',
        `<a class="safety-row-guide" href="${esc(guide.href)}">${esc(tr(`recommendation.guide.${guide.id}.label`, guide.label))} <span aria-hidden="true">→</span></a>`
      );
    });
    root.hidden = true;
    root.innerHTML = '';
  }

  function currentTrail(){
    const raw = new URLSearchParams(window.location.search).get('id');
    const id = (window.DoloPawsRegionalData && window.DoloPawsRegionalData.resolveTrailId ? window.DoloPawsRegionalData.resolveTrailId(raw) : (raw));
    return typeof trails !== 'undefined' ? trails.find(trail => trail.id === id) : null;
  }

  // P0-3: what the reader saw before they added their dog, so the change can
  // be shown rather than explained.
  let previousRender = null;
  let pendingCallout = null;

  function guestProfile(){
    try{
      const raw = window.localStorage.getItem('dolopaws-pending-dog-profile');
      const profile = raw ? JSON.parse(raw) : null;
      return profile && typeof profile === 'object' && profile.name ? profile : null;
    }catch(error){
      return null;
    }
  }

  function subjectFor(profile){
    if(!profile) return {};
    return typeof effectiveOverrides === 'function'
      ? effectiveOverrides(profile, null)
      : profile;
  }

  function renderDecision(trail, profile){
    const root = document.getElementById('recommendationDecision');
    const api = window.DoloPawsRecommendationDecision;
    if(!root || !api || typeof recommendTrail !== 'function') return;
    // The weather arrives after the first paint, so the card scores without it
    // and re-scores when it lands. Absent conditions stay 'not-provided'
    // rather than being guessed at.
    // Official area warnings arrive from trail-hazards.js on their own clock;
    // they ride alongside the weather so the engine can note them at no cost.
    const warnings = Array.isArray(window.OrmaAreaWarnings) ? window.OrmaAreaWarnings : [];
    const conditions = window.DoloPawsCurrentConditions || warnings.length
      ? { status:'not-provided', ...(window.DoloPawsCurrentConditions || {}), warnings }
      : undefined;
    const recommendation = recommendTrail(trail, subjectFor(profile), conditions);
    const view = api.present(recommendation, {
      dogName:profile && profile.name,
      translate:window.t,
    });
    const score = view.score === null ? '' : `<span class="recommendation-score">${view.score}%</span>`;
    // Confidence rides next to the score as a calm data-completeness chip;
    // the audit trail (scoring version, trail-data gaps) lives in the
    // evidence disclosure, not on the card face.
    const chip = view.confidenceLabel
      ? `<span class="recommendation-confidence recommendation-confidence--${esc(view.confidence)}">${esc(view.confidenceLabel)}</span>`
      : '';
    // Dog-side gaps are the one thing the reader can fix right now, the
    // card face turns them into a profile CTA instead of a caveat.
    const canOpenWizard = !!(window.DoloPawsWizard && typeof window.DoloPawsWizard.open === 'function');
    const gapCta = !view.dogName
      ? (canOpenWizard
        ? `<p class="recommendation-gaps"><button type="button" class="recommendation-add-dog" data-add-dog>${esc(tr('recommendation.gap.addDog', 'Add your dog to sharpen this score →'))}</button></p>`
        : `<p class="recommendation-gaps"><a href="onboarding.html">${esc(tr('recommendation.gap.addDog', 'Add your dog to sharpen this score →'))}</a></p>`)
      : view.dogGapFields.length
        ? `<p class="recommendation-gaps"><a href="account.html">${esc(tr('recommendation.gap.fields', 'Add {name}’s {fields} to sharpen this score →', {
            name:view.dogName,
            fields:friendlyList(view.dogGapFields),
          }))}</a></p>`
        : '';

    const thisRender = { score:view.score, forName:view.breakdownFor };
    pendingCallout = api.firstRunCallout(previousRender, thisRender, window.t);
    previousRender = thisRender;

    root.className = `recommendation-decision recommendation-decision--${view.tone}`;
    root.dataset.scoringVersion = view.scoringVersion;
    root.dataset.recommendationCategory = recommendation.category || '';
    root.dataset.recommendationConfidence = view.confidence;
    root.innerHTML =
      '<div class="recommendation-head">' +
        '<div>' +
          `<div class="recommendation-kicker">${esc(view.contextLabel)}</div>` +
          `<h2>${esc(view.conclusion)} ${score} ${chip}</h2>` +
          gapCta +
        '</div>' +
      '</div>' +
      // A heading over a line explaining that there is nothing to say is the
      // opposite of crisp. A section with nothing behind it is dropped; what
      // ORMA has not established stays in the unknowns disclosure below.
      breakdown(view, tr) +
      // The breakdown already carries every reason and caution with its
      // points; repeating them as two more lists doubled the card. The lists
      // only appear when an engine gives no breakdown to show instead.
      (view.breakdown.length ? '' : sections([
        [tr('recommendation.reasons.title', 'Why it may fit'), view.reasons],
        [tr('recommendation.cautions.title', 'Cautions'), view.cautions],
      ])) +
      '<div class="recommendation-actions" aria-label="Trail actions">' +
        `<button type="button" data-recommendation-save>${esc(tr('recommendation.action.save', 'Save trail'))}</button>` +
        `<button type="button" data-recommendation-compare>${esc(tr('recommendation.action.compare', 'Add to comparison'))}</button>` +
        `<button type="button" data-recommendation-download disabled>${esc(tr('recommendation.action.offlineUnavailable', 'Offline map unavailable'))}</button>` +
      '</div>';
    root.hidden = false;

    renderGuideLinks(recommendation);
    const hero = document.getElementById('heroVerdict');
    if(hero) hero.textContent = view.heroSummary;
    wireActions(root, trail);
  }

  function friendlyList(items){
    const labels = items.map(item => tr(
      `recommendation.profileField.${item}`,
      item
    ));
    if(labels.length <= 1) return labels.join('');
    return tr('recommendation.list.and', '{first} and {last}', {
      first:labels.slice(0, -1).join(', '),
      last:labels[labels.length - 1],
    });
  }

  function wireActions(root, trail){
    const save = root.querySelector('[data-recommendation-save]');
    const originalSave = document.getElementById('detailSaveBtn');
    const syncSave = () => {
      save.textContent = originalSave && originalSave.classList.contains('saved')
        ? tr('recommendation.action.saved', 'Saved')
        : tr('recommendation.action.save', 'Save trail');
      save.setAttribute('aria-pressed', String(!!(
        originalSave && originalSave.classList.contains('saved')
      )));
    };
    save.disabled = !originalSave;
    if(originalSave){
      syncSave();
      save.addEventListener('click', () => originalSave.click());
      new MutationObserver(syncSave).observe(originalSave, {
        attributes:true,
        childList:true,
        subtree:true,
      });
    }

    const compare = root.querySelector('[data-recommendation-compare]');
    const comparison = window.DoloPawsComparisonState;
    if(comparison){
      const available = trails.map(item => item.id);
      const selected = comparison.load(localStorage, available);
      const alreadySelected = selected.includes(trail.id);
      compare.textContent = alreadySelected
        ? tr('recommendation.action.openComparison', 'Open comparison')
        : tr('recommendation.action.compare', 'Add to comparison');
      compare.addEventListener('click', () => {
        let ids = comparison.load(localStorage, available);
        if(!ids.includes(trail.id)) ids = comparison.toggle(ids, trail.id);
        comparison.save(localStorage, ids);
        window.location.href = ids.length >= 2
          ? comparison.compareHref(ids)
          : 'browse-trails.html';
      });
    }else{
      compare.disabled = true;
    }

    const download = root.querySelector('[data-recommendation-download]');
    const originalDownload = document.getElementById('offlineDownloadBtn');
    const offlinePanel = document.getElementById('offlinePackagePanel');
    const enableDownload = () => {
      if(!offlinePanel || offlinePanel.hidden) return;
      download.disabled = false;
      download.textContent = tr('recommendation.action.download', 'Download offline map');
    };
    if(window.DoloPawsOffline && originalDownload){
      if(offlinePanel){
        enableDownload();
        new MutationObserver(enableDownload).observe(offlinePanel, { attributes:true });
      }
      window.DoloPawsOffline.availablePackage(trail.id).then(manifest => {
        if(!manifest) return;
        enableDownload();
      }).catch(() => {});
      download.addEventListener('click', () => {
        if(!download.disabled) originalDownload.click();
      });
    }
  }

  async function renderCurrent(){
    const trail = currentTrail();
    if(!trail) return;
    let profile = null;
    if(window.DoloPawsAuth && window.DoloPawsAuth.currentUser){
      try { profile = await window.DoloPawsAuth.getDogProfile(); } catch(error){}
    }
    // No account yet is not the same as no dog. A guest who added one scores
    // against it here and on every other trail, until they choose to save.
    if(!profile) profile = guestProfile();
    renderDecision(trail, profile);
    const add = document.getElementById('recommendationDecision');
    const trigger = add && add.querySelector('[data-add-dog]');
    if(trigger){
      // Opened in place, and told to come back here rather than to a payoff
      // screen listing other trails.
      trigger.addEventListener('click', () => {
        window.DoloPawsWizard.open(null, { returnToPage:true });
      });
    }
    if(pendingCallout){
      // A visible change, once, so the reader sees the score move rather than
      // finding a different number where the old one was.
      add.classList.add('is-rescored');
      window.setTimeout(() => add.classList.remove('is-rescored'), 1400);
      pendingCallout = null;
    }
  }

  renderCurrent();
  if(!window.DoloPawsAuthReady){
    window.addEventListener('dolopaws-auth-ready', renderCurrent, { once:true });
  }
  window.addEventListener('dolopaws-auth-changed', renderCurrent);
  window.addEventListener('dolopaws-dog-profile-saved', renderCurrent);
  window.addEventListener('dolopaws-conditions-ready', renderCurrent);
  window.addEventListener('orma-area-warnings-ready', renderCurrent);
})();
;
